		{name: "tidb revoke on function", sql: "REVOKE EXECUTE ON FUNCTION db.f FROM 'u'@'%';", dialect: spec.DialectTiDB, wantFeature: "revoke.option.routine_object", wantReason: spec.UnsupportedVendorBoundaryReason, wantKind: "ddl"},
		// Index ALGORITHM/LOCK clauses, procedure parameters, sequence table options.
		{name: "mysql create index lock algorithm", sql: "CREATE INDEX ix ON t (c) ALGORITHM=INPLACE LOCK=NONE;", dialect: spec.DialectMySQL, wantFeature: "create_index.option.lock_algorithm", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "tidb drop index lock algorithm", sql: "DROP INDEX ix ON t LOCK=SHARED;", dialect: spec.DialectTiDB, wantFeature: "drop_index.option.lock_algorithm", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql create procedure params", sql: "CREATE PROCEDURE p(IN x INT) SELECT 1;", dialect: spec.DialectMySQL, wantFeature: "create_procedure.option.params", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "tidb create sequence table option", sql: "CREATE SEQUENCE s COMMENT 'x';", dialect: spec.DialectTiDB, wantFeature: "create_sequence.option.comment", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		// Per-spec account auth clauses and placement-policy REPLACE — the field
		// census surface that previously completed silently.
		{name: "mysql create user identified", sql: "CREATE USER u IDENTIFIED BY 'x';", dialect: spec.DialectMySQL, wantFeature: "create_user.option.identified", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql alter user identified", sql: "ALTER USER u IDENTIFIED BY 'x';", dialect: spec.DialectMySQL, wantFeature: "alter_user.option.identified", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql alter user dual password", sql: "ALTER USER u IDENTIFIED BY 'x' RETAIN CURRENT PASSWORD;", dialect: spec.DialectMySQL, wantFeature: "alter_user.option.dual_password", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql alter user current dual password", sql: "ALTER USER USER() IDENTIFIED BY 'x' RETAIN CURRENT PASSWORD;", dialect: spec.DialectMySQL, wantFeature: "alter_user.option.dual_password", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "tidb create placement policy or replace", sql: "CREATE OR REPLACE PLACEMENT POLICY p1 PRIMARY_REGION='us-east-1' REGIONS='us-east-1';", dialect: spec.DialectTiDB, wantFeature: "create_placement_policy.option.or_replace", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		// Field-conditional statement markers closed in the sixth round.
		{name: "mysql union parenthesized select into", sql: "SELECT 1 UNION (SELECT 2 INTO OUTFILE '/tmp/x.txt');", dialect: spec.DialectMySQL, wantFeature: "select_into", wantReason: spec.UnsupportedUnauditedReason, wantKind: "unknown"},
		{name: "mysql union nested list select into", sql: "SELECT 1 UNION ((SELECT 2 INTO OUTFILE '/tmp/y.txt') UNION SELECT 3);", dialect: spec.DialectMySQL, wantFeature: "select_into", wantReason: spec.UnsupportedUnauditedReason, wantKind: "unknown"},
		{name: "mysql set global", sql: "SET GLOBAL sql_mode = 'STRICT_TRANS_TABLES';", dialect: spec.DialectMySQL, wantFeature: "set_global", wantReason: spec.UnsupportedUnauditedReason, wantKind: "unknown"},
		{name: "mysql set atat global", sql: "SET @@global.max_connections = 100;", dialect: spec.DialectMySQL, wantFeature: "set_global", wantReason: spec.UnsupportedUnauditedReason, wantKind: "unknown"},
		{name: "tidb set global", sql: "SET GLOBAL tidb_enable_noop = 1;", dialect: spec.DialectTiDB, wantFeature: "set_global", wantReason: spec.UnsupportedUnauditedReason, wantKind: "unknown"},
		{name: "mysql create table replace select", sql: "CREATE TABLE t (id INT) REPLACE SELECT 1 AS id;", dialect: spec.DialectMySQL, wantFeature: "create_table.option.on_duplicate", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql create table ignore select", sql: "CREATE TABLE t (id INT) IGNORE SELECT 1 AS id;", dialect: spec.DialectMySQL, wantFeature: "create_table.option.on_duplicate", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		{name: "mysql drop hypo index", sql: "DROP HYPO INDEX ix ON t;", dialect: spec.DialectMySQL, wantFeature: "drop_index.option.hypo_index", wantReason: spec.UnsupportedVendorBoundaryReason, wantKind: "ddl"},
		{name: "tidb drop hypo index", sql: "DROP HYPO INDEX ix ON t;", dialect: spec.DialectTiDB, wantFeature: "drop_index.option.hypo_index", wantReason: spec.UnsupportedUnauditedReason, wantKind: "ddl"},
		// The CLUSTERED|NONCLUSTERED primary-key type is a modeled fact on
		// TiDB (drives PKIsHandle determination); under MySQL the same syntax
		// stays a vendor boundary on the primary-key index.
		{name: "mysql inline primary key nonclustered", sql: "CREATE TABLE t (id INT PRIMARY KEY NONCLUSTERED);", dialect: spec.DialectMySQL, wantFeature: "create_table.index.option.primary_key_type", wantReason: spec.UnsupportedVendorBoundaryReason, wantKind: "ddl"},
		{name: "mysql table primary key clustered", sql: "CREATE TABLE t (id INT, PRIMARY KEY (id) CLUSTERED);", dialect: spec.DialectMySQL, wantFeature: "create_table.index.option.primary_key_type", wantReason: spec.UnsupportedVendorBoundaryReason, wantKind: "ddl"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			result, err := AuditSQL(context.Background(), Request{
				SQL:        tc.sql,
				Dialect:    tc.dialect,
				ConfigPath: configPath,
			})
			if !errors.Is(err, ErrUnsupportedStatement) {
				t.Fatalf("expected ErrUnsupportedStatement, got %v", err)
			}
			if len(result.Statements) != 1 {
				t.Fatalf("expected the recognized statement retained, got %#v", result.Statements)
			}
			stmt := result.Statements[0]
			if stmt.Index != 0 || stmt.Kind != tc.wantKind {
				t.Fatalf("expected retained statement kind=%s index=0, got %#v", tc.wantKind, stmt)
			}
			if stmt.RawSQL == "" || stmt.NormalizedSQL == "" {
				t.Fatalf("expected statement identity preserved, got %#v", stmt)
			}
			if stmt.Coverage.Status != report.CoverageIncomplete {
				t.Fatalf("expected statement coverage incomplete, got %#v", stmt.Coverage)
			}
			if len(stmt.Findings) != 0 {
				t.Fatalf("expected no fabricated findings, got %#v", stmt.Findings)
			}
			if result.Coverage.Status != report.CoverageIncomplete {
				t.Fatalf("expected aggregate coverage incomplete, got %q", result.Coverage.Status)
			}
			if result.Verdict != report.VerdictReview {
				t.Fatalf("expected review verdict floor, got %q", result.Verdict)
			}
			var found *spec.UnsupportedDetail
			for i := range result.Unsupported {
				if result.Unsupported[i].Feature == tc.wantFeature {
					found = &result.Unsupported[i]
				}
			}
			if found == nil {
				t.Fatalf("expected unsupported feature %q, got %#v", tc.wantFeature, result.Unsupported)
			}
			if found.Reason != tc.wantReason {
				t.Fatalf("expected reason %q, got %q", tc.wantReason, found.Reason)
			}
			if tc.wantMetadata != nil && !reflect.DeepEqual(found.Metadata, tc.wantMetadata) {
				t.Fatalf("expected metadata %#v, got %#v", tc.wantMetadata, found.Metadata)
			}
			for _, d := range result.Diagnostics {
				if strings.Contains(d.Reason, "INVISIBLE") || strings.Contains(d.Reason, "chk") ||
					strings.Contains(d.Reason, "POLICY") || strings.Contains(d.Reason, "stmt") {
					t.Fatalf("diagnostic leaks statement text: %#v", d)
				}
			}
		})
	}
}

// TestAuditSQLT03UnsupportedFeatureReasonPairs locks the exact
// (index, feature, reason) association on mixed-gap statements: a vendor
// boundary and an unaudited gap on the same statement must keep their own
// reasons instead of being interchangeable.
func TestAuditSQLT03UnsupportedFeatureReasonPairs(t *testing.T) {
	t.Parallel()
	configPath := writeAllRulesDisabledPolicy(t)

	cases := []struct {
		name      string
		sql       string
		dialect   spec.Dialect
		wantIndex int
		want      [][2]string
	}{
		{name: "mysql mixed column uniqueness", sql: "CREATE TABLE t (id INT UNIQUE GLOBAL, c INT UNIQUE);", dialect: spec.DialectMySQL, want: [][2]string{
			{"create_table.column.unique", spec.UnsupportedUnauditedReason},
			{"create_table.column.unique_global", spec.UnsupportedVendorBoundaryReason},
		}},
		{name: "mysql alter add list index global and check", sql: "ALTER TABLE t ADD (c INT, UNIQUE KEY uk (c) GLOBAL, CHECK (c > 0));", dialect: spec.DialectMySQL, want: [][2]string{
			// The CHECK member is audited since T12; only the GLOBAL
			// index modifier remains a vendor boundary.
			{"alter_table.add_index.index.global", spec.UnsupportedVendorBoundaryReason},
		}},
		{name: "mysql unsupported second statement", sql: "ALTER TABLE t ADD COLUMN c INT; CREATE SEQUENCE s;", dialect: spec.DialectMySQL, wantIndex: 1, want: [][2]string{
			{"create_sequence", spec.UnsupportedVendorBoundaryReason},
		}},
		// Index member forms (prefix, expression, descending, multi-valued)
		// and TiDB GLOBAL graduated to member-level audited facts in T10-R2 —
		// they emit compat findings/gaps, never unsupported entries.
		{name: "mysql create view combined options", sql: "CREATE ALGORITHM=TEMPTABLE DEFINER='a'@'%' SQL SECURITY INVOKER VIEW v (a) AS SELECT 1 WITH LOCAL CHECK OPTION;", dialect: spec.DialectMySQL, want: [][2]string{
			{"create_view.option.check_option", spec.UnsupportedUnauditedReason},
			{"create_view.option.definer", spec.UnsupportedUnauditedReason},
			{"create_view.option.sql_security", spec.UnsupportedUnauditedReason},
			{"create_view.option.view_algorithm", spec.UnsupportedUnauditedReason},
			{"create_view.option.view_columns", spec.UnsupportedUnauditedReason},
			{"create_view.option.view_query_shape", spec.UnsupportedUnauditedReason},
		}},
		{name: "mysql grant combined options", sql: "GRANT SELECT(a) ON db.t TO 'u'@'%' WITH GRANT OPTION;", dialect: spec.DialectMySQL, want: [][2]string{
			{"grant.option.column_privileges", spec.UnsupportedUnauditedReason},
			{"grant.option.with_grant", spec.UnsupportedUnauditedReason},
			{"grant.unaudited_targets", spec.UnsupportedUnauditedReason},
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			result, err := AuditSQL(context.Background(), Request{
				SQL:        tc.sql,
				Dialect:    tc.dialect,
				ConfigPath: configPath,
			})
			if !errors.Is(err, ErrUnsupportedStatement) {
				t.Fatalf("expected ErrUnsupportedStatement, got %v", err)
			}
			got := make([][2]string, 0, len(result.Unsupported))
			for _, u := range result.Unsupported {
				if u.Index != tc.wantIndex {
					t.Fatalf("expected unsupported entry bound to statement %d, got %#v", tc.wantIndex, u)
				}
				got = append(got, [2]string{u.Feature, u.Reason})
			}
			sort.Slice(got, func(i, j int) bool { return got[i][0] < got[j][0] })
			want := append([][2]string{}, tc.want...)
			sort.Slice(want, func(i, j int) bool { return want[i][0] < want[j][0] })
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("expected exact (feature,reason) pairs %#v, got %#v", want, got)
			}
		})
	}
}

// TestAuditSQLT03RecognizedOutOfSurfaceStaysComplete locks the counter-examples:
// ordinary read-only EXPLAIN, session-scope PREPARE/DEALLOCATE, and the
// TiDB-audited placement-policy alter stay complete — only execution-capable or
// unaudited forms flip coverage.
func TestAuditSQLT03RecognizedOutOfSurfaceStaysComplete(t *testing.T) {
	t.Parallel()
	configPath := writeAllRulesDisabledPolicy(t)

	cases := []struct {
		name    string
		sql     string
		dialect spec.Dialect
	}{
		{name: "tidb plain explain", sql: "EXPLAIN DELETE FROM t;", dialect: spec.DialectTiDB},
		{name: "mysql plain explain", sql: "EXPLAIN SELECT id FROM t;", dialect: spec.DialectMySQL},
		{name: "tidb prepare deallocate", sql: "PREPARE s FROM 'SELECT 1'; DEALLOCATE PREPARE s;", dialect: spec.DialectTiDB},
		{name: "tidb alter placement policy", sql: "ALTER TABLE t PLACEMENT POLICY=p;", dialect: spec.DialectTiDB},
		{name: "mysql plain create table", sql: "CREATE TABLE t (id INT PRIMARY KEY);", dialect: spec.DialectMySQL},
		{name: "mysql create table generated column supported", sql: "CREATE TABLE t (a INT, b INT GENERATED ALWAYS AS (a+1) STORED);", dialect: spec.DialectMySQL},
		{name: "tidb plain create table", sql: "CREATE TABLE t (id INT PRIMARY KEY);", dialect: spec.DialectTiDB},
		{name: "mysql drop table", sql: "DROP TABLE t;", dialect: spec.DialectMySQL},
		{name: "mysql drop procedure", sql: "DROP PROCEDURE p;", dialect: spec.DialectMySQL},
		{name: "mysql alter add list column only", sql: "ALTER TABLE t ADD (c INT);", dialect: spec.DialectMySQL},
		{name: "mysql alter add list index", sql: "ALTER TABLE t ADD (c INT, UNIQUE KEY uk (c));", dialect: spec.DialectMySQL},
		{name: "mysql alter add list index only", sql: "ALTER TABLE t ADD (UNIQUE KEY uk (id));", dialect: spec.DialectMySQL},
		{name: "mysql alter add list foreign key", sql: "ALTER TABLE t ADD (c INT, FOREIGN KEY (c) REFERENCES p(id));", dialect: spec.DialectMySQL},
		{name: "tidb alter add list check", sql: "ALTER TABLE t ADD (c INT, CHECK (c > 0));", dialect: spec.DialectTiDB},
		{name: "mysql alter add list primary key only", sql: "ALTER TABLE t ADD (PRIMARY KEY (c));", dialect: spec.DialectMySQL},
		{name: "mysql drop user single", sql: "DROP USER u1;", dialect: spec.DialectMySQL},
		{name: "tidb drop sequence single", sql: "DROP SEQUENCE s1;", dialect: spec.DialectTiDB},
		{name: "mysql create index plain", sql: "CREATE INDEX ix ON t (c);", dialect: spec.DialectMySQL},
		{name: "mysql alter user single", sql: "ALTER USER u;", dialect: spec.DialectMySQL},
		{name: "mysql create user single", sql: "CREATE USER u;", dialect: spec.DialectMySQL},
		{name: "mysql create table foreign key plain", sql: "CREATE TABLE t (a INT, FOREIGN KEY (a) REFERENCES p(id));", dialect: spec.DialectMySQL},
		{name: "tidb alter add foreign key plain", sql: "ALTER TABLE t ADD FOREIGN KEY (c) REFERENCES p(id);", dialect: spec.DialectTiDB},
		{name: "mysql create table partitioned plain", sql: "CREATE TABLE t (id INT) PARTITION BY RANGE (id) (PARTITION p0 VALUES LESS THAN (10));", dialect: spec.DialectMySQL},
		{name: "mysql plain select", sql: "SELECT 1;", dialect: spec.DialectMySQL},
		{name: "mysql plain union", sql: "SELECT 1 UNION SELECT 2;", dialect: spec.DialectMySQL},
		{name: "mysql plain create view", sql: "CREATE VIEW v AS SELECT id FROM t;", dialect: spec.DialectMySQL},
		{name: "tidb plain create view", sql: "CREATE VIEW v AS SELECT id FROM t;", dialect: spec.DialectTiDB},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			result, err := AuditSQL(context.Background(), Request{
				SQL:        tc.sql,
				Dialect:    tc.dialect,
				ConfigPath: configPath,
			})
			if err != nil {
				t.Fatalf("expected clean audit, got %v", err)
			}
			if result.Coverage.Status != report.CoverageComplete {
				t.Fatalf("expected complete aggregate coverage, got %q", result.Coverage.Status)
			}
			if len(result.Unsupported) != 0 {
				t.Fatalf("expected no unsupported details, got %#v", result.Unsupported)
			}
		})
	}
}

// TestAuditSQLT03MySQLPlacementAlterIsVendorBoundary proves the TiDB-only
// placement-policy alter action is a vendor boundary under MySQL even though
// TiDB audits the same action at notice level.
func TestAuditSQLT03MySQLPlacementAlterIsVendorBoundary(t *testing.T) {
	t.Parallel()
	configPath := writeAllRulesDisabledPolicy(t)

	result, err := AuditSQL(context.Background(), Request{
		SQL:        "ALTER TABLE t PLACEMENT POLICY=p;",
		Dialect:    spec.DialectMySQL,
		ConfigPath: configPath,
	})
	if !errors.Is(err, ErrUnsupportedStatement) {
		t.Fatalf("expected ErrUnsupportedStatement, got %v", err)
	}
	if len(result.Unsupported) != 1 || result.Unsupported[0].Feature != "alter_table.placement_policy" {
		t.Fatalf("expected alter_table.placement_policy unsupported detail, got %#v", result.Unsupported)
	}
	if result.Unsupported[0].Reason != spec.UnsupportedVendorBoundaryReason {
		t.Fatalf("expected vendor-boundary reason, got %q", result.Unsupported[0].Reason)
	}
}

// TestAuditSQLT03UnsupportedAndParserErrorCoexist proves one batch can carry
// both diagnostic classes: a recognized-unsupported statement, a genuine parse
// failure, and an audited statement coexist without either being reclassified.
func TestAuditSQLT03UnsupportedAndParserErrorCoexist(t *testing.T) {
	t.Parallel()
	configPath := writeAllRulesDisabledPolicy(t)

	result, err := AuditSQL(context.Background(), Request{
		SQL:        "ALTER TABLE t ADD COLUMN c INT;\nCREATE SEQUENCE seq_boundary START WITH 1;\nTHIS IS NOT SQL;",
		Dialect:    spec.DialectMySQL,
		ConfigPath: configPath,
	})
	if err == nil {
		t.Fatal("expected parse-failure error for invalid tail")
	}
	if len(result.Statements) != 2 {
		t.Fatalf("expected audited and unsupported statements retained, got %#v", result.Statements)
	}
	if result.Statements[0].Coverage.Status != report.CoverageComplete {
		t.Fatalf("expected first statement complete, got %#v", result.Statements[0])
	}
	if result.Statements[1].Coverage.Status != report.CoverageIncomplete {
		t.Fatalf("expected unsupported statement incomplete, got %#v", result.Statements[1])
	}
	if len(result.Unsupported) != 1 || result.Unsupported[0].Feature != "create_sequence" {
		t.Fatalf("expected one create_sequence unsupported detail, got %#v", result.Unsupported)
	}
	var sawParserError, sawUnsupported bool
	for _, d := range result.Diagnostics {
		switch d.Classification {
		case DiagnosticParserError:
			sawParserError = true
		case DiagnosticUnsupportedStatement:
			sawUnsupported = true
		}
	}
	if !sawParserError || !sawUnsupported {
		t.Fatalf("expected parser_error and unsupported_statement diagnostics to coexist, got %#v", result.Diagnostics)
	}
	if result.Coverage.Status != report.CoverageIncomplete {
		t.Fatalf("expected incomplete aggregate coverage, got %q", result.Coverage.Status)
	}
}

internal/application/audit/cross_dialect:
// Package audit verifies cross-dialect DDL coverage classifications.
package audit

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

type ddlCoverageClass string

const (
	ddlCoverageParserError         ddlCoverageClass = "parser_error"
	ddlCoverageUnsupportedBoundary ddlCoverageClass = "unsupported_boundary"
	ddlCoverageNormalizedSilent    ddlCoverageClass = "normalized_silent"
	ddlCoverageFindingCovered      ddlCoverageClass = "finding_covered"
)

type ddlCensusCase struct {
	SQL      string
	Expected ddlCoverageClass
}

type ddlCensusResult struct {
	Name           string
	Dialect        string
	ParseOK        bool
	Kind           string
	Unsupported    bool
	UnsupportedFea string
	DDLOperation   string
	FindingRuleIDs []string
	Classification ddlCoverageClass
}

type ddlCensusSummary struct {
	Dialect             string
	Total               int
	FindingCovered      int
	NormalizedSilent    int
	UnsupportedBoundary int
	ParserError         int
	Unclassified        int
}

func summarizeDDLCensusResults(dialect string, results []ddlCensusResult) ddlCensusSummary {
	summary := ddlCensusSummary{Dialect: dialect, Total: len(results)}
	for _, r := range results {
		switch r.Classification {
		case ddlCoverageFindingCovered:
			summary.FindingCovered++
		case ddlCoverageNormalizedSilent:
			summary.NormalizedSilent++
		case ddlCoverageUnsupportedBoundary:
			summary.UnsupportedBoundary++
		case ddlCoverageParserError:
			summary.ParserError++
		default:
			summary.Unclassified++
		}
	}
	return summary
}

func (s ddlCensusSummary) assertArithmetic(t *testing.T) {
	t.Helper()
	sum := s.FindingCovered + s.NormalizedSilent + s.UnsupportedBoundary + s.ParserError + s.Unclassified
	if sum != s.Total {
		t.Fatalf("%s census arithmetic mismatch: total=%d buckets=%d", s.Dialect, s.Total, sum)
	}
}

var mysqlDDLCensusCases = []struct {
	Name     string
	SQL      string
	Expected ddlCoverageClass
}{
	// --- 1. Table lifecycle ---
	{Name: "CREATE TABLE", SQL: "CREATE TABLE users (id bigint primary key)", Expected: ddlCoverageFindingCovered},
	{Name: "CREATE TEMPORARY TABLE", SQL: "CREATE TEMPORARY TABLE tmp_users (id bigint primary key)", Expected: ddlCoverageFindingCovered},
	{Name: "CREATE TABLE LIKE", SQL: "CREATE TABLE users_copy LIKE users", Expected: ddlCoverageFindingCovered},
	{Name: "CREATE TABLE AS SELECT", SQL: "CREATE TABLE users_backup AS SELECT * FROM users", Expected: ddlCoverageFindingCovered},
	{Name: "RENAME TABLE", SQL: "RENAME TABLE users TO users_old", Expected: ddlCoverageFindingCovered},
	{Name: "DROP TABLE", SQL: "DROP TABLE users", Expected: ddlCoverageFindingCovered},
	{Name: "TRUNCATE TABLE", SQL: "TRUNCATE TABLE users", Expected: ddlCoverageFindingCovered},

	// --- 2. ALTER TABLE basics ---
	{Name: "ALTER TABLE ADD COLUMN", SQL: "ALTER TABLE users ADD COLUMN email varchar(255)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE DROP COLUMN", SQL: "ALTER TABLE users DROP COLUMN email", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE MODIFY COLUMN", SQL: "ALTER TABLE users MODIFY COLUMN email varchar(500)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE MODIFY COLUMN EXPLICIT NULLABILITY", SQL: "ALTER TABLE users MODIFY COLUMN email varchar(500) NOT NULL", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE CHANGE COLUMN", SQL: "ALTER TABLE users CHANGE COLUMN email user_email varchar(255)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE RENAME COLUMN", SQL: "ALTER TABLE users RENAME COLUMN email TO user_email", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE RENAME TO", SQL: "ALTER TABLE users RENAME TO members", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE ADD PRIMARY KEY", SQL: "ALTER TABLE users ADD PRIMARY KEY (id)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE DROP PRIMARY KEY", SQL: "ALTER TABLE users DROP PRIMARY KEY", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE ADD INDEX", SQL: "ALTER TABLE users ADD INDEX idx_email (email)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE DROP INDEX", SQL: "ALTER TABLE users DROP INDEX idx_email", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE ADD UNIQUE", SQL: "ALTER TABLE users ADD UNIQUE idx_email (email)", Expected: ddlCoverageFindingCovered},
	{Name: "ALTER TABLE ADD FOREIGN KEY", SQL: "ALTER TABLE orders ADD FOREIGN KEY (user_id) REFERENCES users(id)", Expected: ddlCoverageFindingCovered},
