// Table describes a table-level object.
type Table struct {
	Schema  string `json:"schema,omitempty"`
	Name    string `json:"name"`
	Comment string `json:"comment,omitempty"`
}

// Column describes a table column.
type Column struct {
	Name          string `json:"name"`
	Type          string `json:"type,omitempty"`
	Length        int    `json:"length,omitempty"`
	Charset       string `json:"charset,omitempty"`
	Collation     string `json:"collation,omitempty"`
	Comment       string `json:"comment,omitempty"`
	Unsigned      bool   `json:"unsigned,omitempty"`
	NotNull       bool   `json:"not_null,omitempty"`
	AutoIncrement bool   `json:"auto_increment,omitempty"`
	// HasDefault and DefaultValue mean different facts by source: on the
	// input-AST path HasDefault marks an explicit DEFAULT clause and
	// literals keep their quoting; on the MySQL/TiDB metadata path
	// HasDefault marks a non-NULL COLUMN_DEFAULT and DefaultValue is the
	// stored representation verbatim. Neither may be read as recovering
	// the original declaration, and DefaultIsNull is only asserted by the
	// AST path — a NULL COLUMN_DEFAULT cannot distinguish an omitted
	// clause from an explicit DEFAULT NULL, so the metadata path never
	// sets it.
	HasDefault                bool           `json:"has_default,omitempty"`
	DefaultValue              string         `json:"default_value,omitempty"`
	DefaultKind               string         `json:"default_kind,omitempty"`
	DefaultIsNull             bool           `json:"default_is_null,omitempty"`
	DefaultIsCurrentTimestamp bool           `json:"default_is_current_timestamp,omitempty"`
	OnUpdateCurrentTimestamp  bool           `json:"on_update_current_timestamp,omitempty"`
	GeneratedWhen             string         `json:"generated_when,omitempty"`
	IsIdentity                bool           `json:"is_identity,omitempty"`
	IdentityOptions           map[string]any `json:"identity_options,omitempty"`
	// AutoRandom marks a parsed TiDB AUTO_RANDOM column attribute. MySQL has
	// no such feature, so it is a vendor boundary there (owner T23).
	AutoRandom bool `json:"auto_random,omitempty"`
	// UnextractedOptions names parsed column options the extractor recognized
	// but did not model; see DDL.UnextractedOptions.
	UnextractedOptions []string `json:"unextracted_options,omitempty"`
	// Generated is the internal generated-column fact: nil means no generated
	// attribute; non-nil carries the effective storage (omitted storage is
	// VIRTUAL) and structured expression facts. GeneratedWhen stays the
	// PostgreSQL-side fact and is unrelated.
	Generated *GeneratedColumn `json:"-"`
	// DefaultExpression is the internal expression-default fact: nil means no
	// expression default; a non-nil fact with Known=false is unknown, not an
	// empty reference list.
	DefaultExpression *ExpressionFacts `json:"-"`
	// Visibility is the effective column visibility fact: "visible",
	// "invisible", or empty when the fact is withheld/unresolved. CREATE
	// omission resolves to visible; it is never catalog-declaration presence.
	Visibility string `json:"-"`
	// VisibilityExplicit records that a VISIBLE|INVISIBLE attribute was
	// written. It is declaration presence only, never inferred from catalog
	// normalization.
	VisibilityExplicit bool `json:"-"`
	// DefaultParenthesized records that the default clause carried an
	// authored `DEFAULT (<expr>)` paren wrapper. Internal fact only: TiDB's
	// create-side parens grammar accepts only a bare call (a parenthesized
	// literal is a determined negative there while legal MySQL), and both
	// products require parens for non-literal ALTER SET DEFAULT — the flag
	// is never evidence about the stored value itself.
	DefaultParenthesized bool `json:"-"`
	// DefaultLiteral is the comparable literal identity for a
	// literal-class default: the decoded value bytes plus a literal kind.
	// nil means the identity is unproven or the default is not literal —
	// an empty declared string is a proven empty value, never the unknown
	// sentinel. Source-shaped DefaultValue stays the display field; it is
	// never read as identity (T08-R1). Every source writes this fact with
	// the same decode contract — declaration AST yields decoded values,
	// catalog COLUMN_DEFAULT bytes are already decoded value bytes.
	DefaultLiteral *LiteralDefaultFacts `json:"-"`
}

// LiteralDefaultFacts is the recorded literal identity of a literal-class
// column default. It carries no SQL text, quoting, or expression content —
// only the decoded value bytes and the literal kind. A recorded fact is not
// automatically a *comparable* pair: kind marks the value domain, and the
// comparison additionally requires a proven shared encoding (T08-R2).
type LiteralDefaultFacts struct {
	// Kind names the literal's value domain: "string" or "numeric".
	// Kinds never coerce — a string literal and a numeric literal never
	// prove equality, they prove unproven.
	Kind string
	// Value is the decoded literal value bytes exactly as the source
	// stores them: 'x' → x, '''x''' → 'x', 'O''Reilly' → O'Reilly on both
	// sides; a DECIMAL catalog may carry scale-normalized text (1.00)
	// while the AST integer carries canonical digits — same kind does not
	// prove a shared encoding.
	Value string
}

// Literal kinds. Only kinds whose cross-source value domain is provable
// without type coercion are named; encoding comparability is the
// comparison's domain check, not implied here (T08-R2).
const (
	LiteralDefaultString  = "string"
	LiteralDefaultNumeric = "numeric"
)

// CloneLiteralDefaultFacts deep-copies a literal-identity fact. Both fields
// are value types, so a nil-safe struct copy is the whole clone.
func CloneLiteralDefaultFacts(in *LiteralDefaultFacts) *LiteralDefaultFacts {
	if in == nil {
		return nil
	}
	out := *in
	return &out
}

// Partition boundary literal kinds. Only value domains that compare across
// the declaration/catalog boundary without coercion are named; anything
// else stays "expression" with its structured facts — never compared equal
// by identity text.
const (
	PartitionBoundNumeric    = "numeric"
	PartitionBoundString     = "string"
	PartitionBoundNull       = "null"
	PartitionBoundExpression = "expression"
	// PartitionBoundMaxValue marks a MAXVALUE item inside a COLUMNS bound
	// tuple — position-preserving, so `(10,MAXVALUE)` stays a two-item row
	// whose second element is +∞ rather than collapsing the whole bound to
	// a scalar tail. A row composed entirely of MAXVALUE items normalizes
	// back to the scalar PartitionBound.MaxValue sentinel.
	PartitionBoundMaxValue = "maxvalue"
)

// BoundLiteral is one comparable datum inside a partition boundary clause:
// a literal kind plus its canonical value text (numeric digits or decoded
// string bytes — never the authored quoting), or the structured identity
// facts of a non-literal bound item. A Kind outside the comparable set
// proves nothing about equality: two expressions are never equated by this
// model.
type BoundLiteral struct {
	Kind       string           `json:"kind,omitempty"`
	Value      string           `json:"value,omitempty"`
	Expression *ExpressionFacts `json:"expression,omitempty"`
}

// PartitionBound is one member's declared VALUES clause. Kind is
// "less_than" for RANGE(-family) members and "in" for LIST(-family)
// members; MaxValue marks the LESS THAN MAXVALUE sentinel. Rows keeps the
// authored tuple grouping — one row per IN-tuple, one row for LESS THAN —
// with the literal items inside each row in authored order. A nil Bound on
// PartitionDef means the member declared no VALUES clause (HASH/KEY
// members carry none) — never confused with an unparseable clause, which
// leaves the row items unproven instead.
type PartitionBound struct {
	Kind     string `json:"kind,omitempty"`
	MaxValue bool   `json:"max_value,omitempty"`
	// Default marks the MariaDB-compatible `VALUES IN (DEFAULT)` clause —
	// an empty Rows with Kind "in" is this form, never an unprojected
	// tuple list.
	Default bool             `json:"default,omitempty"`
	Rows    [][]BoundLiteral `json:"rows,omitempty"`
}

// PartitionDef is one declared partition member: its name, its declared
// boundary clause when the method carries one, and the subpartition mark
// that keeps member-level operations unproven on that member. The model
// never fabricates a boundary — a member whose clause exists but whose
// items cannot be projected keeps Bound with unproven rows.
type PartitionDef struct {
	Name           string          `json:"name,omitempty"`
	Bound          *PartitionBound `json:"bound,omitempty"`
	Subpartitioned bool            `json:"subpartitioned,omitempty"`
}

// PartitionScheme is a partitioning declaration in normalized form — the
// payload of an ALTER ... PARTITION BY action: the method (same lowercase
// vocabulary as DDL.PartitionType), the COLUMNS member names, the
// partitioning expression's structured identity for expr methods, the
// authored PARTITIONS n count, the explicit member definitions, and the
// subpartition/interval marks that keep the member space unproven.
type PartitionScheme struct {
	Type           string           `json:"type,omitempty"`
	Columns        []string         `json:"columns,omitempty"`
	Expr           *ExpressionFacts `json:"expression,omitempty"`
	Count          *uint64          `json:"count,omitempty"`
	Defs           []PartitionDef   `json:"defs,omitempty"`
	Subpartitioned bool             `json:"subpartitioned,omitempty"`
	SubType        string           `json:"sub_type,omitempty"`
	Interval       bool             `json:"interval,omitempty"`
}

// ClonePartitionDefs deep-copies a member-definition list; bound rows and
// expression facts are value/reference copies per item.
func ClonePartitionDefs(in []PartitionDef) []PartitionDef {
	if in == nil {
		return nil
	}
	out := make([]PartitionDef, len(in))
	for i, def := range in {
		out[i] = def
		if def.Bound != nil {
			bound := *def.Bound
			if def.Bound.Rows != nil {
				bound.Rows = make([][]BoundLiteral, len(def.Bound.Rows))
				for j, row := range def.Bound.Rows {
					bound.Rows[j] = make([]BoundLiteral, len(row))
					for k, item := range row {
						bound.Rows[j][k] = item
						if item.Expression != nil {
							bound.Rows[j][k].Expression = CloneExpressionFacts(item.Expression)
						}
					}
				}
			}
			out[i].Bound = &bound
		}
	}
	return out
}

// ClonePartitionScheme deep-copies a partitioning declaration.
func ClonePartitionScheme(in *PartitionScheme) *PartitionScheme {
	if in == nil {
		return nil
	}
	out := *in
	out.Columns = append([]string(nil), in.Columns...)
	out.Expr = CloneExpressionFacts(in.Expr)
	out.Defs = ClonePartitionDefs(in.Defs)
	if in.Count != nil {
		count := *in.Count
		out.Count = &count
	}
	return &out
}

// IndexKind identifies the semantic class of an index declaration.
type IndexKind string

// Supported index kinds.
const (
	IndexKindUnknown   IndexKind = "unknown"
	IndexKindPrimary   IndexKind = "primary"
	IndexKindSecondary IndexKind = "secondary"
	IndexKindUnique    IndexKind = "unique"
	IndexKindFulltext  IndexKind = "fulltext"
	IndexKindSpatial   IndexKind = "spatial"
	IndexKindVector    IndexKind = "vector"
	IndexKindColumnar  IndexKind = "columnar"
)

// IndexKeyPartKind classifies one index member row.
type IndexKeyPartKind string

// Supported member kinds. "column" binds a named table column; "expression"
// is a functional key part carrying structured expression identity facts;
// "unmodeled" is a member row the source could not classify (e.g. a named
// member with a NULL catalog collation).
const (
	IndexKeyPartColumn     IndexKeyPartKind = "column"
	IndexKeyPartExpression IndexKeyPartKind = "expression"
	IndexKeyPartUnmodeled  IndexKeyPartKind = "unmodeled"
)

// IndexKeyPart is one index member with its source semantics preserved:
// ordinal position inside the index, which column it binds or which
// expression identity it carries, the explicit prefix length when authored/
// cataloged, and the declared or cataloged sort direction. The aggregate
// marks (PrefixParts/DescParts/ExpressionCount/MultiValuedParts/
// UnmodeledKeyParts) are derived from this list — SetKeyParts keeps both in
// sync so a member position can never disagree with its count.
type IndexKeyPart struct {
	Ordinal      int              `json:"ordinal"`
	Kind         IndexKeyPartKind `json:"kind"`
	Column       string           `json:"column,omitempty"`
	PrefixLength *int             `json:"prefix_length,omitempty"`
	Descending   bool             `json:"descending,omitempty"`
	// DirectionUnknown marks a classified member (column or expression)
	// whose sort direction the source could not prove — e.g. a provider
	// catalog row with a NULL or unrecognized COLLATION. The member keeps
	// its kind and identity; only the direction answer is withheld, so the
	// index's key ordering stays unproven for comparisons.
	DirectionUnknown bool `json:"direction_unknown,omitempty"`
	// Expression carries the member's structured identity on expression
	// parts: fingerprint for sameness, References for the column
	// dependencies, Functions/TopForm for the governed shape. nil on
	// column/unmodeled parts.
	Expression *ExpressionFacts `json:"expression,omitempty"`
	// MultiValued marks the MySQL multi-valued member form
	// CAST(… AS … ARRAY); the member also has Kind=expression.
	MultiValued bool `json:"multi_valued,omitempty"`
	// MultiValuedCastType records the normalized cast-target family a
	// multi-valued member declares: signed, unsigned, char, binary, date,
	// time, datetime, decimal, double, float, json, year, vector — or ""
	// when the member is not multi-valued or the target could not be
	// classified. The member-legality check applies the product's allowed
	// cast family to it (MySQL and TiDB allow disjoint subsets).
	MultiValuedCastType string `json:"multi_valued_cast_type,omitempty"`
	// MultiValuedCastLengthSet records that the authored cast target
	// carried an explicit length — char and binary targets require one on
	// both products (the unspecified-length form answers 1235).
	MultiValuedCastLengthSet bool `json:"multi_valued_cast_length_set,omitempty"`
}

// SetKeyParts installs the member list and derives every aggregate mark from
// it, so count fields can never drift from the member facts.
func (i *Index) SetKeyParts(parts []IndexKeyPart) {
	i.KeyParts = parts
	i.ExpressionCount, i.PrefixParts, i.DescParts, i.MultiValuedParts, i.UnmodeledKeyParts, i.DirectionUnknownParts = 0, 0, 0, 0, 0, 0
	i.HasExpressionKeys = false
	for _, part := range parts {
		switch part.Kind {
		case IndexKeyPartExpression:
			i.ExpressionCount++
			i.HasExpressionKeys = true
			if part.MultiValued {
				i.MultiValuedParts++
			}
		case IndexKeyPartUnmodeled:
			i.UnmodeledKeyParts++
		}
		if part.PrefixLength != nil {
			i.PrefixParts++
		}
		if part.Descending {
			i.DescParts++
		}
		if part.DirectionUnknown {
			i.DirectionUnknownParts++
		}
	}
}

// CloneKeyParts deep-copies the member list; ExpressionFacts are reference
// counts and strings, so a slice copy per part is the whole clone.
func CloneKeyParts(in []IndexKeyPart) []IndexKeyPart {
	if in == nil {
		return nil
	}
	out := make([]IndexKeyPart, len(in))
	for i, part := range in {
		out[i] = part
		if part.PrefixLength != nil {
			length := *part.PrefixLength
			out[i].PrefixLength = &length
		}
		if part.Expression != nil {
			facts := *part.Expression
			facts.References = append([]ColumnReference(nil), part.Expression.References...)
			facts.Functions = append([]string(nil), part.Expression.Functions...)
			facts.Features = append([]string(nil), part.Expression.Features...)
			out[i].Expression = &facts
		}
	}
	return out
}

// Index describes an index declaration.
type Index struct {
	Name              string         `json:"name"`
	Kind              IndexKind      `json:"kind,omitempty"`
	Columns           []string       `json:"columns,omitempty"`
	KeyParts          []IndexKeyPart `json:"key_parts,omitempty"`
	Cardinality       *int64         `json:"cardinality,omitempty"`
	AccessMethod      string         `json:"access_method,omitempty"`
	IncludedColumns   []string       `json:"included_columns,omitempty"`
	HasPredicate      bool           `json:"has_predicate,omitempty"`
	HasExpressionKeys bool           `json:"has_expression_keys,omitempty"`
	ExpressionCount   int            `json:"expression_count,omitempty"`
	// PrefixParts/DescParts count column-prefix lengths and descending key
	// parts parsed on the index but not yet modeled for audit semantics.
	PrefixParts int `json:"prefix_parts,omitempty"`
	DescParts   int `json:"desc_parts,omitempty"`
	// MultiValuedParts counts CAST(… AS … ARRAY) key parts — the MySQL
	// multi-valued index member form. Those parts are also expression key
	// parts (ExpressionCount/HasExpressionKeys still count them); the
	// mark exists so coverage and version applicability can name the
	// multi-valued aspect without inspecting expression contents.
	MultiValuedParts int `json:"multi_valued_parts,omitempty"`
	// Visibility is the effective index visibility fact: "visible",
	// "invisible", or "" when no fact was established. Provider-loaded
	// members carry the catalog answer; declared members carry the authored
	// attribute or "" when none was written.
	Visibility string `json:"visibility,omitempty"`
	// VisibilityExplicit records that a VISIBLE|INVISIBLE attribute was
	// authored on a declared index path. Provider and post-state members
	// keep this false — state claims the effective fact, not the authored
	// form.
	VisibilityExplicit bool `json:"visibility_explicit,omitempty"`
	// UnmodeledKeyParts counts member rows the model cannot classify as a
	// plain ascending column part (e.g. a NULL or unrecognized COLLATION on
	// a provider-loaded row). Any nonzero count means the member definition
	// is not fully known and the index must not enter ordinary-key
	// comparisons.
	UnmodeledKeyParts int `json:"unmodeled_key_parts,omitempty"`
	// DirectionUnknownParts counts classified members (column or
	// expression kind) whose sort direction the source could not prove.
	// Any nonzero count means the index's key ordering is unproven, so it
	// must not enter ordinary-key comparisons either.
	DirectionUnknownParts int `json:"direction_unknown_parts,omitempty"`
	// Global marks the TiDB-only GLOBAL index modifier parsed on table-level
	// UNIQUE/PRIMARY KEY constraints and standalone CREATE INDEX statements.
	// MySQL has no such modifier, so it is a vendor boundary there.
	Global bool `json:"global,omitempty"`
	// PrimaryKeyType records a parsed `PRIMARY KEY … CLUSTERED|NONCLUSTERED`
	// option (TiDB syntax) on a primary-key declaration: "clustered",
	// "nonclustered", or "" when unwritten. It decides whether a declared
	// TiDB single-int PK becomes the row handle (no operable index object)
	// or a real PRIMARY index object.
	PrimaryKeyType string `json:"primary_key_type,omitempty"`
	// UnmodeledOptions lists bounded names of parsed IndexOption members the
	// normalized model does not keep (comment, key_block_size, index_type,
	// with_parser, primary_key_type, split_opt, secondary_engine_attr,
	// columnar_replica). Visibility graduated to Visibility/
	// VisibilityExplicit. Any name present means that parsed aspect is
	// unaudited.
	UnmodeledOptions []string `json:"unmodeled_options,omitempty"`
	// NameUnknown marks a member whose stored name the projection cannot
	// prove — set on every member when StoredIndexNames cannot resolve the
	// collection under the product's auto-naming rule (cross-member suffix
	// effects make per-member honesty all-or-nothing there), and cleared by
	// construction everywhere else: provider names are catalog facts and
	// members merged by an authored ADD/CREATE carry an authored name.
	// Name-keyed lookups must only bind members with a proven name.
	// Internal audit marker; not serialized.
	NameUnknown bool `json:"-"`
}

// Constraint describes a non-index table constraint worth preserving for later rules.
type Constraint struct {
	Type              string   `json:"type"`
	Name              string   `json:"name,omitempty"`
	Columns           []string `json:"columns,omitempty"`
	ReferencedSchema  string   `json:"referenced_schema,omitempty"`
	ReferencedTable   string   `json:"referenced_table,omitempty"`
	ReferencedColumns []string `json:"referenced_columns,omitempty"`
	// UnmodeledParts counts local key parts (foreign keys) that carry more
	// than a plain column name: expression parts, explicit prefix lengths
	// (including zero), and descending parts.
	UnmodeledParts int `json:"unmodeled_parts,omitempty"`
	// UnmodeledReferencedParts is the same count over the referenced
	// IndexPartSpecification list of a foreign key.
	UnmodeledReferencedParts int `json:"unmodeled_referenced_parts,omitempty"`
	// OnDelete/OnUpdate carry the declared referential actions as normalized
	// lowercase tokens (restrict, cascade, set_null, no_action, set_default);
	// an empty string means the clause was not declared.
	OnDelete string `json:"on_delete,omitempty"`
	OnUpdate string `json:"on_update,omitempty"`
	// UnmodeledReferActions counts parsed reference options a foreign key
	// carries that the normalized model does not keep: MATCH clauses. ON
	// DELETE and ON UPDATE are modeled facts in OnDelete/OnUpdate.
	UnmodeledReferActions int `json:"unmodeled_refer_actions,omitempty"`
	// Enforced is the CHECK member's enforcement state: "enforced",
	// "not_enforced", or "" when the state is unproven (provider did not
	// read it, a data-conditional flip could not be decided, or the member
	// lives on an arm where the state is not real). Only CHECK members
	// carry it; other constraint types leave it empty.
	Enforced string `json:"enforced,omitempty"`
	// EnforcedExplicit records that the authored text provably wrote an
	// ENFORCED or NOT ENFORCED clause on this CHECK declaration — a
	// parser-adapted fact read from the member's own clause, never guessed
	// from the Enforced default. It decides the pre-8.0.16 boundary: bare
	// CHECK parses-and-ignores there while an explicit clause refuses
	// 1064.
	EnforcedExplicit bool `json:"enforced_explicit,omitempty"`
	// EnforcedUnproven records that the authored text's enforcement clause
	// could not be attributed to this declaration — the clause text was
	// unavailable or unalignable (comment-split boundaries, multi-action
	// clauses whose elements could not be matched to AST members). It is
	// never set together with a decisive EnforcedExplicit answer: the
	// member's clause stays unproven instead of reading false as a proven
	// clause-free declaration.
	EnforcedUnproven bool `json:"enforced_unproven,omitempty"`
	// Expression records the evaluation-free structural facts of a CHECK
	// member's expression: column references, function names, feature
	// markers, root form, and a structural fingerprint. Raw expression
	// text is never retained. Expression.Known=false means the clause
	// could not be modeled — never an empty-expression claim. A nil
	// pointer means the member carries no modeled expression (all
	// non-CHECK members).
	Expression *ExpressionFacts `json:"expression,omitempty"`
	// InColumn marks a CHECK declared as a column option rather than a
	// table constraint — the catalog member is the same object type but
	// the declared identity binds the owning column.
	InColumn bool `json:"in_column,omitempty"`
	// NameUnknown marks a member whose stored name is unproven — a bare
	// foreign key added through ordered state, where the server derives a
	// catalog name the statement itself does not author. Name-keyed
	// lookups must never bind or disprove on the empty stored name.
	NameUnknown bool `json:"-"`
}

// AlterColumnChange describes statement-local column-change intent.
// These flags are parser-neutral hints about what the ALTER statement touches;
// they do not claim live-schema source truth on their own.
type AlterColumnChange struct {
	TouchesNullability   bool `json:"touches_nullability,omitempty"`
	TouchesDefault       bool `json:"touches_default,omitempty"`
	TouchesAutoIncrement bool `json:"touches_auto_increment,omitempty"`
	// DeclaresPrimaryKey records that this column definition itself writes
	// PRIMARY KEY. It is parser-owned presence, not an added-primary-key
	// post-state, and it stays out of public JSON.
	DeclaresPrimaryKey bool `json:"-"`
}

// AlterColumn describes a column-focused alter payload.
// OldName is only populated when the action targets an existing column name.
// Definition carries the target column shape after the action when available.
// Change carries parser-neutral statement-local relation facts for upcoming
// source-aware alter rules.
type AlterColumn struct {
	OldName    string             `json:"old_name,omitempty"`
	Definition *Column            `json:"definition,omitempty"`
	Change     *AlterColumnChange `json:"change,omitempty"`
}

// AlterIndex describes an index-focused alter payload.
// OldName is only populated when the action targets an existing index name.
// Definition carries the target index shape after the action when available.
type AlterIndex struct {
	OldName    string `json:"old_name,omitempty"`
	Definition *Index `json:"definition,omitempty"`
}

// AlterPosition carries a parsed FIRST|AFTER column-position clause as a
// normalized fact: Kind is "first" or "after" and After is the normalized
// relative column name (empty for "first").
type AlterPosition struct {
	Kind  string `json:"kind"`
	After string `json:"after,omitempty"`
}

// Alter describes a normalized alter action.
// Name is the canonical subject identifier for downstream matching:
// existing-object actions use the pre-change name, pure additions use the
// created object's name, and table-option actions leave it empty.
type Alter struct {
	Action string       `json:"action"`
	Name   string       `json:"name,omitempty"`
	Column *AlterColumn `json:"column,omitempty"`
	Index  *AlterIndex  `json:"index,omitempty"`
	// Constraint carries the declared constraint payload for constraint-bearing
	// alter specs (ADD CONSTRAINT ...) so coverage and rules can see the
	// constraint type even when no index definition is produced.
	Constraint *Constraint `json:"constraint,omitempty"`
	// Constraints carries CHECK members declared inside column definitions
	// of the same alter spec (ADD/MODIFY/CHANGE COLUMN ... CHECK(...)) —
	// the in-column form the catalog stores as a table-level CHECK member.
	Constraints []Constraint      `json:"constraints,omitempty"`
	Options     map[string]string `json:"options,omitempty"`
	// HasColumnPosition records a parsed FIRST|AFTER column-position clause;
	// Position carries the normalized fact (non-nil exactly when
	// HasColumnPosition is true).
	HasColumnPosition bool           `json:"has_column_position,omitempty"`
	Position          *AlterPosition `json:"position,omitempty"`
	// Partitions carries the named partition targets of a partition alter
	// action (DROP/TRUNCATE/EXCHANGE PARTITION), lower-cased as written and
	// in clause order. It is empty for the TRUNCATE PARTITION ALL form —
	// an empty name is never fabricated.
	Partitions []string `json:"partitions,omitempty"`
	// AllPartitions marks the `TRUNCATE PARTITION ALL` form — a distinct
	// modeled fact from an empty Partitions list on the named forms.
	AllPartitions bool `json:"all_partitions,omitempty"`
	// ExchangeTable carries the exchanged counterpart table of
	// EXCHANGE PARTITION ... WITH TABLE x as written; Schema is empty when
	// the clause names an unqualified table.
	ExchangeTable *Table `json:"exchange_table,omitempty"`
	// ExchangeValidation is the effective validation clause of EXCHANGE
	// PARTITION: "without" only when WITHOUT VALIDATION is authored;
	// "with" covers both authored WITH VALIDATION and the absent clause —
	// the AST collapses the two, so "with" never proves the keyword was
	// explicit. The clause is never product-verified compatibility.
	ExchangeValidation string `json:"exchange_validation,omitempty"`
	// PartitionDefs carries the member definitions an ADD PARTITION or
	// REORGANIZE PARTITION ... INTO clause declares, with names and
	// boundary clauses in authored order. nil when the action declares no
	// member definitions (PARTITIONS n / bare forms).
	PartitionDefs []PartitionDef `json:"partition_defs,omitempty"`
	// PartitionCount carries the authored count of `ADD PARTITION
	// PARTITIONS n` and `COALESCE PARTITION n`; nil when the clause names
	// no count. Zero is never authored successfully — a written 0 stays
	// nil here because the AST stores the absent marker the same way.
	PartitionCount *uint64 `json:"partition_count,omitempty"`
	// PartitionScheme carries the new partitioning declaration of the
	// `partition` action (ALTER TABLE ... PARTITION BY ...). nil on every
	// other action.
	PartitionScheme *PartitionScheme `json:"partition_scheme,omitempty"`
	// OrderBy carries the authored ORDER BY column list of the
	// `order_by_columns` action in authored order — structure is captured
	// even though the server does not validate the names (probed:
	// ORDER BY <nonexistent> executes).
	OrderBy []OrderByItem `json:"order_by,omitempty"`
	// UnextractedOptions names parsed table-option clauses that were dropped
	// during extraction; see DDL.UnextractedOptions.
	UnextractedOptions []string `json:"unextracted_options,omitempty"`
}

// OrderByItem is one member of an ALTER TABLE ... ORDER BY declaration —
// the normalized column identity plus its authored direction.
type OrderByItem struct {
	Column string `json:"column"`
	Desc   bool   `json:"desc,omitempty"`
}

// IsPartitionAlterAction reports whether an alter-table action is a
// partition-scoped operation. The online-DDL classifier, coverage, and
// ordered state exclude these from the general modifier matrix because
// partition combinations carry their own adjudication (T14); the set is
// the one canonical vocabulary shared by rules, audit state, and
// coverage.
func IsPartitionAlterAction(action string) bool {
	switch action {
	case "drop_partition", "truncate_partition", "exchange_partition",
		"add_partitions", "reorganize_partition", "coalesce_partitions",
		"partition", "remove_partitioning",
		"rebuild_partition", "check_partitions", "optimize_partition",
		"repair_partition", "import_partition_tablespace", "discard_partition_tablespace":
		return true
	default:
		return false
	}
}

internal/domain/spec/metadata.go:
// Package spec defines normalized statement specifications for rule evaluation.
package spec

import "strings"

// Metadata carries optional non-SQL facts for one statement evaluation.
type Metadata struct {
	Schema      string           `json:"schema,omitempty"`
	Instance    *InstanceFacts   `json:"instance,omitempty"`
	Version     *VersionIdentity `json:"version,omitempty"`
	TargetTable *TableSnapshot   `json:"target_table,omitempty"`
	View        *ViewMetadata    `json:"-"`
	// ExchangeTable is the ordered pre-state projection of the
	// EXCHANGE PARTITION counterpart table — the second object identity
	// the action touches, resolved through the same once-per-key seam as
	// the primary target. nil means the counterpart was never resolved
	// (no exchange action on the statement, or the identity is unknown).
	ExchangeTable *TableSnapshot   `json:"exchange_table,omitempty"`
	Objects       []ObjectSnapshot `json:"objects,omitempty"`

	// TargetTables binds every identity in DDL.TableTargets() to its
	// ordered pre-state projection in source order — the namespace-aware
	// answer for multi-target statements (multi-table DROP, RENAME pairs).
	// A binding's Snapshot is nil when the target's state is unvouched;
	// Ambiguous marks a binding the model could not even decide (a name
	// that could hit either namespace).
	TargetTables []TargetBinding `json:"target_tables,omitempty"`
	// SourceTable is the CREATE TABLE ... LIKE source's ordered pre-state —
	// bound through the same temp-first namespace rule every unqualified
	// read uses. nil when the LIKE source is unvouched (or the statement
	// is not a LIKE create).
	SourceTable *TableSnapshot `json:"source_table,omitempty"`
	// SourceTables binds each CTAS SelectSources entry to its ordered
	// pre-state, aligned 1:1 in source order. A nil element marks an
	// unvouched source; an empty slice means the select named no base
	// table (literal select — no source premise at all).
	SourceTables []*TableSnapshot `json:"source_tables,omitempty"`
	// SchemaTarget binds a schema-scoped statement (CREATE/ALTER/DROP
	// DATABASE|SCHEMA) to its ordered pre-state projection: confirmed
	// schema attributes when the identity is provably present, an empty
	// snapshot when provably absent, and nil when the schema's state is
	// unvouched (or the statement is not schema-scoped). A name-less
	// ALTER DATABASE binds the request's trusted schema — never a
	// connection guess.
	SchemaTarget *ObjectSnapshot `json:"schema_target,omitempty"`
}

// MetadataSchemaTarget is the ordered schema binding accessor rules use —
// nil-safe over a missing metadata block or a non-schema statement.
func (s Statement) MetadataSchemaTarget() *ObjectSnapshot {
	if s.Metadata == nil {
		return nil
	}
	return s.Metadata.SchemaTarget
}

// TargetBinding is the namespace-aware pre-state answer for one named
// identity: which object the statement's reference binds and what was
// provable about it. Snapshot.Temporary marks the session-local temp
// namespace; Snapshot nil means unvouched; Ambiguous means the binding
// itself could not be decided (never conflated with a proven absence).
type TargetBinding struct {
	Table     Table          `json:"table"`
	Snapshot  *TableSnapshot `json:"snapshot,omitempty"`
	Ambiguous bool           `json:"ambiguous,omitempty"`
}

// InstanceFacts are normalized server-level facts that influence audit behavior.
// Numeric facts pair a value with an explicit Known flag: a zero value is never
// treated as evidence — unknown facts stay unknown so rules can emit bounded
// evidence gaps instead of fabricating a configuration.
type InstanceFacts struct {
	Version string `json:"version,omitempty"`
	// On MySQL, DefaultCharset is character_set_database, not the server default.
	DefaultCharset string `json:"default_charset,omitempty"`
	// Empty server default fields mean unobserved.
	ServerCharset              string `json:"server_charset,omitempty"`
	ServerCollation            string `json:"server_collation,omitempty"`
	DefaultCollationForUTF8MB4 string `json:"default_collation_for_utf8mb4,omitempty"`
	InnoDBLargePrefixEnabled   bool   `json:"innodb_large_prefix_enabled,omitempty"`
	InnoDBLargePrefixKnown     bool   `json:"innodb_large_prefix_known,omitempty"`
	InnoDBDefaultRowFormat     string `json:"innodb_default_row_format,omitempty"`
	InnoDBAdaptiveHashEnabled  bool   `json:"innodb_adaptive_hash_enabled,omitempty"`
	InnoDBPageSizeBytes        int    `json:"innodb_page_size,omitempty"`
	InnoDBPageSizeKnown        bool   `json:"innodb_page_size_known,omitempty"`
	TiDBMaxIndexLengthBytes    int    `json:"tidb_max_index_length,omitempty"`
	TiDBMaxIndexLengthKnown    bool   `json:"tidb_max_index_length_known,omitempty"`

	// TiDBEnableClusteredIndex is the session-observed
	// tidb_enable_clustered_index value (on/off/int_only). A declared
	// TiDB primary key without CLUSTERED|NONCLUSTERED stores under this
	// session default — an empty value means the mode was not probed, so
	// the handle answer stays unknown rather than inheriting the
	// product's ON default as a guess. TiDB only; never populated on
	// MySQL.
	TiDBEnableClusteredIndex string `json:"tidb_enable_clustered_index,omitempty"`

	// TiDBAlterPrimaryKey is the observed alter-primary-key configuration
	// fact the int_only clustered mode defers to: int_only clusters a
	// single-int PK only while alter-primary-key is disabled. An
	// unobserved fact keeps the int_only handle answer unknown — the
	// Known bit separates "probed false" from "never probed" so a zero
	// value is never read as evidence. TiDB only.
	TiDBAlterPrimaryKey      bool `json:"tidb_alter_primary_key,omitempty"`
	TiDBAlterPrimaryKeyKnown bool `json:"tidb_alter_primary_key_known,omitempty"`

	// RestrictNonStandardKey is the observed
	// restrict_fk_on_non_standard_key value — MySQL 8.4+'s refusal of
	// foreign keys whose referenced columns are covered only by a
	// non-unique index (native 6125, verified 8.4.10 ON; the variable
	// does not exist on 5.7/8.0/TiDB, so an unobserved read resolves the
	// eligibility question by dialect and version instead of guessing a
	// default). The Known bit separates "probed off" from "never probed".
	RestrictNonStandardKey      bool `json:"restrict_non_standard_key,omitempty"`
	RestrictNonStandardKeyKnown bool `json:"restrict_non_standard_key_known,omitempty"`

	// TiDBEnableCheckConstraint is the observed
	// tidb_enable_check_constraint value — TiDB's CHECK runtime switch.
	// OFF means CHECK syntax parses but stores and enforces nothing; ON
	// means CHECK members land and enforce. The Known bit separates
	// "probed off" from "never probed" so an unobserved value resolves to
	// undecidable, never a guessed ON. TiDB only; MySQL never returns the
	// row.
	TiDBEnableCheckConstraint      bool `json:"tidb_enable_check_constraint,omitempty"`
	TiDBEnableCheckConstraintKnown bool `json:"tidb_enable_check_constraint_known,omitempty"`
}

// TableSnapshot is the current metadata-backed shape of a target table.
// Member collections keep their source semantics: a nil Columns marks a
// withheld column set (unknown), while PrimaryKey/Indexes/Constraints treat
// nil as "loaded, absent/empty" — the *Unknown flags below override that
// convention when a projection cannot vouch for those collections.
type TableSnapshot struct {
	Schema       string            `json:"schema,omitempty"`
	Exists       bool              `json:"exists"`
	Table        *Table            `json:"table,omitempty"`
	RelationKind string            `json:"relation_kind,omitempty"`
	View         *ViewSnapshot     `json:"-"`
	Columns      []Column          `json:"columns,omitempty"`
	PrimaryKey   *Index            `json:"primary_key,omitempty"`
	Indexes      []Index           `json:"indexes,omitempty"`
	Constraints  []Constraint      `json:"constraints,omitempty"`
	Options      map[string]string `json:"options,omitempty"`

	// PrimaryKeyIsHandle marks a TiDB PKIsHandle table: the single-integer
	// clustered primary key is the row handle, so no operable PRIMARY index
	// object exists even though the catalog synthesizes a PRIMARY row for
	// display (ALTER INDEX `PRIMARY` answers 1176 there). A non-handle TiDB
	// primary key — NONCLUSTERED or clustered on a non-single-int shape —
	// is a real index object (VISIBLE succeeds, INVISIBLE reports 3522).
	// MySQL never sets it: PRIMARY is always an index object there.
	PrimaryKeyIsHandle bool `json:"-"`

	// PrimaryKeyHandleUnknown marks that the snapshot cannot prove the
	// TiDB handle answer either way — e.g. the TIDB_INDEXES clustered row
	// was absent or NULL on the provider path, or a batch-derived PK was
	// declared without CLUSTERED|NONCLUSTERED while the session's
	// tidb_enable_clustered_index mode is unobserved. Consumers must not
	// read PrimaryKeyIsHandle as a determined "real object" then — the
	// PRIMARY-object answer stays unresolved.
	PrimaryKeyHandleUnknown bool `json:"-"`

	// PrimaryKeyClustered marks a TiDB primary key stored clustered —
	// PKIsHandle single-int PKs and common-handle PKs alike. The fact
	// answers the DROP PRIMARY KEY premise (TiDB refuses the drop with
	// 8200 on every clustered primary, handle or common-handle); it is
	// deliberately separate from PrimaryKeyIsHandle, which answers the
	// PRIMARY-object addressability question instead. MySQL never sets
	// it: a MySQL primary key drops cleanly.
	PrimaryKeyClustered bool `json:"-"`

	// PrimaryKeyClusteredUnknown marks that the snapshot cannot prove the
	// clustered-storage answer either way — the same evidence gaps that
	// leave the handle answer unknown. Consumers must not guess drop
	// executability under it.
	PrimaryKeyClusteredUnknown bool `json:"-"`

	// PrimaryKeyUnknown/IndexesUnknown/ConstraintsUnknown mark member
	// collections the snapshot cannot vouch for (a derived-incomplete
	// projection). Rules must treat them as unknown — never as confirmed
	// absence. Internal audit markers; not part of serialized output.
	PrimaryKeyUnknown  bool `json:"-"`
	IndexesUnknown     bool `json:"-"`
	ConstraintsUnknown bool `json:"-"`

	// IndexOrderCatalog records that Indexes slice order is the catalog /
	// declaration order (a table wholly created in-batch). Provider-loaded
	// indexes arrive name-sorted, which is never the role-selection order,
	// so provider snapshots keep this false and multi-candidate primary-role
	// determinations degrade to a bounded gap instead of guessing Indexes[0].
	IndexOrderCatalog bool `json:"-"`

	// IndexNamesUnknown marks a vouched Indexes collection whose stored
	// index names cannot all be proven — a derived create-table shape
	// where StoredIndexNames could not resolve every member under the
	// product's auto-naming rule (expression first member, authored-name
	// collision), or the post-state of a name-keyed transition whose target
	// or outcome could not be proven under the prior name space. The flag
	// covers the member name space only: the PK object's stored name has
	// its own provability marker (PrimaryKey.NameUnknown), which the
	// transitions that may have moved it set separately. The members stay
	// known; name-based consumers must treat lookups as unresolved rather
	// than reading an unmatched name as confirmed absence. Internal audit
	// marker; not serialized.
	IndexNamesUnknown bool `json:"-"`

	// Partitioned reports whether the table is partitioned — the fact TiDB's
	// GLOBAL index option and the partition-action applicability checks are
	// gated on. nil means the fact was never loaded (offline statement or a
	// pre-expansion provider), not "not partitioned".
	Partitioned *bool `json:"-"`

	// PartitionType is the observed PARTITION_METHOD normalized lowercase
	// (`range`, `list`, `hash`, `key`, `linear hash`, `linear key`,
	// `range columns`, `list columns`). nil means the catalog probe never
	// answered — never read as "no type". The fact is vacuous on a
	// known-non-partitioned table.
	PartitionType *string `json:"-"`

	// PartitionNames is the observed partition-member name list in catalog
	// order. nil means unobserved; a non-nil empty slice is an
	// observed-empty set (a known-non-partitioned table).
	PartitionNames []string `json:"-"`

	// PartitionDescriptions carries the catalog PARTITION_DESCRIPTION
	// text per member, aligned 1:1 with PartitionNames (RANGE keeps the
	// authored bound text like `120`/`'abc'`/`MAXVALUE`, LIST the value
	// list `2,5`, HASH/KEY members carry empty text). nil means
	// unobserved — the fact lives only where names were observed.
	PartitionDescriptions []string `json:"-"`

	// PartitionDefs carries the member directory with boundary clauses in
	// comparable literal form — projected from declared definitions on
	// batch-derived shapes and from the catalog description text on
	// provider shapes, so bound comparisons read one field on either
	// side. nil when the member space was never observed; a member whose
	// bound could not project keeps a clause without rows (unproven —
	// never a claimed-empty boundary).
	PartitionDefs []PartitionDef `json:"-"`

	// Subpartitioned reports that the catalog showed leaf-level member
	// rows (SUBPARTITION_NAME non-NULL). On such tables the top-level
	// member list is not the member space, so PartitionNames stays
	// unobserved; the flag distinguishes that incomplete projection from
	// a simply-unanswered catalog probe.
	Subpartitioned bool `json:"-"`

	// Temporary marks a bound session-local temporary table — an object
	// in the per-session namespace that can shadow a same-named
	// persistent table. Provider snapshots never carry it; only
	// batch-derived bindings produce it.
	Temporary bool `json:"temporary,omitempty"`

	// GlobalTemporary marks a TiDB global-temporary catalog object — a
	// persistent-namespace definition whose rows are transaction-scoped.
	// It lives in the ordinary catalog namespace (plain DROP/ALTER/
	// TRUNCATE/RENAME apply), unlike Temporary's session object.
	GlobalTemporary bool `json:"global_temporary,omitempty"`

	// ColumnsTailUnknown marks that the Columns list is provable only up
	// to its declared prefix — a CTAS destination keeps the declared
	// column definitions but cannot vouch for select-appended members
	// beyond the tail. Consumers must not treat Columns as the complete
	// member set under this flag.
	ColumnsTailUnknown bool `json:"-"`

	// ReferencedBy carries inbound foreign-key edges the batch can prove:
	// child tables created in-batch declaring REFERENCES <this table>.
	// Only derived edges land here — a non-nil empty slice means "no
	// proven inbound edge", nil means none recorded yet.
	ReferencedBy []Table `json:"-"`

	// ReferencedByUnknown marks that the snapshot cannot vouch for
	// inbound references at all — provider snapshots do not load reverse
	// edges, so "no recorded child" on a provider path is unknown, never
	// proven-empty. Consumers (TRUNCATE's 1701 premise) must gap instead
	// of reading an empty ReferencedBy as safe.
	ReferencedByUnknown bool `json:"-"`
}

// HasColumn reports whether the snapshot contains a column by name, case-insensitively.
func (s TableSnapshot) HasColumn(name string) bool {
	return s.FindColumn(name) != nil
}

// FindColumn returns the matching column by name, case-insensitively.
func (s TableSnapshot) FindColumn(name string) *Column {
	if strings.TrimSpace(name) == "" {
		return nil
	}
	for i := range s.Columns {
		if strings.EqualFold(s.Columns[i].Name, name) {
			column := s.Columns[i]
			return &column
		}
	}
	return nil
}

// HasIndex reports whether the snapshot contains an index by name, case-insensitively.
func (s TableSnapshot) HasIndex(name string) bool {
	return s.FindIndex(name) != nil
}

// FindIndex returns the matching secondary/unique/fulltext index by name, case-insensitively.
func (s TableSnapshot) FindIndex(name string) *Index {
	if strings.TrimSpace(name) == "" {
		return nil
	}
	for i := range s.Indexes {
		if strings.EqualFold(s.Indexes[i].Name, name) {
			index := s.Indexes[i]
			return &index
		}
	}
	return nil
}

// FindProvenIndex returns the member whose stored name is both provable
// (!NameUnknown) and equal-folds the authored name — the only member a
// name-keyed lookup may bind. Under IndexNamesUnknown a member kept as a
// fact may carry an unproven projected name; binding it would fabricate a
// hit the stored name space cannot vouch for. The result points into the
// receiver's index slice so identity comparisons (e.g. HolderIndex) work.
func (s TableSnapshot) FindProvenIndex(name string) *Index {
	if strings.TrimSpace(name) == "" {
		return nil
	}
	for i := range s.Indexes {
		if s.Indexes[i].NameUnknown {
			continue
		}
		if strings.EqualFold(s.Indexes[i].Name, name) {
			return &s.Indexes[i]
		}
	}
	return nil
}

// HasUnprovenIndexName reports whether any member's stored name is
// unproven — the granular form of IndexNamesUnknown used by name-keyed
// transitions to tell a provable target from a name space that may hide
// the real stored name.
func (s TableSnapshot) HasUnprovenIndexName() bool {
	for i := range s.Indexes {
		if s.Indexes[i].NameUnknown {
			return true
		}
	}
	return false
}

// IndexNameSpaceUnvouched reports whether the member name space cannot vouch
// every stored name — the collection unread, the whole space unvouched, or
// one member's stored name unproven. Name-keyed consumers share this check
// so they cannot drift on what "the member space is vouched" means.
func (s TableSnapshot) IndexNameSpaceUnvouched() bool {
	return s.IndexesUnknown || s.IndexNamesUnknown || s.HasUnprovenIndexName()
}

// FindForeignKeyConstraint binds a name-keyed foreign-key lookup to a
// proven member of the loaded constraint set (case-insensitive like the
// catalog's foreign-key name space). It returns nil when no member carries
// the name; callers must treat nil under ConstraintsUnknown or an
// unproven member name as "unknown", not absence — a nil Constraints is
// itself a loaded empty set per the collection contract.
func (s TableSnapshot) FindForeignKeyConstraint(name string) *Constraint {
	if strings.TrimSpace(name) == "" {
		return nil
	}
	for i := range s.Constraints {
		if s.Constraints[i].Type != "foreign_key" {
			continue
		}
		if s.Constraints[i].NameUnknown {
			continue
		}
		if strings.EqualFold(s.Constraints[i].Name, name) {
			return &s.Constraints[i]
		}
	}
	return nil
}

// FindCheckConstraint binds a name-keyed CHECK lookup to a proven member of
// the loaded constraint set — the check-namespace counterpart of
// FindForeignKeyConstraint. A nil result under ConstraintsUnknown or an
// unproven member name means "unknown", never confirmed absence.
func (s TableSnapshot) FindCheckConstraint(name string) *Constraint {
	if strings.TrimSpace(name) == "" {
		return nil
	}
	for i := range s.Constraints {
		if s.Constraints[i].Type != "check" {
			continue
		}
		if s.Constraints[i].NameUnknown {
			continue
		}
		if strings.EqualFold(s.Constraints[i].Name, name) {
			return &s.Constraints[i]
		}
	}
	return nil
}

// HasUnprovenCheckName reports whether any CHECK member's stored name is
// unproven — the check arm of an unvouched constraint name space.
func (s TableSnapshot) HasUnprovenCheckName() bool {
	for i := range s.Constraints {
		if s.Constraints[i].Type == "check" && s.Constraints[i].NameUnknown {
			return true
		}
	}
	return false
}

// HasUnprovenForeignKeyName reports whether any foreign-key member's stored
// name is unproven — the granular form of an unvouched constraint name
// space used by name-keyed transitions to tell a provable target from a
// member that may hide the real stored name.
func (s TableSnapshot) HasUnprovenForeignKeyName() bool {
	for i := range s.Constraints {
		if s.Constraints[i].Type == "foreign_key" && s.Constraints[i].NameUnknown {
			return true
		}
	}
	return false
}

// CheckNameSpaceUnvouched reports whether the CHECK member name space
// cannot vouch every stored name — the collection flagged unvouched, or one
// check member's stored name unproven. The check namespace on MySQL/TiDB is
// separate from index names, so only check members participate.
func (s TableSnapshot) CheckNameSpaceUnvouched() bool {
	return s.ConstraintsUnknown || s.HasUnprovenCheckName()
}

// ForeignKeyNameSpaceUnvouched reports whether the foreign-key member name
// space cannot vouch every stored name — the collection flagged
// unvouched, or one member's stored name unproven. Per the collection
// contract at the top of this file a nil Constraints is a loaded empty
// set, never an unread one; providers and projections mark the unread
// case through ConstraintsUnknown. Name-keyed consumers share this check
// so "not found" can never read as confirmed absence.
func (s TableSnapshot) ForeignKeyNameSpaceUnvouched() bool {
	return s.ConstraintsUnknown || s.HasUnprovenForeignKeyName()
}

// HasPrimaryKey reports whether the snapshot currently has a primary key.
func (s TableSnapshot) HasPrimaryKey() bool {
	if s.PrimaryKey != nil {
		return true
	}
	for _, c := range s.Constraints {
		if c.Type == "primary_key" {
			return true
		}
	}
	return false
}

// MetadataStatus identifies the outcome of a metadata object lookup.
type MetadataStatus string

const (
	MetadataStatusConfirmed   MetadataStatus = "confirmed"
	MetadataStatusNotFound    MetadataStatus = "not_found"
	MetadataStatusUnavailable MetadataStatus = "unavailable"
	MetadataStatusAmbiguous   MetadataStatus = "ambiguous"
)

// ObjectSnapshot carries the metadata-validated state of one non-table database object.
type ObjectSnapshot struct {
	Schema              string            `json:"schema,omitempty"`
	Type                string            `json:"type,omitempty"`
	Name                string            `json:"name,omitempty"`
	Status              MetadataStatus    `json:"status,omitempty"`
	Exists              bool              `json:"exists"`
	Attributes          map[string]string `json:"attributes,omitempty"`
	AmbiguousCandidates []string          `json:"ambiguous_candidates,omitempty"`
}

// ObjectLookupRequest describes one object to resolve from live metadata.
type ObjectLookupRequest struct {
	Schema     string
	Type       string
	Name       string
	Qualifiers map[string]string
}

// IsConfirmed reports whether the object was found in live metadata.
func (o ObjectSnapshot) IsConfirmed() bool {
	return o.Status == MetadataStatusConfirmed
}

// IsNotFound reports whether the object was confirmed absent from live metadata.
func (o ObjectSnapshot) IsNotFound() bool {
	return o.Status == MetadataStatusNotFound
}

// IsUnavailable reports whether metadata lookup was not performed or not possible.
func (o ObjectSnapshot) IsUnavailable() bool {
	return o.Status == MetadataStatusUnavailable || o.Status == ""
}

// IsAmbiguous reports whether the object identity could not be uniquely resolved.
func (o ObjectSnapshot) IsAmbiguous() bool {
	return o.Status == MetadataStatusAmbiguous
}

// SafeAttributes returns only non-sensitive attributes from the snapshot.
// Keys matching known sensitive patterns are excluded.
func (o ObjectSnapshot) SafeAttributes() map[string]string {
	if o.Attributes == nil {
		return nil
	}
	safe := make(map[string]string, len(o.Attributes))
	for k, v := range o.Attributes {
		if isSensitiveAttributeKey(k) {
			continue
		}
		safe[k] = v
	}
	return safe
}

// FindObject returns the first ObjectSnapshot matching the given type and name,
// case-insensitively. Returns nil if no match is found.
func (m *Metadata) FindObject(objectType, name string) *ObjectSnapshot {
	if m == nil || len(m.Objects) == 0 {
		return nil
	}
	ot := strings.TrimSpace(strings.ToLower(objectType))
	n := strings.TrimSpace(strings.ToLower(name))
	if ot == "" || n == "" {
		return nil
	}
	for i := range m.Objects {
		if strings.EqualFold(m.Objects[i].Type, objectType) && strings.EqualFold(m.Objects[i].Name, name) {
			snapshot := m.Objects[i]
			return &snapshot
		}
	}
	return nil
}

// FindObjectsByType returns all ObjectSnapshots matching the given type, case-insensitively.
func (m *Metadata) FindObjectsByType(objectType string) []ObjectSnapshot {
	if m == nil || len(m.Objects) == 0 {
		return nil
	}
	var result []ObjectSnapshot
	for i := range m.Objects {
		if strings.EqualFold(m.Objects[i].Type, objectType) {
			result = append(result, m.Objects[i])
		}
	}
	return result
}

// sensitiveAttributeKeys lists attribute keys that must never be projected publicly.
var sensitiveAttributeKeys = map[string]bool{
	"password": true, "secret": true, "token": true, "api_key": true,
	"connection": true, "dsn": true, "connstr": true,
	"body": true, "definition": true, "comment": true, "label": true,
	"query": true, "action_sql": true, "options": true,
}

func isSensitiveAttributeKey(key string) bool {
	return sensitiveAttributeKeys[strings.ToLower(strings.TrimSpace(key))]
}

internal/infrastructure/metadata/mysql/p:
// Package mysqlmeta implements metadata-aware audit adapters over the MySQL protocol.
package mysqlmeta

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"database/sql"
	"fmt"
	"net"
	"strconv"
	"strings"
	"time"
	"unicode"

	gomysql "github.com/go-sql-driver/mysql"

	appaudit "github.com/Fanduzi/DeltaScope/internal/application/audit"
	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
	tidbparser "github.com/Fanduzi/DeltaScope/internal/infrastructure/parser/tidb"
)

// DefaultConnectTimeout is the default timeout for initial metadata connection.
const DefaultConnectTimeout = 5 * time.Second

// ConnectionConfig describes one MySQL-compatible metadata connection.
type ConnectionConfig struct {
	Host           string
	Port           int
	Socket         string
	User           string
	Password       string
	Database       string
	ConnectTimeout time.Duration
	TLSMode        string         // "disabled" (default) or "enabled"
	CACert         *x509.CertPool // pre-parsed CA pool; only used when tls_mode=enabled
}

// connectTimeout returns the configured timeout, defaulting to DefaultConnectTimeout when zero.
func (c ConnectionConfig) connectTimeout() time.Duration {
	if c.ConnectTimeout <= 0 {
		return DefaultConnectTimeout
	}
	return c.ConnectTimeout
}

// Network reports the driver network name for the connection.
func (c ConnectionConfig) Network() string {
	if strings.TrimSpace(c.Socket) != "" {
		return "unix"
	}
	return "tcp"
}

// Address reports the driver address for the connection.
func (c ConnectionConfig) Address() string {
	if strings.TrimSpace(c.Socket) != "" {
		return strings.TrimSpace(c.Socket)
	}
	host := strings.TrimSpace(c.Host)
	if host == "" {
		host = "127.0.0.1"
	}
	port := c.Port
	if port == 0 {
		port = 3306
	}
	return net.JoinHostPort(host, strconv.Itoa(port))
}

// mysqlConfig builds a go-sql-driver/mysql Config from this connection config.
// When TLS is enabled, the TLS config is set directly on the driver config
// rather than using RegisterTLSConfig, avoiding global state accumulation.
func (c ConnectionConfig) mysqlConfig() *gomysql.Config {
	cfg := gomysql.NewConfig()
	cfg.Net = c.Network()
	cfg.Addr = c.Address()
	cfg.User = c.User
	cfg.Passwd = c.Password
	cfg.Collation = "utf8mb4_general_ci"
	cfg.Timeout = c.connectTimeout()
	cfg.InterpolateParams = true

	if strings.TrimSpace(c.Database) != "" {
		cfg.DBName = strings.TrimSpace(c.Database)
	}

	tlsMode := strings.ToLower(strings.TrimSpace(c.TLSMode))
	if tlsMode == "enabled" {
		host := strings.TrimSpace(c.Host)
		if host == "" {
			host = "127.0.0.1"
		}
		tlsCfg := &tls.Config{
			ServerName:         host,
			InsecureSkipVerify: false,
		}
		if c.CACert != nil {
			tlsCfg.RootCAs = c.CACert
		}
		cfg.TLS = tlsCfg
	}

	return cfg
}

func (c ConnectionConfig) DSN() string {
	return c.mysqlConfig().FormatDSN()
}

// OpenDBContext connects to a MySQL-compatible database for metadata reads,
// respecting the caller's context for cancellation and applying the configured
// connect timeout as a deadline. The caller is responsible for closing the
// returned *sql.DB.
func OpenDBContext(ctx context.Context, config ConnectionConfig) (*sql.DB, error) {
	if ctx == nil {
		ctx = context.Background()
	}

	connector, err := gomysql.NewConnector(config.mysqlConfig())
	if err != nil {
		return nil, fmt.Errorf("create metadata connector: %w", err)
	}
	db := sql.OpenDB(connector)

	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	db.SetConnMaxLifetime(5 * time.Minute)
	db.SetConnMaxIdleTime(1 * time.Minute)

	timeoutCtx, cancel := context.WithTimeout(ctx, config.connectTimeout())
	defer cancel()
	if err := db.PingContext(timeoutCtx); err != nil {
		db.Close()
		return nil, fmt.Errorf("ping metadata connection: %w", err)
	}

	return db, nil
}

// OpenDB connects to a MySQL-compatible database for metadata reads using a
// background context. The caller is responsible for closing the returned *sql.DB.
func OpenDB(config ConnectionConfig) (*sql.DB, error) {
	return OpenDBContext(context.Background(), config)
}

// Provider loads metadata facts through a MySQL-compatible SQL connection.
type Provider struct {
	db *sql.DB
}

// NewProvider builds a metadata provider on top of an existing SQL handle.
func NewProvider(db *sql.DB) *Provider {
	return &Provider{db: db}
}

// DetectDialect reads server version information and classifies the SQL dialect.
func (p *Provider) DetectDialect(ctx context.Context) (spec.Dialect, error) {
	var version string
	if err := p.db.QueryRowContext(ctx, `select version()`).Scan(&version); err != nil {
		return "", fmt.Errorf("query server version: %w", err)
	}
	return detectDialectFromVersion(version), nil
}

// FindSchemasForTable lists schemas that currently contain the named table.
func (p *Provider) FindSchemasForTable(ctx context.Context, table string) ([]string, error) {
	rows, err := p.db.QueryContext(ctx, `
		select table_schema
		from information_schema.tables
		where table_name = ?
		order by table_schema
	`, table)
	if err != nil {
		return nil, fmt.Errorf("query schemas for table %s: %w", table, err)
	}
	defer rows.Close()

	schemas := make([]string, 0)
	for rows.Next() {
		var schema string
		if err := rows.Scan(&schema); err != nil {
			return nil, fmt.Errorf("scan schema for table %s: %w", table, err)
		}
		schemas = append(schemas, schema)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate schemas for table %s: %w", table, err)
	}
	return schemas, nil
}

var _ appaudit.MetadataProvider = (*Provider)(nil)

// LoadInstanceFacts reads server-level variables that influence audit behavior.
// Facts that cannot be observed stay unknown (Known=false) rather than being
// back-filled with defaults — rules downgrade to bounded evidence gaps on them.
func (p *Provider) LoadInstanceFacts(ctx context.Context, _ spec.Dialect, _ string) (*spec.InstanceFacts, error) {
	rows, err := p.db.QueryContext(ctx, `
		show variables where Variable_name in
		('version','character_set_database','character_set_server','collation_server','default_collation_for_utf8mb4','innodb_large_prefix','innodb_default_row_format','innodb_adaptive_hash_index','innodb_page_size','tidb_enable_clustered_index','restrict_fk_on_non_standard_key','tidb_enable_check_constraint')
	`)
	if err != nil {
		return nil, fmt.Errorf("query instance facts: %w", err)
	}
	defer rows.Close()

	facts := &spec.InstanceFacts{}
	for rows.Next() {
		var name string
		var value string
		if err := rows.Scan(&name, &value); err != nil {
			return nil, fmt.Errorf("scan instance fact: %w", err)
		}
		switch strings.ToLower(name) {
		case "version":
			facts.Version = value
		case "character_set_database":
			facts.DefaultCharset = value
		case "character_set_server":
			facts.ServerCharset = strings.ToLower(strings.TrimSpace(value))
		case "collation_server":
			facts.ServerCollation = strings.ToLower(strings.TrimSpace(value))
		case "default_collation_for_utf8mb4":
			facts.DefaultCollationForUTF8MB4 = strings.ToLower(strings.TrimSpace(value))
		case "innodb_large_prefix":
			facts.InnoDBLargePrefixEnabled = normalizeOnOff(value)
			facts.InnoDBLargePrefixKnown = true
		case "innodb_default_row_format":
			facts.InnoDBDefaultRowFormat = strings.ToLower(value)
		case "innodb_adaptive_hash_index":
			facts.InnoDBAdaptiveHashEnabled = normalizeOnOff(value)
		case "innodb_page_size":
			if parsed, parseErr := strconv.Atoi(strings.TrimSpace(value)); parseErr == nil && parsed > 0 {
				facts.InnoDBPageSizeBytes = parsed
				facts.InnoDBPageSizeKnown = true
			}
		case "tidb_enable_clustered_index":
			// The session-scoped mode governs unstated-type PK storage on
			// TiDB (v8.5.0 pkg/ddl/create_table.go L1582-1593). MySQL never
			// returns the row, so only the TiDB arm below consumes it.
			facts.TiDBEnableClusteredIndex = strings.ToLower(strings.TrimSpace(value))
		case "restrict_fk_on_non_standard_key":
			// MySQL 8.4+'s non-standard referenced-key refusal gate —
			// absent on 5.7/8.0/TiDB so an unobserved answer is resolved
			// by dialect and version downstream, never by a guessed value.
			facts.RestrictNonStandardKey = normalizeOnOff(value)
			facts.RestrictNonStandardKeyKnown = true
		case "tidb_enable_check_constraint":
			// TiDB's CHECK storage/enforcement switch (v8.5.0) — OFF means
			// CHECK syntax parses but no member is stored or enforced.
			// MySQL never returns the row; unobserved stays Known=false.
			facts.TiDBEnableCheckConstraint = normalizeOnOff(value)
			facts.TiDBEnableCheckConstraintKnown = true
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate instance facts: %w", err)
	}

	// TiDB's index-length bound is the tidb-server max-index-length config,
	// not a system variable. SHOW CONFIG is the supported read path. An
	// actual read failure propagates as a provider error; only a clean read
	// with no usable or no consistent value leaves the fact unknown so the
	// rule reports a bounded gap instead of assuming the 3072 default.
	if strings.Contains(strings.ToLower(facts.Version), "-tidb-") {
		value, known, cfgErr := p.loadTiDBMaxIndexLength(ctx)
		if cfgErr != nil {
			return nil, fmt.Errorf("load tidb max-index-length: %w", cfgErr)
		}
		if known {
			facts.TiDBMaxIndexLengthBytes = value
			facts.TiDBMaxIndexLengthKnown = true
		}
		alterPK, alterKnown, alterErr := p.loadTiDBAlterPrimaryKey(ctx)
		if alterErr != nil {
			return nil, fmt.Errorf("load tidb alter-primary-key: %w", alterErr)
		}
		if alterKnown {
			facts.TiDBAlterPrimaryKey = alterPK
			facts.TiDBAlterPrimaryKeyKnown = true
		}
	} else {
		// A non-TiDB server never consults the clustered-index mode — an
		// unexpected row must not leak a TiDB fact onto MySQL facts.
		facts.TiDBEnableClusteredIndex = ""
	}
	return facts, nil
}

// loadTiDBMaxIndexLength reads the effective tidb-server max-index-length
// configuration via SHOW CONFIG and verifies every matching row — one row
// per tidb-server instance — never trusting the first row alone. Query,
// scan, and iteration failures return an error (provider errors never
// degrade into gaps); an unparsable or non-positive value marks the read
// unverifiable but the stream is still drained, so a later failure still
// surfaces as an error. A clean read ends in zero rows, an invalid value,
// or disagreeing instances → ok=false: the fact stays unknown rather than
// fabricating a bound.
func (p *Provider) loadTiDBMaxIndexLength(ctx context.Context) (value int, ok bool, err error) {
	rows, err := p.db.QueryContext(ctx, `
		show config where Type = 'tidb' and Name = 'max-index-length'
	`)
	if err != nil {
		return 0, false, fmt.Errorf("query tidb max-index-length: %w", err)
	}
	defer rows.Close()

	consistent := true
	for rows.Next() {
		var typ, instance, name, raw string
		if err := rows.Scan(&typ, &instance, &name, &raw); err != nil {
			return 0, false, fmt.Errorf("scan tidb max-index-length: %w", err)
		}
		parsed, parseErr := strconv.Atoi(strings.TrimSpace(raw))
		if parseErr != nil || parsed <= 0 {
			// An unusable value marks the read unverifiable but the stream
			// is still drained to its end: a later scan or iteration
			// failure remains a provider error, never an unknown fact.
			consistent = false
			continue
		}
		if !ok {
			value, ok = parsed, true
		} else if parsed != value {
			consistent = false
		}
	}
	if err := rows.Err(); err != nil {
		return 0, false, fmt.Errorf("iterate tidb max-index-length: %w", err)
	}
	if !consistent {
		return 0, false, nil
	}
	return value, ok, nil
}

// loadTiDBAlterPrimaryKey reads the effective tidb-server
// alter-primary-key configuration via SHOW CONFIG — the fact the int_only
// clustered mode defers to for a single-int PK (upstream: !AlterPrimaryKey
// && isSingleIntPK). Same contract as loadTiDBMaxIndexLength: query, scan,
// and iteration failures propagate as provider errors; every matching row
// (one per tidb-server instance) must parse and agree, otherwise the fact
// stays unknown so a declared unstated-type PK resolves to a bounded gap
// rather than a guessed handle answer.
func (p *Provider) loadTiDBAlterPrimaryKey(ctx context.Context) (value bool, ok bool, err error) {
	rows, err := p.db.QueryContext(ctx, `
		show config where Type = 'tidb' and Name = 'alter-primary-key'
	`)
	if err != nil {
		return false, false, fmt.Errorf("query tidb alter-primary-key: %w", err)
	}
	defer rows.Close()

	consistent := true
	for rows.Next() {
		var typ, instance, name, raw string
		if err := rows.Scan(&typ, &instance, &name, &raw); err != nil {
			return false, false, fmt.Errorf("scan tidb alter-primary-key: %w", err)
		}
		parsed, parseErr := strconv.ParseBool(strings.ToLower(strings.TrimSpace(raw)))
		if parseErr != nil {
			consistent = false
			continue
		}
		if !ok {
			value, ok = parsed, true
		} else if parsed != value {
			consistent = false
		}
	}
	if err := rows.Err(); err != nil {
		return false, false, fmt.Errorf("iterate tidb alter-primary-key: %w", err)
	}
	if !consistent {
		return false, false, nil
	}
	return value, ok, nil
}

// LoadTableSnapshot reads one target table shape from information_schema.
func (p *Provider) LoadTableSnapshot(ctx context.Context, dialect spec.Dialect, schema string, table string) (*spec.TableSnapshot, error) {
	snapshot := &spec.TableSnapshot{
		Schema: schema,
		Exists: false,
	}

	tableRow := p.db.QueryRowContext(ctx, `
		select engine, table_collation, table_comment, auto_increment, row_format, table_rows, table_type
		from information_schema.tables
		where table_schema = ? and table_name = ?
	`, schema, table)

	var engine sql.NullString
	var collation sql.NullString
	var comment sql.NullString
	var autoIncrement sql.NullInt64
	var rowFormat sql.NullString
	var tableRows sql.NullInt64
	var relationType sql.NullString
	if err := tableRow.Scan(&engine, &collation, &comment, &autoIncrement, &rowFormat, &tableRows, &relationType); err != nil {
		if err == sql.ErrNoRows {
			return snapshot, nil
		}
		return nil, fmt.Errorf("query table snapshot: %w", err)
	}

	snapshot.Exists = true
	snapshot.Table = &spec.Table{Name: table, Comment: comment.String}
	switch strings.ToUpper(strings.TrimSpace(relationType.String)) {
	case "BASE TABLE":
		snapshot.RelationKind = "table"
	case "VIEW":
		snapshot.RelationKind = "view"
	}
	snapshot.Options = map[string]string{}
	if engine.Valid {
		snapshot.Options["engine"] = engine.String
	}
	if rowFormat.Valid {
		snapshot.Options["row_format"] = strings.ToUpper(rowFormat.String)
	}
	if autoIncrement.Valid {
		snapshot.Options["auto_increment"] = strconv.FormatInt(autoIncrement.Int64, 10)
	}
	if tableRows.Valid {
		snapshot.Options["table_rows"] = strconv.FormatInt(tableRows.Int64, 10)
	}
	if collation.Valid {
		snapshot.Options["collation"] = collation.String
		snapshot.Options["charset"] = charsetFromCollation(collation.String)
	}

	if err := p.loadColumns(ctx, snapshot); err != nil {
		if snapshot.RelationKind == "view" {
			return nil, safeViewReadError{cause: err}
		}
		return nil, fmt.Errorf("load table %s.%s columns: %w", snapshot.Schema, snapshot.Table.Name, err)
	}
	if snapshot.RelationKind == "view" {
		if err := p.loadView(ctx, snapshot); err != nil {
			return nil, safeViewReadError{cause: err}
		}
		return snapshot, nil
	}
	if err := p.loadIndexes(ctx, snapshot, dialect); err != nil {
		return nil, fmt.Errorf("load table %s.%s indexes: %w", snapshot.Schema, snapshot.Table.Name, err)
	}
	if err := p.loadForeignKeys(ctx, snapshot); err != nil {
		return nil, fmt.Errorf("load table %s.%s foreign keys: %w", snapshot.Schema, snapshot.Table.Name, err)
	}
	if err := p.loadCheckConstraints(ctx, snapshot); err != nil {
		return nil, fmt.Errorf("load table %s.%s check constraints: %w", snapshot.Schema, snapshot.Table.Name, err)
	}
	// Partition facts are loaded on both products — the TiDB GLOBAL index
	// gate and the partition-action applicability checks both consume them.
	if err := p.loadPartitionFacts(ctx, snapshot); err != nil {
		return nil, fmt.Errorf("load table %s.%s partition state: %w", snapshot.Schema, snapshot.Table.Name, err)
	}
	if dialect == spec.DialectTiDB {
		// PrimaryKeyIsHandle is TiDB-only — skip those probes on MySQL.
		if err := p.resolveTiDBPrimaryName(ctx, snapshot); err != nil {
			return nil, fmt.Errorf("load table %s.%s primary-key identity: %w", snapshot.Schema, snapshot.Table.Name, err)
		}
		if err := p.loadTiDBPrimaryKeyHandle(ctx, snapshot); err != nil {
			return nil, fmt.Errorf("load table %s.%s primary-key handle: %w", snapshot.Schema, snapshot.Table.Name, err)
		}
	}

	return snapshot, nil
}

type safeViewReadError struct{ cause error }

func (safeViewReadError) Error() string   { return "view metadata read failed" }
func (e safeViewReadError) Unwrap() error { return e.cause }

func (p *Provider) loadView(ctx context.Context, snapshot *spec.TableSnapshot) error {
	var definition, security, check, updatable, definer sql.NullString
	rows, err := p.db.QueryContext(ctx, `
		select view_definition, security_type, check_option, is_updatable, definer
		from information_schema.views
		where table_schema = ? and table_name = ?
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		snapshot.View = &spec.ViewSnapshot{}
		return nil
	}
	if err := rows.Scan(&definition, &security, &check, &updatable, &definer); err != nil {
		return err
	}
	if rows.Next() {
		return fmt.Errorf("multiple view metadata rows")
	}
	if err := rows.Err(); err != nil {
		return err
	}
	view := &spec.ViewSnapshot{
		Security:    strings.ToLower(strings.TrimSpace(security.String)),
		CheckOption: strings.ToLower(strings.TrimSpace(check.String)),
	}
	if definer.Valid {
		view.DefinerKind = "named"
		view.DefinerPrincipal = definer.String
	}
	if updatable.Valid {
		switch strings.ToUpper(strings.TrimSpace(updatable.String)) {
		case "YES":
			v := true
			view.Updatable = &v
		case "NO":
			v := false
			view.Updatable = &v
		}
	}
	if definition.Valid && strings.TrimSpace(definition.String) != "" {
		parsed, parseErr := tidbparser.ParseViewDefinition(ctx, definition.String)
		if err := ctx.Err(); err != nil {
			return err
		}
		if parseErr != nil {
			view.Definition = &spec.ViewDefinition{SQL: definition.String}
		} else {
			view.Definition = parsed
		}
	}
	snapshot.View = view
	return nil
}

// loadPartitionFacts records the observed partition catalog: whether the
// table is partitioned, the PARTITION_METHOD normalized lowercase
// (`range`, `hash`, `linear key`, `range columns`, ...), and the member
// names in ordinal order. A query the catalog cannot answer keeps every
// fact unknown (nil) — a bounded gap, not a guessed "not partitioned".
// A partitioned table's catalog answer always carries a method, so a
// nil PartitionType under partitioned=true is itself an unobserved fact.
func (p *Provider) loadPartitionFacts(ctx context.Context, snapshot *spec.TableSnapshot) error {
	rows, err := p.db.QueryContext(ctx, `
		select partition_method, partition_name, subpartition_name, partition_description
		from information_schema.partitions
		where table_schema = ? and table_name = ?
			and partition_name is not null
		order by partition_ordinal_position
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		if err == sql.ErrNoRows {
			// An unanswerable catalog probe keeps every partition fact
			// unknown — a bounded gap, never a guessed "not partitioned".
			return nil
		}
		return fmt.Errorf("query partitions: %w", err)
	}
	defer rows.Close()

	names := make([]string, 0)
	descriptions := make([]string, 0)
	seen := make(map[string]bool)
	var method string
	subpartitioned := false
	for rows.Next() {
		var rawMethod, name, subName, description sql.NullString
		if err := rows.Scan(&rawMethod, &name, &subName, &description); err != nil {
			return fmt.Errorf("scan partition for table %s.%s: %w", snapshot.Schema, snapshot.Table.Name, err)
		}
		if method == "" && rawMethod.Valid {
			method = strings.ToLower(rawMethod.String)
		}
		if subName.Valid {
			// Leaf members live in SUBPARTITION_NAME — the top-level
			// projection is not the member space, so the directory is
			// incomplete: MySQL exchanges a leaf name natively.
			subpartitioned = true
		}
		if name.Valid && !seen[name.String] {
			seen[name.String] = true
			names = append(names, name.String)
			// PARTITION_DESCRIPTION is NULL on HASH/KEY members and on
			// unanswerable cells; the recorded text keeps alignment with
			// the name list ("" marks the member whose bound text the
			// catalog never stored).
			text := ""
			if description.Valid {
				text = description.String
			}
			descriptions = append(descriptions, text)
		}
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate partitions for table %s.%s: %w", snapshot.Schema, snapshot.Table.Name, err)
	}

	partitioned := len(names) > 0
	snapshot.Partitioned = &partitioned
	snapshot.Subpartitioned = subpartitioned
	if partitioned {
		if method != "" {
			snapshot.PartitionType = &method
		}
		if !subpartitioned {
			snapshot.PartitionNames = names
			snapshot.PartitionDescriptions = descriptions
			snapshot.PartitionDefs = spec.CatalogPartitionDefs(names, descriptions, method)
		}
		// A subpartitioned catalog is an incomplete projection: the
		// member directory stays unobserved (nil) so no rule can claim
		// a name was proven absent.
	} else {
		// No partition rows is an observed-empty member set on a
		// known-plain table — never confused with an unobserved set.
		snapshot.PartitionNames = []string{}
	}
	return nil
}

// resolveTiDBPrimaryName binds the PK identity to an index-object fold
// under the table's proven constraint presence
// (information_schema.table_constraints — a `PRIMARY KEY` row proves the
// constraint exists; verified on the TiDB v8.5.0 anchor that tidb_pk_type
// cannot answer this — it reports NONCLUSTERED both for PK-less tables and
// for real nonclustered primaries). Presence and attribution are judged
// separately: a proven constraint with zero `primary`-fold rows means the
// PK object was renamed (RENAME INDEX `PRIMARY` TO pk2 is legal on v8.5.0
// and moves the object's stored catalog name while the constraint stays
// PRIMARY), never that no PK exists — the constraint row and the name
// space answer different questions.
//
// Attribution resolves by unique-fold candidacy — a PK object always
// emits a NON_UNIQUE=0 STATISTICS fold (handle tables synthesize one),
// while ordinary members may be unique too, so every unique fold is a
// candidate:
//   - zero candidates means the constraint declares members the index
//     catalog does not carry — presence stays vouched, nothing is
//     attributable;
//   - exactly one candidate can only be the PK object — promote it;
//   - several candidates consult TIDB_INDEXES clustered first: only the
//     PK object's row can read YES, so exactly one clustered candidate
//     identifies it, and more than one contradicts the catalog's own
//     rule — withhold;
//   - with no clustered candidate, the constraint's ordered member
//     sequence (key_column_usage.ordinal_position) separates the object:
//     exactly one ordered match promotes — never the first read in
//     STATISTICS order, and never a same-set-different-order member;
//   - anything else withholds: the constraint still proves presence (a
//     name-unknown placeholder), the surviving candidates demote to kind
//     unknown so unique-overlap consumers never read a maybe-PK fold as
//     an ordinary UNIQUE member, and the handle/clustered answers stay
//     unproven unless every candidate already proved NONCLUSTERED.
//
// A proven-absent constraint (count 0) keeps every fold a secondary; a
// failed constraint or disambiguation probe is a provider failure and
// propagates — issue #79 requires actual query/connection errors to stay
// errors rather than degrade into withheld facts.
func (p *Provider) resolveTiDBPrimaryName(ctx context.Context, snapshot *spec.TableSnapshot) error {
	uniquePositions := make([]int, 0, 2)
	for i := range snapshot.Indexes {
		if snapshot.Indexes[i].Kind == spec.IndexKindUnique {
			uniquePositions = append(uniquePositions, i)
		}
	}
	var pkCount int
	err := p.db.QueryRowContext(ctx, `
		select count(*)
		from information_schema.table_constraints
		where table_schema = ? and table_name = ? and constraint_type = 'PRIMARY KEY'
	`, snapshot.Schema, snapshot.Table.Name).Scan(&pkCount)
	if err != nil {
		// count(*) can never be empty — a failed read is a provider
		// failure (issue #79: actual failures stay errors), not an
		// answerable absence. Context cancellation propagates the same.
		return fmt.Errorf("query table_constraints: %w", err)
	}
	if pkCount == 0 {
		// Proven PK-less: every fold is a secondary — members, not the
		// constraint object.
		return nil
	}
	if pkCount > 1 {
		// A constraint count beyond one is a catalog inconsistency the
		// binding cannot resolve — withhold all three primary facts and
		// demote every maybe-PK fold: no candidate may stay a proven
		// UNIQUE member while the constraint truth itself is unproven.
		for _, pos := range uniquePositions {
			snapshot.Indexes[pos].Kind = spec.IndexKindUnknown
		}
		snapshot.PrimaryKeyUnknown = true
		snapshot.PrimaryKeyHandleUnknown = true
		snapshot.PrimaryKeyClusteredUnknown = true
		return nil
	}
	// pkCount == 1 — the constraint proves presence; attribute the object.
	// Every unique fold is a candidate: a PK object always emits a
	// NON_UNIQUE=0 fold, a secondary may be unique too, and a member may
	// even own `primary` uniquely (a unique member `primary` beside a
	// renamed pk2 object is legal — the name alone cannot pick).
	switch len(uniquePositions) {
	case 0:
		// A proven PK with no NON_UNIQUE=0 fold is a catalog
		// inconsistency — presence stays vouched but nothing can be
		// attributed, and the stored shape answers nothing.
		p.withholdTiDBPrimaryAttribution(snapshot, nil, false)
		return nil
	case 1:
		// Exactly one unique fold can only be the PK object — the
		// constraint requires a unique fold and none other exists.
		p.promoteTiDBPrimary(snapshot, uniquePositions[0])
		return nil
	}
	// Multiple unique candidates — the clustered fact first: only the PK
	// object's TIDB_INDEXES row can read YES.
	clustered, err := p.loadTiDBClusteredRows(ctx, snapshot)
	if err != nil {
		return fmt.Errorf("query tidb_indexes clustered: %w", err)
	}
	clusteredCount := 0
	clusteredPos := -1
	coverageComplete := true
	for _, pos := range uniquePositions {
		switch clustered[strings.ToLower(snapshot.Indexes[pos].Name)] {
		case tidbClusteredYes:
			clusteredCount++
			clusteredPos = pos
		case tidbClusteredNo:
		default:
			// A missing row or an unrecognized value is unproven
			// coverage — never a proven NO.
			coverageComplete = false
		}
	}
	if clusteredCount == 1 {
		p.promoteTiDBPrimary(snapshot, clusteredPos)
		snapshot.PrimaryKeyClustered = true
		return nil
	}
	if clusteredCount > 1 {
		// Two clustered candidates contradicts the catalog's own rule —
		// withhold the object identity.
		p.withholdTiDBPrimaryAttribution(snapshot, uniquePositions, false)
		return nil
	}
	// No clustered candidate — the PK object is nonclustered only while
	// every candidate's row is a recognized NO; an unproven row keeps the
	// storage facts unknown instead of publishing NONCLUSTERED. The
	// constraint's declared ordered member sequence still separates the
	// object from unique members carrying the same column set.
	pkColumns, err := p.loadTiDBPrimaryKeyColumns(ctx, snapshot)
	if err != nil {
		return fmt.Errorf("query key_column_usage primary: %w", err)
	}
	matched := -1
	matches := 0
	for _, pos := range uniquePositions {
		if columnsSequenceEqualFold(snapshot.Indexes[pos].Columns, pkColumns) {
			matched = pos
			matches++
		}
	}
	if len(pkColumns) > 0 && matches == 1 {
		p.promoteTiDBPrimary(snapshot, matched)
		return nil
	}
	p.withholdTiDBPrimaryAttribution(snapshot, uniquePositions, coverageComplete)
	return nil
}

// columnsSequenceEqualFold compares two column-name lists as ordered
// sequences — the KCU ordinal_position list against a candidate fold's
// seq_in_index order. A UNIQUE (b,a) member is never the PRIMARY KEY
// (a,b) object: the same column set in a different order is a different
// index.
func columnsSequenceEqualFold(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if !strings.EqualFold(a[i], b[i]) {
			return false
		}
	}
	return true
}

// loadTiDBPrimaryKeyColumns returns the PRIMARY KEY constraint's declared
// column names — the fact that separates the PK object fold from ordinary
// UNIQUE members when every candidate proves nonclustered.
func (p *Provider) loadTiDBPrimaryKeyColumns(ctx context.Context, snapshot *spec.TableSnapshot) ([]string, error) {
	rows, err := p.db.QueryContext(ctx, `
		select column_name
		from information_schema.key_column_usage
		where table_schema = ? and table_name = ? and constraint_name = 'PRIMARY'
		order by ordinal_position
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		if err == sql.ErrNoRows {
			// ErrNoRows from Query is the row-absent answer — no declared
			// member list — not a provider failure.
			return nil, nil
		}
		return nil, err
	}
	defer rows.Close()
	var columns []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		columns = append(columns, name)
	}
	return columns, rows.Err()
}

// promoteTiDBPrimary moves the candidate fold to snapshot.PrimaryKey —
// the constraint object's real index-member identity. The remaining folds
// keep their member slots.
func (p *Provider) promoteTiDBPrimary(snapshot *spec.TableSnapshot, pos int) {
	index := snapshot.Indexes[pos]
	index.Kind = spec.IndexKindPrimary
	snapshot.PrimaryKey = &index
	snapshot.Indexes = append(snapshot.Indexes[:pos], snapshot.Indexes[pos+1:]...)
}

// withholdTiDBPrimaryAttribution keeps the proven PK presence (a
// name-unknown placeholder) while unvouching the object identity: each
// surviving candidate demotes to kind unknown so member-comparison rules
// never consume a maybe-PK fold as a proven UNIQUE, and the
// handle/clustered answers stay unknown unless every candidate already
// proved nonclustered storage.
func (p *Provider) withholdTiDBPrimaryAttribution(snapshot *spec.TableSnapshot, candidates []int, provenNonClustered bool) {
	snapshot.PrimaryKey = &spec.Index{Kind: spec.IndexKindPrimary, NameUnknown: true}
	for _, pos := range candidates {
		snapshot.Indexes[pos].Kind = spec.IndexKindUnknown
	}
	if !provenNonClustered {
		snapshot.PrimaryKeyHandleUnknown = true
		snapshot.PrimaryKeyClusteredUnknown = true
	}
}

// tidbClusteredValue is the tri-state answer one TIDB_INDEXES.CLUSTERED
// row can give — a clean read that is missing the row or carries a
// NULL/unrecognized value is unproven coverage, never a proven NO.
type tidbClusteredValue int

const (
	tidbClusteredUnproven tidbClusteredValue = iota
	tidbClusteredNo
	tidbClusteredYes
)

// loadTiDBClusteredRows reads every index row's clustered flag from
// information_schema.TIDB_INDEXES — the catalog's own clustered-storage
// fact, keyed by stored index name (lowercased). Only the PK object's row
// can read YES, which is exactly what separates a common-handle object
// from ordinary UNIQUE members. Candidates absent from the map (or
// carrying a NULL/unrecognized value) answer unproven, not NO.
func (p *Provider) loadTiDBClusteredRows(ctx context.Context, snapshot *spec.TableSnapshot) (map[string]tidbClusteredValue, error) {
	rows, err := p.db.QueryContext(ctx, `
		select key_name, clustered
		from information_schema.tidb_indexes
		where table_schema = ? and table_name = ?
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		if err == sql.ErrNoRows {
			// A driver reporting ErrNoRows from Query means an empty
			// result — the row-absent answer, not a failure.
			return map[string]tidbClusteredValue{}, nil
		}
		return nil, err
	}
	defer rows.Close()
	clustered := make(map[string]tidbClusteredValue)
	for rows.Next() {
		var name string
		var value sql.NullString
		if err := rows.Scan(&name, &value); err != nil {
			return nil, err
		}
		// Keys fold to lowercase for the case-insensitive name match —
		// identifier folds compare EqualFold everywhere else. Two
		// case-variant rows (a member `primary` beside a synthesized
		// `PRIMARY`) collapse to one key, so the fold merges YES over
		// unproven over NO, independent of read order: a YES overwrite can
		// only push attribution toward the clustered candidate or the
		// withhold arm, and an unproven row may never be covered by a
		// same-key NO — the fold's answer stays unproven until every row
		// under the key is a recognized NO.
		key := strings.ToLower(name)
		state := tidbClusteredUnproven
		if value.Valid {
			switch {
			case strings.EqualFold(value.String, "yes"):
				state = tidbClusteredYes
			case strings.EqualFold(value.String, "no"):
				state = tidbClusteredNo
			}
		}
		if prev, seen := clustered[key]; !seen || state == tidbClusteredYes ||
			(prev == tidbClusteredNo && state == tidbClusteredUnproven) {
			clustered[key] = state
		}
	}
	return clustered, rows.Err()
}

// loadTiDBPrimaryKeyHandle resolves the two independent TiDB primary facts
// from information_schema.TIDB_INDEXES.CLUSTERED: clustered storage (the
// DROP PRIMARY KEY 8200 refusal class — PKIsHandle and common-handle member
// shapes alike) and whether the PK is stored as PKIsHandle — the row-id
// promotion for a single-integer clustered PK that leaves no operable
// PRIMARY index object. STATISTICS synthesizes a PRIMARY member row even
// for handle tables, so neither fact can be told by index presence alone.
// A missing catalog row keeps both unknown — MySQL and PK-less TiDB tables
// never reach this probe.
func (p *Provider) loadTiDBPrimaryKeyHandle(ctx context.Context, snapshot *spec.TableSnapshot) error {
	if snapshot.PrimaryKey == nil || snapshot.PrimaryKeyUnknown {
		// No PK or an unresolved PK identity — the `primary` catalog rows
		// may not be the constraint object's, so neither fact can be
		// answered from them.
		return nil
	}
	if snapshot.PrimaryKey.NameUnknown || strings.TrimSpace(snapshot.PrimaryKey.Name) == "" {
		// A present-but-unattributed PK (the constraint proved presence
		// while no fold could be picked) has no proven stored name to
		// probe — the attribution pass already set the handle/clustered
		// answers it could prove, so nothing more can settle here.
		return nil
	}
	// Probe by the PK object's actual stored name — a renamed object no
	// longer answers `primary`, and a case-insensitive match may return a
	// member `primary` row alongside the synthesized PRIMARY row, so the
	// clustered fact takes the YES row whenever one exists (only the PK
	// object's row can be clustered).
	rows, err := p.db.QueryContext(ctx, `
		select clustered
		from information_schema.tidb_indexes
		where table_schema = ? and table_name = ? and key_name = ?
	`, snapshot.Schema, snapshot.Table.Name, snapshot.PrimaryKey.Name)
	if err != nil {
		if err != sql.ErrNoRows {
			// A failed catalog read is a provider failure (issue #79) —
			// propagate rather than fabricating a withheld answer.
			// Context cancellation propagates identically.
			return fmt.Errorf("query tidb_indexes clustered: %w", err)
		}
		// ErrNoRows from Query is the row-absent answer — the stored
		// shape stays unproven both ways.
		snapshot.PrimaryKeyHandleUnknown = true
		snapshot.PrimaryKeyClusteredUnknown = true
		return nil
	}
	defer rows.Close()
	rowCount := 0
	clusteredYes := false
	unrecognized := false
	for rows.Next() {
		var value sql.NullString
		if err := rows.Scan(&value); err != nil {
			return fmt.Errorf("scan tidb_indexes clustered: %w", err)
		}
		rowCount++
		if !value.Valid {
			unrecognized = true
			continue
		}
		switch {
		case strings.EqualFold(value.String, "yes"):
			clusteredYes = true
		case strings.EqualFold(value.String, "no"):
		default:
			unrecognized = true
		}
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate tidb_indexes clustered: %w", err)
	}
	if rowCount == 0 {
		// STATISTICS vouched the object but TIDB_INDEXES lacks the row —
		// the stored shape is unproven either way, so the handle and
		// clustered answers both stay unknown instead of defaulting to a
		// real object.
		snapshot.PrimaryKeyHandleUnknown = true
		snapshot.PrimaryKeyClusteredUnknown = true
		return nil
	}
	if unrecognized && !clusteredYes {
		// A NULL or unrecognized CLUSTERED value is equally unproven.
		snapshot.PrimaryKeyHandleUnknown = true
		snapshot.PrimaryKeyClusteredUnknown = true
		return nil
	}
	if !clusteredYes {
		// CLUSTERED=no is a real nonclustered PRIMARY index object — a
		// determined answer on both facts.
		return nil
	}
	// CLUSTERED=yes is the catalog's own clustered-storage fact — it covers
	// PKIsHandle and common-handle shapes alike, which is exactly the class
	// DROP PRIMARY KEY refuses natively (8200).
	snapshot.PrimaryKeyClustered = true
	if len(snapshot.PrimaryKey.Columns) != 1 {
		// A clustered non-single-int PK is a common-handle real object.
		return nil
	}
	if snapshot.PrimaryKey.Columns[0] == "" {
		// The member list cannot prove the PK column — the handle answer
		// stays unknown (an expression/unmodeled PK member is already
		// excluded by the single-column guard above only when a name is
		// provable).
		snapshot.PrimaryKeyHandleUnknown = true
		return nil
	}
	if snapshot.Columns == nil {
		// A withheld column set cannot prove the member is integer.
		snapshot.PrimaryKeyHandleUnknown = true
		return nil
	}
	if integer := tidbHandleColumnInteger(snapshot, snapshot.PrimaryKey.Columns[0]); integer != nil {
		snapshot.PrimaryKeyIsHandle = *integer
	} else {
		// The PK member is not provable in the vouched column set — the
		// handle answer stays unknown.
		snapshot.PrimaryKeyHandleUnknown = true
	}
	return nil
}

// tidbHandleColumnInteger reports whether the PK column is an integer kind —
// the shape TiDB promotes to PKIsHandle under clustered storage. nil when
// the column is not provable in the loaded set.
func tidbHandleColumnInteger(snapshot *spec.TableSnapshot, column string) *bool {
	for i := range snapshot.Columns {
		if strings.EqualFold(snapshot.Columns[i].Name, column) {
			integer := false
			switch catalogBaseType(snapshot.Columns[i].Type) {
			case "tinyint", "smallint", "mediumint", "int", "integer", "bigint":
				integer = true
			}
			return &integer
		}
	}
	return nil
}

func (p *Provider) loadColumns(ctx context.Context, snapshot *spec.TableSnapshot) error {
	rows, err := p.db.QueryContext(ctx, `
		select column_name, column_type, character_set_name, collation_name, column_comment,
		       column_default, is_nullable, extra, generation_expression
		from information_schema.columns
		where table_schema = ? and table_name = ?
		order by ordinal_position
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return fmt.Errorf("query table columns: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var name, columnType, isNullable, extra string
		var charset, collation, comment, defaultValue, generationExpr sql.NullString
		if err := rows.Scan(&name, &columnType, &charset, &collation, &comment, &defaultValue, &isNullable, &extra, &generationExpr); err != nil {
			return fmt.Errorf("scan table column: %w", err)
		}
		typeText, length, unsigned := parseColumnType(columnType)
		extraTokens := catalogExtraTokens(extra)
		column := spec.Column{
			Name:          name,
			Type:          typeText,
			Length:        length,
			Charset:       charset.String,
			Collation:     collation.String,
			Comment:       comment.String,
			Unsigned:      unsigned,
			NotNull:       strings.EqualFold(isNullable, "NO"),
			AutoIncrement: strings.Contains(strings.ToLower(extra), "auto_increment"),
			HasDefault:    defaultValue.Valid,
			DefaultValue:  defaultValue.String,
		}
		// The CURRENT_TIMESTAMP marker is only meaningful on temporal
		// columns: on a VARCHAR row the stored bytes are the string literal
		// 'CURRENT_TIMESTAMP', not the temporal function. The catalog
		// cannot recover which declaration produced them, but the column
		// type is authoritative — a non-temporal base type never stores a
		// temporal function default.
		if defaultValue.Valid && strings.EqualFold(defaultValue.String, "current_timestamp") && temporalDefaultColumnType(typeText) {
			column.DefaultIsCurrentTimestamp = true
		}
		// A non-NULL COLUMN_DEFAULT is always a stored representation, never
		// proof of a SQL NULL default: the text "null" is the string literal
		// 'null', while a real DEFAULT NULL surfaces as a NULL row. A NULL
		// column_default also cannot distinguish an omitted DEFAULT clause
		// from an explicit DEFAULT NULL, so neither sets DefaultIsNull here.
		if strings.Contains(strings.ToLower(extra), "on update current_timestamp") {
			column.OnUpdateCurrentTimestamp = true
		}
		// T07: generation presence comes from the GENERATED EXTRA token or
		// non-empty GENERATION_EXPRESSION text, never from declaration
		// spelling. Storage comes only from unambiguous STORED/VIRTUAL
		// tokens — a missing or contradictory pair stays explicit unknown
		// storage. Absent or unparseable expression text stays an explicit
		// unknown expression fact rather than collapsing into a known-empty
		// one or a fake absent column.
		generationText := ""
		if generationExpr.Valid {
			generationText = strings.TrimSpace(generationExpr.String)
		}
		if extraTokens["generated"] || generationText != "" {
			generated := &spec.GeneratedColumn{Expression: spec.ExpressionFacts{}}
			switch {
			case extraTokens["stored"] && !extraTokens["virtual"]:
				generated.Storage = spec.GeneratedStorageStored
			case extraTokens["virtual"] && !extraTokens["stored"]:
				generated.Storage = spec.GeneratedStorageVirtual
			default:
				generated.Storage = spec.GeneratedStorageUnknown
			}
			if generationText != "" {
				generated.Expression = tidbparser.ParseCatalogExpressionFacts(generationText)
			}
			column.Generated = generated
		}
		// DEFAULT_GENERATED marks an expression default: keep the raw catalog
		// bytes in DefaultValue and carry parsed facts separately. A bare
		// temporal current_timestamp keeps the existing temporal contract
		// (DefaultIsCurrentTimestamp, no DefaultExpression). Undecodable or
		// absent expression text is an explicit unknown fact.
		if extraTokens["default_generated"] && !column.DefaultIsCurrentTimestamp {
			// Catalog-stored expression defaults are always parenthesized —
			// the flag mirrors the authored-syntax fact, not the value.
			column.DefaultParenthesized = true
			if defaultValue.Valid && strings.TrimSpace(defaultValue.String) != "" {
				column.DefaultExpression = ptrExpressionFacts(tidbparser.ParseCatalogExpressionFacts(defaultValue.String))
			} else {
				column.DefaultExpression = &spec.ExpressionFacts{}
			}
		}
		// A stored literal carries its decoded value bytes verbatim on all
		// anchors — no quoting or unescaping applies. The kind comes from
		// the column's own type family, never from guessing at the byte
		// content. The recorded bytes are the literal *identity fact*;
		// whether a pair shares a proven encoding is the comparison's
		// domain check (T08-R2) — scale-normalized catalog text like 1.00
		// is recorded, not normalized to the AST integer's 1.
		if defaultValue.Valid && !column.DefaultIsCurrentTimestamp && column.DefaultExpression == nil {
			column.DefaultLiteral = &spec.LiteralDefaultFacts{
				Kind:  catalogLiteralKind(typeText),
				Value: defaultValue.String,
			}
		}
		// EXTRA is complete for every catalog row: INVISIBLE is the only
		// invisibility marker, so its absence proves effective visibility.
		// VisibilityExplicit stays false — the catalog cannot prove the
		// declaration carried the keyword.
		if extraTokens["invisible"] {
			column.Visibility = spec.ColumnVisibilityInvisible
		} else {
			column.Visibility = spec.ColumnVisibilityVisible
		}
		snapshot.Columns = append(snapshot.Columns, column)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate table columns: %w", err)
	}
	return nil
}

// catalogBaseType reduces a parsed column type to its base keyword:
// faithful forms like decimal(10,2) or enum('a','b') lose their parameter
// span, and attribute text after the base is ignored.
func catalogBaseType(typeText string) string {
	lower := strings.ToLower(strings.TrimSpace(typeText))
	if i := strings.IndexByte(lower, '('); i >= 0 {
		lower = lower[:i]
	}
	if fields := strings.Fields(lower); len(fields) > 0 {
		return fields[0]
	}
	return ""
}

// temporalDefaultColumnType reports the only column base types that can
// carry a CURRENT_TIMESTAMP default under any supported anchor — TIMESTAMP
// and DATETIME. Any other base type storing the bytes CURRENT_TIMESTAMP
// carries the plain string literal.
func temporalDefaultColumnType(typeText string) bool {
	switch catalogBaseType(typeText) {
	case "timestamp", "datetime":
		return true
	default:
		return false
	}
}

// catalogLiteralKind names the comparison domain for a stored literal from
// the column's own type family: numeric bases decode to numeric literals,
// every other family keeps string bytes. It never inspects the byte
// content — the family is the authoritative domain.
func catalogLiteralKind(typeText string) string {
	switch catalogBaseType(typeText) {
	case "tinyint", "smallint", "mediumint", "int", "integer", "bigint",
		"decimal", "numeric", "float", "double", "real", "year":
		return spec.LiteralDefaultNumeric
	default:
		return spec.LiteralDefaultString
	}
}

// catalogExtraTokens splits the EXTRA attribute string into lowercase word
// tokens so compound markers like "VIRTUAL GENERATED" and "DEFAULT_GENERATED"
// are matched exactly, never by substring bleed.
func catalogExtraTokens(extra string) map[string]bool {
	tokens := make(map[string]bool)
	for _, token := range strings.FieldsFunc(strings.ToLower(extra), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_'
	}) {
		tokens[token] = true
	}
	return tokens
}

func ptrExpressionFacts(facts spec.ExpressionFacts) *spec.ExpressionFacts {
	return &facts
}

func (p *Provider) loadIndexes(ctx context.Context, snapshot *spec.TableSnapshot, dialect spec.Dialect) error {
	// sub_part/collation are the bounded plain-key knownness facts: a prefix
	// length, a descending part, or a NULL column_name (expression key part)
	// means the index must not enter ordinary-key comparisons. Both columns
	// exist on every supported anchor; a server without them fails the query
	// and surfaces a load error rather than a guessed shape.
	//
	// IS_VISIBLE is version-gated: MySQL 5.7 has no such column (index
	// visibility landed in 8.0) while 8.0/8.4 and TiDB expose it. The
	// capability probe keeps 5.7 loading honestly — members there carry an
	// unknown Visibility instead of a guessed "visible" or a failed query.
	hasVisible, err := p.statisticsHasIsVisible(ctx)
	if err != nil {
		return err
	}
	visibleSelect := ""
	if hasVisible {
		visibleSelect = ", is_visible"
	}
	// EXPRESSION carries the catalog-stored functional key-part text (MySQL
	// 8.0.13+ and TiDB); MySQL 5.7 has no such column and functional parts
	// cannot exist there, so the probe keeps the row shape honest per
	// anchor instead of selecting a column that may not exist.
	hasExpression, err := p.statisticsHasExpression(ctx)
	if err != nil {
		return err
	}
	expressionSelect := ""
	if hasExpression {
		expressionSelect = ", expression"
	}
	rows, err := p.db.QueryContext(ctx, `
		select index_name, non_unique, index_type, column_name, cardinality,
			sub_part, collation`+visibleSelect+expressionSelect+`
		from information_schema.statistics
		where table_schema = ? and table_name = ?
		order by index_name, seq_in_index
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return fmt.Errorf("query table indexes: %w", err)
	}
	defer rows.Close()

	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)

	for rows.Next() {
		var name, indexType string
		var columnName, collation, visible, expression sql.NullString
		var nonUnique int
		var cardinality, subPart sql.NullInt64
		dest := []any{&name, &nonUnique, &indexType, &columnName, &cardinality, &subPart, &collation}
		if hasVisible {
			dest = append(dest, &visible)
		}
		if hasExpression {
			dest = append(dest, &expression)
		}
		if err := rows.Scan(dest...); err != nil {
			return fmt.Errorf("scan table index: %w", err)
		}

		var cardinalityValue *int64
		if cardinality.Valid {
			cardinalityValue = ptrInt64(cardinality.Int64)
		}
		accumulateIndexRow(indexes, &order, dialect, name, nonUnique, indexType,
			indexMemberRow{columnName: columnName, collation: collation, subPart: subPart, visible: visible, expression: expression},
			cardinalityValue, snapshot.Columns)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate table indexes: %w", err)
	}

	for _, name := range order {
		index := indexes[name]
		index.SetKeyParts(index.KeyParts)
		if index.Kind == spec.IndexKindPrimary {
			snapshot.PrimaryKey = index
			continue
		}
		snapshot.Indexes = append(snapshot.Indexes, *index)
	}
	return nil
}

// loadForeignKeys loads the table's foreign-key members into
// snapshot.Constraints — the only constraint type the collection vouches
// for on the provider path (primary-key identity lives on PrimaryKey and
// unique keys on index members; statement-derived shapes may append
// primary_key members the parser itself proved). KEY_COLUMN_USAGE rows
// with a non-NULL referenced table are exactly the FK column pairs, in
// ORDINAL_POSITION order, so local and referenced columns fold into
// aligned ordered lists. REFERENTIAL_CONSTRAINTS supplies delete/update
// rules; a MATCH option other than NONE counts as an unmodeled refer
// action rather than silently dropping. A clean empty result is a proven
// empty set — never a withheld one — while query/scan failures propagate
// because a failed catalog read is not an answerable absence.
func (p *Provider) loadForeignKeys(ctx context.Context, snapshot *spec.TableSnapshot) error {
	rows, err := p.db.QueryContext(ctx, `
		select k.constraint_name, k.column_name,
			k.referenced_table_schema, k.referenced_table_name, k.referenced_column_name,
			r.delete_rule, r.update_rule, r.match_option
		from information_schema.key_column_usage k
		left join information_schema.referential_constraints r
			on r.constraint_schema = k.constraint_schema
			and r.table_name = k.table_name
			and r.constraint_name = k.constraint_name
		where k.table_schema = ? and k.table_name = ?
			and k.referenced_table_name is not null
		order by k.constraint_name, k.ordinal_position
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return fmt.Errorf("query table foreign keys: %w", err)
	}
	defer rows.Close()

	constraints := make([]spec.Constraint, 0)
	byName := make(map[string]int)
	for rows.Next() {
		var name, column, refSchema, refTable, refColumn string
		var deleteRule, updateRule, matchOption sql.NullString
		if err := rows.Scan(&name, &column, &refSchema, &refTable, &refColumn,
			&deleteRule, &updateRule, &matchOption); err != nil {
			return fmt.Errorf("scan table foreign key: %w", err)
		}
		pos, seen := byName[name]
		if !seen {
			constraints = append(constraints, spec.Constraint{Type: "foreign_key", Name: name})
			pos = len(constraints) - 1
			byName[name] = pos
		}
		member := &constraints[pos]
		member.Columns = append(member.Columns, column)
		member.ReferencedSchema = refSchema
		member.ReferencedTable = refTable
		member.ReferencedColumns = append(member.ReferencedColumns, refColumn)
		if deleteRule.Valid {
			member.OnDelete = referActionName(deleteRule.String)
		}
		if updateRule.Valid {
			member.OnUpdate = referActionName(updateRule.String)
		}
		if matchOption.Valid && !strings.EqualFold(matchOption.String, "NONE") {
			member.UnmodeledReferActions++
		}
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate table foreign keys: %w", err)
	}
	snapshot.Constraints = constraints
	return nil
}

// loadCheckConstraints loads the table's CHECK members into
// snapshot.Constraints after the foreign keys — name, enforcement state,
// and the parsed clause's structural facts (never the raw expression
// text). Two live catalog shapes exist, probed on the anchors:
//   - MySQL 8.0.16+: members sit in TABLE_CONSTRAINTS with ENFORCED; the
//     clause joins from CHECK_CONSTRAINTS on catalog+schema+name (that
//     table has no TABLE_NAME column on MySQL).
//   - TiDB v8.5.0: members sit only in TIDB_CHECK_CONSTRAINTS (which does
//     carry TABLE_NAME); TABLE_CONSTRAINTS stores no CHECK rows and no
//     catalog column exposes the enforcement bit — SHOW CREATE's
//     /*!80016 NOT ENFORCED */ marker is the only surface, so provider
//     members stay enforcement-unvouched on TiDB.
//
// MySQL 5.7 stores no CHECK members at all. A catalog without the
// relevant capability leaves member facts unproven rather than guessed.
// Query failures propagate — a failed catalog read is not an answerable
// absence.
func (p *Provider) loadCheckConstraints(ctx context.Context, snapshot *spec.TableSnapshot) error {
	hasTidb, err := p.tidbCheckConstraintsTableExists(ctx)
	if err != nil {
		return fmt.Errorf("probe tidb_check_constraints table: %w", err)
	}
	if hasTidb {
		return p.loadTiDBCheckConstraints(ctx, snapshot)
	}
	hasEnforced, err := p.tableConstraintsHasEnforced(ctx)
	if err != nil {
		return fmt.Errorf("probe table_constraints.enforced: %w", err)
	}
	hasClauses, err := p.checkConstraintsTableExists(ctx)
	if err != nil {
		return fmt.Errorf("probe check_constraints table: %w", err)
	}

	enforcedSel, clauseSel, join := "null", "null", ""
	if hasEnforced {
		enforcedSel = "tc.enforced"
	}
	if hasClauses {
		clauseSel = "cc.check_clause"
		join = `
		left join information_schema.check_constraints cc
			on cc.constraint_catalog = tc.constraint_catalog
			and cc.constraint_schema = tc.constraint_schema
			and cc.constraint_name = tc.constraint_name`
	}
	rows, err := p.db.QueryContext(ctx, `
		select tc.constraint_name, `+enforcedSel+`, `+clauseSel+`
		from information_schema.table_constraints tc`+join+`
		where tc.table_schema = ? and tc.table_name = ?
			and tc.constraint_type = 'CHECK'
		order by tc.constraint_name
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return fmt.Errorf("query table check constraints: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var name string
		var enforced, clause sql.NullString
		if err := rows.Scan(&name, &enforced, &clause); err != nil {
			return fmt.Errorf("scan table check constraint: %w", err)
		}
		member := spec.Constraint{Type: "check", Name: name}
		if enforced.Valid {
			member.Enforced = checkEnforcementName(enforced.String)
		}
		if clause.Valid {
			facts := tidbparser.ParseCatalogExpressionFacts(clause.String)
			member.Expression = &facts
			for _, ref := range facts.References {
				if !ref.Qualified() {
					member.Columns = append(member.Columns, ref.Name)
				}
			}
		}
		snapshot.Constraints = append(snapshot.Constraints, member)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate table check constraints: %w", err)
	}

	return p.finishCheckConstraintLoad(ctx, snapshot)
}

// loadTiDBCheckConstraints loads CHECK members on the TiDB catalog shape:
// TIDB_CHECK_CONSTRAINTS carries TABLE_NAME and CHECK_CLAUSE but no
// enforcement column (verified on the v8.5.0 anchor — enforcement is only
// rendered inside SHOW CREATE output). Members therefore arrive with
// Enforced unvouched; ordered state transitions carry the flip knowledge.
func (p *Provider) loadTiDBCheckConstraints(ctx context.Context, snapshot *spec.TableSnapshot) error {
	rows, err := p.db.QueryContext(ctx, `
		select constraint_name, check_clause
		from information_schema.tidb_check_constraints
		where constraint_schema = ? and table_name = ?
		order by constraint_name
	`, snapshot.Schema, snapshot.Table.Name)
	if err != nil {
		return fmt.Errorf("query tidb check constraints: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var name, clause string
		if err := rows.Scan(&name, &clause); err != nil {
			return fmt.Errorf("scan tidb check constraint: %w", err)
		}
		member := spec.Constraint{Type: "check", Name: name}
		facts := tidbparser.ParseCatalogExpressionFacts(clause)
		member.Expression = &facts
		for _, ref := range facts.References {
			if !ref.Qualified() {
				member.Columns = append(member.Columns, ref.Name)
			}
		}
		snapshot.Constraints = append(snapshot.Constraints, member)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate tidb check constraints: %w", err)
	}
	return p.finishCheckConstraintLoad(ctx, snapshot)
}

// finishCheckConstraintLoad applies the shared tail of
// loadCheckConstraints: the collection vouches for foreign keys, checks,
// and statement-proven primary_key members — primary keys live on
// PrimaryKey and unique keys on index members. Any other
// TABLE_CONSTRAINTS type is a member this projection cannot represent, so
// its presence unvouches the collection rather than letting a partial
// answer pose as complete.
func (p *Provider) finishCheckConstraintLoad(ctx context.Context, snapshot *spec.TableSnapshot) error {
	var unmodeled int
	err := p.db.QueryRowContext(ctx, `
		select count(*)
		from information_schema.table_constraints
		where table_schema = ? and table_name = ?
			and constraint_type not in ('PRIMARY KEY', 'UNIQUE', 'FOREIGN KEY', 'CHECK')
	`, snapshot.Schema, snapshot.Table.Name).Scan(&unmodeled)
	if err != nil {
		return fmt.Errorf("query table unmodeled constraint types: %w", err)
	}
	if unmodeled > 0 {
		snapshot.ConstraintsUnknown = true
	}
	return nil
}

// tidbCheckConstraintsTableExists reports whether this server's
// information_schema exposes the TiDB-specific TIDB_CHECK_CONSTRAINTS
// member table (the only catalog with TABLE_NAME attribution for checks
// on TiDB; absent on MySQL).
func (p *Provider) tidbCheckConstraintsTableExists(ctx context.Context) (bool, error) {
	var n int
	err := p.db.QueryRowContext(ctx, `
		select count(*) from information_schema.`+"`tables`"+`
		where table_schema = 'information_schema'
			and table_name = 'TIDB_CHECK_CONSTRAINTS'
	`).Scan(&n)
	if err != nil {
		if err == sql.ErrNoRows {
			return false, nil
		}
		return false, err
	}
	return n > 0, nil
}

// checkEnforcementName normalizes the catalog ENFORCED token into the
// constraint vocabulary — an unrecognized value stays empty rather than a
// guessed fact.
func checkEnforcementName(token string) string {
	switch strings.ToUpper(strings.TrimSpace(token)) {
	case "YES":
		return "enforced"
	case "NO":
		return "not_enforced"
	default:
		return ""
	}
}

// tableConstraintsHasEnforced reports whether this server's
// information_schema.TABLE_CONSTRAINTS exposes the ENFORCED column
// (MySQL 8.0.16+, TiDB; absent on MySQL 5.7). The probe queries the
// catalog itself so the answer reflects the connected server, not a
// version guess.
func (p *Provider) tableConstraintsHasEnforced(ctx context.Context) (bool, error) {
	var n int
	err := p.db.QueryRowContext(ctx, `
		select count(*) from information_schema.`+"`columns`"+`
		where table_schema = 'information_schema'
			and table_name = 'TABLE_CONSTRAINTS'
			and column_name = 'ENFORCED'
	`).Scan(&n)
	if err != nil {
		if err == sql.ErrNoRows {
			return false, nil
		}
		return false, err
	}
	return n > 0, nil
}

// checkConstraintsTableExists reports whether this server's
// information_schema exposes the CHECK_CONSTRAINTS clause table (MySQL
// 8.0.16+, TiDB; absent on MySQL 5.7 where CHECK syntax parses but is
// ignored).
func (p *Provider) checkConstraintsTableExists(ctx context.Context) (bool, error) {
	var n int
	err := p.db.QueryRowContext(ctx, `
		select count(*) from information_schema.`+"`tables`"+`
		where table_schema = 'information_schema'
			and table_name = 'CHECK_CONSTRAINTS'
	`).Scan(&n)
	if err != nil {
		if err == sql.ErrNoRows {
			return false, nil
		}
		return false, err
	}
	return n > 0, nil
}

// referActionName normalizes a catalog DELETE_RULE/UPDATE_RULE token into
// the same lowercase vocabulary parser-extracted referential actions use.
// An unrecognized token stays an empty string rather than a guessed fact.
func referActionName(rule string) string {
	switch strings.ToUpper(strings.TrimSpace(rule)) {
	case "RESTRICT":
		return "restrict"
	case "CASCADE":
		return "cascade"
	case "SET NULL":
		return "set_null"
	case "NO ACTION":
		return "no_action"
	case "SET DEFAULT":
		return "set_default"
	default:
		return ""
	}
}

// ResolveObject implements the ObjectResolver seam for non-table catalog
// objects. T17 resolves schema identities through
// information_schema.SCHEMATA: existence, default charset/collation, the
// DEFAULT_ENCRYPTION column (MySQL 8.0.16+, capability-probed), and TiDB's
// TIDB_PLACEMENT_POLICY_NAME binding. Every other object type reports
// unavailable — the resolver never fabricates coverage it does not query.
func (p *Provider) ResolveObject(ctx context.Context, dialect spec.Dialect, request spec.ObjectLookupRequest) (*spec.ObjectSnapshot, error) {
	snapshot := &spec.ObjectSnapshot{
		Schema: request.Schema,
		Type:   request.Type,
		Name:   request.Name,
		Status: spec.MetadataStatusUnavailable,
	}
	if request.Type != "schema" || strings.TrimSpace(request.Name) == "" {
		return snapshot, nil
	}
	return p.loadSchemaObject(ctx, dialect, request.Name, snapshot)
}

func (p *Provider) loadSchemaObject(ctx context.Context, dialect spec.Dialect, name string, snapshot *spec.ObjectSnapshot) (*spec.ObjectSnapshot, error) {
	row := p.db.QueryRowContext(ctx, `
		select schema_name, default_character_set_name, default_collation_name
		from information_schema.schemata
		where schema_name = ?
	`, name)
	var schemaName, charset, collation sql.NullString
	if err := row.Scan(&schemaName, &charset, &collation); err != nil {
		if err == sql.ErrNoRows {
			snapshot.Status = spec.MetadataStatusNotFound
			return snapshot, nil
		}
		return nil, fmt.Errorf("query schema snapshot %s: %w", name, err)
	}
	snapshot.Status = spec.MetadataStatusConfirmed
	snapshot.Exists = true
	snapshot.Schema = schemaName.String
	snapshot.Attributes = map[string]string{}
	if charset.Valid && charset.String != "" {
		snapshot.Attributes["charset"] = charset.String
	}
	if collation.Valid && collation.String != "" {
		snapshot.Attributes["collation"] = collation.String
	}
	if has, err := p.schemataHasColumn(ctx, "DEFAULT_ENCRYPTION"); err != nil {
		return nil, err
	} else if has {
		var encryption sql.NullString
		err = p.db.QueryRowContext(ctx, `
			select default_encryption
			from information_schema.schemata
			where schema_name = ?
		`, name).Scan(&encryption)
		if err != nil {
			return nil, fmt.Errorf("query schema encryption %s: %w", name, err)
		}
		if encryption.Valid && encryption.String != "" {
			snapshot.Attributes["encryption"] = strings.ToLower(encryption.String)
		}
	}
	if dialect == spec.DialectTiDB {
		if has, err := p.schemataHasColumn(ctx, "TIDB_PLACEMENT_POLICY_NAME"); err != nil {
			return nil, err
		} else if has {
			var policy sql.NullString
			err = p.db.QueryRowContext(ctx, `
				select tidb_placement_policy_name
				from information_schema.schemata
				where schema_name = ?
			`, name).Scan(&policy)
			if err != nil {
				return nil, fmt.Errorf("query schema placement policy %s: %w", name, err)
			}
			if policy.Valid && policy.String != "" {
				snapshot.Attributes["placement_policy"] = policy.String
			}
		}
	}
	return snapshot, nil
}

// schemataHasColumn reports whether this server's information_schema.SCHEMATA
// exposes the named column (DEFAULT_ENCRYPTION on MySQL 8.0.16+,
// TIDB_PLACEMENT_POLICY_NAME on TiDB; neither on MySQL 5.7). The answer comes
