// indexMemberRow carries one STATISTICS member row's plain-key knownness
// facts: which column it names, its sort direction, and its prefix length.
// A NULL column_name marks an expression key part; a NULL collation on a
// named member means the row is not classifiable as a plain ascending part.
// visible carries the index-level IS_VISIBLE fact (constant across the
// index's rows); a NULL/unsupported value leaves Visibility unknown.
// expression carries the catalog-stored functional key-part text when the
// server exposes it.
type indexMemberRow struct {
	columnName sql.NullString
	collation  sql.NullString
	subPart    sql.NullInt64
	visible    sql.NullString
	expression sql.NullString
}

func accumulateIndexRow(indexes map[string]*spec.Index, order *[]string, dialect spec.Dialect, name string, nonUnique int, indexType string, member indexMemberRow, cardinality *int64, columns []spec.Column) {
	index, ok := indexes[name]
	if !ok {
		index = &spec.Index{
			Name: name,
			Kind: classifyIndex(dialect, name, nonUnique, indexType),
		}
		indexes[name] = index
		*order = append(*order, name)
	}
	if index.Visibility == "" {
		switch {
		case strings.EqualFold(member.visible.String, "yes"):
			index.Visibility = spec.ColumnVisibilityVisible
		case member.visible.Valid && strings.EqualFold(member.visible.String, "no"):
			index.Visibility = spec.ColumnVisibilityInvisible
		}
	}

	// STATISTICS emits rows in seq_in_index order inside each index group,
	// so the accumulated slice position is the member ordinal.
	keyPart := spec.IndexKeyPart{Ordinal: len(index.KeyParts) + 1}
	switch {
	case !member.columnName.Valid:
		// A SQL NULL column_name is an expression key part — the catalog
		// stores no column name for it. The catalog EXPRESSION text
		// supplies the member identity and column dependencies when the
		// server exposes it.
		classifyExpressionMember(&keyPart, member)
	case strings.EqualFold(member.columnName.String, "NULL"):
		// TiDB emits the literal text 'NULL' for an expression member
		// while MySQL emits a SQL NULL — but a real column can carry the
		// backtick-quoted reserved name too (`` `NULL` INT ``), so the
		// literal alone cannot classify the row. Decide on verifiable
		// catalog facts: expression text present → expression member;
		// the loaded column set vouches the named column → plain column;
		// neither provable → unmodeled rather than a guessed either-way.
		switch {
		case member.expression.Valid && strings.TrimSpace(member.expression.String) != "":
			classifyExpressionMember(&keyPart, member)
		case catalogColumnExists(columns, member.columnName.String):
			classifyColumnMember(&keyPart, index, member)
		default:
			keyPart.Kind = spec.IndexKeyPartUnmodeled
		}
	default:
		classifyColumnMember(&keyPart, index, member)
	}
	index.KeyParts = append(index.KeyParts, keyPart)
	if cardinality == nil {
		return
	}
	if index.Cardinality == nil || *cardinality > *index.Cardinality {
		index.Cardinality = ptrInt64(*cardinality)
	}
}

// classifyExpressionMember marks the member an expression key part and
// attaches the catalog-stored functional text when the server exposes it —
// the EXPRESSION column is authoritative for identity and dependencies.
// The catalog records sort direction on functional key parts too (MySQL
// 8.0.46 functional_index.result L186-193 proves descending functional
// indexes are real objects), so the member reads the same collation fact
// the column branch does: 'D' keeps descending, 'A' stays ascending, and
// an unproven or unrecognized direction keeps the expression identity but
// marks DirectionUnknown — never demoted to unmodeled, which would lose
// the member's identity and dependency facts.
func classifyExpressionMember(keyPart *spec.IndexKeyPart, member indexMemberRow) {
	switch {
	case strings.EqualFold(member.collation.String, "D"):
		keyPart.Kind = spec.IndexKeyPartExpression
		keyPart.Descending = true
	case member.collation.Valid && strings.EqualFold(member.collation.String, "A"):
		keyPart.Kind = spec.IndexKeyPartExpression
	default:
		// A NULL or unrecognized COLLATION withholds only the direction
		// answer — the member is still provably an expression part.
		keyPart.Kind = spec.IndexKeyPartExpression
		keyPart.DirectionUnknown = true
	}
	if member.expression.Valid && strings.TrimSpace(member.expression.String) != "" {
		keyPart.Expression = ptrExpressionFacts(tidbparser.ParseCatalogExpressionFacts(member.expression.String))
		keyPart.MultiValued = tidbparser.CatalogExpressionIsMultiValued(member.expression.String)
		if keyPart.MultiValued {
			keyPart.MultiValuedCastType, keyPart.MultiValuedCastLengthSet = tidbparser.CatalogMultiValuedCastFacts(member.expression.String)
		}
	}
}

// classifyColumnMember marks the member a plain column key part, carrying
// its authored prefix length and catalog sort direction. A named member
// whose collation the row cannot prove stays unmodeled.
func classifyColumnMember(keyPart *spec.IndexKeyPart, index *spec.Index, member indexMemberRow) {
	keyPart.Kind = spec.IndexKeyPartColumn
	keyPart.Column = member.columnName.String
	index.Columns = append(index.Columns, member.columnName.String)
	if member.subPart.Valid {
		length := int(member.subPart.Int64)
		keyPart.PrefixLength = &length
	}
	if !member.collation.Valid {
		// A named member with no collation (e.g. spatial rows) cannot
		// be classified as a plain ascending part.
		keyPart.Kind = spec.IndexKeyPartUnmodeled
	} else if strings.EqualFold(member.collation.String, "D") {
		keyPart.Descending = true
	} else if !strings.EqualFold(member.collation.String, "A") {
		keyPart.Kind = spec.IndexKeyPartUnmodeled
	}
}

// catalogColumnExists reports whether the loaded column set vouches for a
// member's column name — the fact a literal-'NULL' member row needs to
// stay a plain column instead of being read as an expression marker.
func catalogColumnExists(columns []spec.Column, name string) bool {
	for i := range columns {
		if strings.EqualFold(columns[i].Name, name) {
			return true
		}
	}
	return false
}

func normalizeOnOff(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "on", "yes", "true":
		return true
	default:
		return false
	}
}

func charsetFromCollation(collation string) string {
	if idx := strings.Index(collation, "_"); idx > 0 {
		return collation[:idx]
	}
	return ""
}

// faithfulCatalogTypes are the T06-A17 target bases whose COLUMN_TYPE
// parameter text — DECIMAL/FLOAT/DOUBLE second parameters and ENUM/SET member
// literals — is preserved verbatim. Every other type keeps the established
// base-keyword contract.
var faithfulCatalogTypes = map[string]bool{
	"decimal": true, "float": true, "double": true, "enum": true, "set": true,
}

// typeParameterSpan locates the parenthesized parameter list of a catalog
// COLUMN_TYPE, honoring single-quoted members with ” escapes: a comma or
// right paren inside a member never ends the span. Returns (-1, -1) without a
// parameter list; the end index is exclusive so columnType[start:end] is the
// whole "(...)" segment.
func typeParameterSpan(columnType string) (start, end int) {
	start = strings.IndexByte(columnType, '(')
	if start < 0 {
		return -1, -1
	}
	inString := false
	for i := start + 1; i < len(columnType); i++ {
		switch {
		case inString:
			if columnType[i] == '\'' {
				if i+1 < len(columnType) && columnType[i+1] == '\'' {
					i++
					continue
				}
				inString = false
			}
		case columnType[i] == '\'':
			inString = true
		case columnType[i] == ')':
			return start, i + 1
		}
	}
	return start, len(columnType)
}

// stripQuotedLiterals removes '...' member literals (including ” escapes) so
// attribute detection never reads inside member text: 'x unsigned' inside an
// ENUM member is a value, never the UNSIGNED attribute.
func stripQuotedLiterals(s string) string {
	var b strings.Builder
	inString := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inString {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				inString = false
			}
			continue
		}
		if c == '\'' {
			inString = true
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

// parseColumnType normalizes a catalog COLUMN_TYPE. Length keeps its
// established first-integer meaning; unsigned is read only outside quoted
// member literals; typeText preserves the verbatim parameter span for the
// five faithfulCatalogTypes bases and stays the bare base keyword otherwise.
func parseColumnType(columnType string) (typeText string, length int, unsigned bool) {
	trimmed := strings.TrimSpace(columnType)
	lower := strings.ToLower(trimmed)
	unsigned = strings.Contains(strings.ToLower(stripQuotedLiterals(trimmed)), " unsigned")
	start, end := typeParameterSpan(trimmed)
	var baseType string
	if start >= 0 {
		baseType = strings.TrimSpace(lower[:start])
		part := trimmed[start+1 : end-1]
		if comma := strings.Index(part, ","); comma >= 0 {
			part = part[:comma]
		}
		if parsed, err := strconv.Atoi(strings.TrimSpace(part)); err == nil {
			length = parsed
		}
	} else if fields := strings.Fields(lower); len(fields) > 0 {
		baseType = fields[0]
	}
	if !faithfulCatalogTypes[baseType] {
		return baseType, length, unsigned
	}
	var text strings.Builder
	text.WriteString(baseType)
	if start >= 0 {
		text.WriteString(trimmed[start:end])             // verbatim parameters, member case intact
		text.WriteString(strings.ToLower(trimmed[end:])) // attribute keywords after the span
	} else if rest := trimmed[len(baseType):]; rest != "" {
		// No parameter span (e.g. bare "float unsigned"): keep the declared
		// attribute text, keyword-normalized.
		text.WriteString(strings.ToLower(rest))
	}
	return text.String(), length, unsigned
}

func classifyIndex(dialect spec.Dialect, name string, nonUnique int, indexType string) spec.IndexKind {
	// MySQL reserves `primary` for the PK index object outright — a member
	// can never own the name (1280), so the catalog name promotes safely.
	// TiDB lets a secondary literally own `primary` (RENAME … TO `primary`
	// is legal on PK-less and PKIsHandle tables), so the name alone cannot
	// promote — resolveTiDBPrimaryName binds the PK identity under the
	// table's proven pk-presence fact instead.
	if dialect == spec.DialectMySQL && strings.EqualFold(name, "primary") {
		return spec.IndexKindPrimary
	}
	if strings.EqualFold(indexType, "fulltext") {
		return spec.IndexKindFulltext
	}
	if strings.EqualFold(indexType, "spatial") {
		return spec.IndexKindSpatial
	}
	if nonUnique == 0 {
		return spec.IndexKindUnique
	}
	return spec.IndexKindSecondary
}

func detectDialectFromVersion(version string) spec.Dialect {
	if strings.Contains(strings.ToLower(version), "tidb") {
		return spec.DialectTiDB
	}
	return spec.DialectMySQL
}

func ptrInt64(value int64) *int64 {
	return &value
}

// Package mysql verifies the T06-A10 provider provenance boundary.
package mysqlmeta

import (
	"context"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// t06A10CatalogRows builds the constructed catalog rows for one table whose
// catalog allocator value is `allocator` (nil → SQL NULL) and whose id column
// carries extra='auto_increment'. This is a driver-level fixture — a
// controlled catalog row shape, not a live four-anchor run.
func t06A10CatalogRows(allocator driver.Value) map[string]testQueryResult {
	return map[string]testQueryResult{
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_bin", "", allocator, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.columns": {
			columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows:    [][]driver.Value{{"id", "bigint(20)", nil, nil, "", nil, "NO", "auto_increment", ""}},
		},
		"from information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows:    [][]driver.Value{{"PRIMARY", int64(0), "BTREE", "id", nil, nil, "A"}},
		},
	}
}

// TestProviderT06A10CatalogAllocatorValueWritesSnapshotOption proves the
// catalog-sourced allocator value lands on the same Options key the
// declaration layer uses — same key, different provenance. A NULL catalog
// value keeps the key absent rather than fabricating a declaration.
func TestProviderT06A10CatalogAllocatorValueWritesSnapshotOption(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	t.Run("catalog_value_lands_on_snapshot_option", func(t *testing.T) {
		t.Parallel()
		db := openTestDB(t, t06A10CatalogRows(int64(42)))
		defer db.Close()

		snapshot, err := NewProvider(db).LoadTableSnapshot(ctx, spec.DialectMySQL, "golden", "t")
		if err != nil {
			t.Fatalf("load snapshot: %v", err)
		}
		if !snapshot.Exists || snapshot.Options["auto_increment"] != "42" {
			t.Fatalf("snapshot options = %#v, want auto_increment=42 from catalog", snapshot.Options)
		}
		if len(snapshot.Columns) != 1 || !snapshot.Columns[0].AutoIncrement || snapshot.Columns[0].Name != "id" {
			t.Fatalf("snapshot columns = %#v, want id with auto_increment", snapshot.Columns)
		}
	})

	t.Run("null_catalog_value_keeps_key_absent", func(t *testing.T) {
		t.Parallel()
		db := openTestDB(t, t06A10CatalogRows(nil))
		defer db.Close()

		snapshot, err := NewProvider(db).LoadTableSnapshot(ctx, spec.DialectMySQL, "golden", "t")
		if err != nil {
			t.Fatalf("load snapshot: %v", err)
		}
		if !snapshot.Exists {
			t.Fatal("snapshot must exist")
		}
		if got, present := snapshot.Options["auto_increment"]; present {
			t.Fatalf("NULL catalog value must not fabricate a key, got %q", got)
		}
	})
}

// Package mysqlmeta verifies the T06-A17 catalog type-parameter fidelity
// contract: DECIMAL/FLOAT/DOUBLE parameter text and ENUM/SET member literals
// from COLUMN_TYPE survive the real Provider.LoadTableSnapshot — parameters
// are no longer truncated to the base keyword plus first integer. Rows are
// constructed catalog input (a live server may normalize differently; the
// provider must only preserve what it actually receives).
package mysqlmeta

import (
	"context"
	"database/sql/driver"
	"fmt"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// t06a17ColumnRows renders the frozen A17 column_type inputs verbatim.
func t06a17Results() map[string]testQueryResult {
	columnTypes := [][2]string{
		{"d_dec122", "decimal(12,2)"},
		{"d_dec123", "decimal(12,3)"},
		{"d_dec120", "decimal(12,0)"},
		{"f_flt102", "float(10,2)"},
		{"f_flt103", "float(10,3)"},
		{"f_flt100", "float(10,0)"},
		{"x_dbl162", "double(16,2)"},
		{"x_dbl164", "double(16,4)"},
		{"x_dbl160", "double(16,0)"},
		{"e_upper", "enum('Ready','Closed')"},
		{"e_lower", "enum('ready','closed')"},
		{"e_order", "enum('Closed','Ready')"},
		{"s_upper", "set('Read','Write')"},
		{"s_lower", "set('read','write')"},
		{"s_order", "set('Write','Read')"},
		{"e_edge", "enum('','A,B','A)B','O''Reilly')"},
		// Attribute-boundary controls: ' unsigned'/'zerofill' inside member
		// literals are values, never type attributes.
		{"e_attrword", "enum('x unsigned','y zerofill')"},
		{"s_attrword", "set('a unsigned','b')"},
		{"c_int", "int"},
		{"c_varchar8", "varchar(8)"},
		{"c_bigint_u", "bigint unsigned"},
		{"d_dec122u", "decimal(12,2) unsigned"},
	}
	rows := make([][]driver.Value, 0, len(columnTypes))
	for _, pair := range columnTypes {
		rows = append(rows, []driver.Value{pair[0], pair[1], nil, nil, "", nil, "YES", "", ""})
	}
	return map[string]testQueryResult{
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.columns": {
			columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows:    rows,
		},
		"from information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
		},
	}
}

// t06a17CheckProviderColumns requires the complete 22-row fixture set in
// catalog order: every expected name present exactly once, in position, with
// its faithful Type/Length/Unsigned — nothing unchecked on the actual side.
func t06a17CheckProviderColumns(columns []spec.Column) error {
	expected := []struct {
		name, typeText string
		length         int
		unsigned       bool
	}{
		{"d_dec122", "decimal(12,2)", 12, false},
		{"d_dec123", "decimal(12,3)", 12, false},
		{"d_dec120", "decimal(12,0)", 12, false},
		{"f_flt102", "float(10,2)", 10, false},
		{"f_flt103", "float(10,3)", 10, false},
		{"f_flt100", "float(10,0)", 10, false},
		{"x_dbl162", "double(16,2)", 16, false},
		{"x_dbl164", "double(16,4)", 16, false},
		{"x_dbl160", "double(16,0)", 16, false},
		{"e_upper", "enum('Ready','Closed')", 0, false},
		{"e_lower", "enum('ready','closed')", 0, false},
		{"e_order", "enum('Closed','Ready')", 0, false},
		{"s_upper", "set('Read','Write')", 0, false},
		{"s_lower", "set('read','write')", 0, false},
		{"s_order", "set('Write','Read')", 0, false},
		{"e_edge", "enum('','A,B','A)B','O''Reilly')", 0, false},
		{"e_attrword", "enum('x unsigned','y zerofill')", 0, false},
		{"s_attrword", "set('a unsigned','b')", 0, false},
		{"c_int", "int", 0, false},
		{"c_varchar8", "varchar", 8, false},
		{"c_bigint_u", "bigint", 0, true},
		{"d_dec122u", "decimal(12,2) unsigned", 12, true},
	}
	if len(columns) != len(expected) {
		return fmt.Errorf("columns = %d (%+v), want %d", len(columns), columns, len(expected))
	}
	seen := map[string]struct{}{}
	for i, want := range expected {
		got := columns[i]
		if _, dup := seen[got.Name]; dup {
			return fmt.Errorf("duplicate column %q", got.Name)
		}
		seen[got.Name] = struct{}{}
		if got.Name != want.name {
			return fmt.Errorf("column[%d] = %q, want %q", i, got.Name, want.name)
		}
		if got.Type != want.typeText || got.Length != want.length || got.Unsigned != want.unsigned {
			return fmt.Errorf("%s = Type %q Length %d Unsigned %v, want %q/%d/%v",
				got.Name, got.Type, got.Length, got.Unsigned, want.typeText, want.length, want.unsigned)
		}
	}
	return nil
}

func t06a17SnapshotColumns(t *testing.T) []spec.Column {
	t.Helper()
	db := openTestDB(t, t06a17Results())
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	if snapshot == nil || !snapshot.Exists {
		t.Fatalf("snapshot missing or absent: %+v", snapshot)
	}
	if err := t06a17CheckProviderColumns(snapshot.Columns); err != nil {
		t.Fatalf("provider columns: %v", err)
	}
	return snapshot.Columns
}

// TestT06A17ProviderParameterFidelity pins verbatim catalog parameter text:
// scale/second-parameter/member content survive; non-target types keep the
// established base-keyword contract. The complete-set check runs inside the
// shared snapshot path so the adjacent matrices inherit it too.
func TestT06A17ProviderParameterFidelity(t *testing.T) {
	t06a17SnapshotColumns(t)
}

// TestT06A17ProviderDistinctness asserts the merged groups stay distinguishable
// end-to-end: scale variants, case variants, and order variants never collapse.
func TestT06A17ProviderDistinctness(t *testing.T) {
	columns := t06a17SnapshotColumns(t)
	byName := map[string]spec.Column{}
	for _, column := range columns {
		byName[column.Name] = column
	}
	pairs := [][2]string{
		{"d_dec122", "d_dec123"}, {"d_dec122", "d_dec120"},
		{"f_flt102", "f_flt103"}, {"x_dbl162", "x_dbl164"},
		{"e_upper", "e_lower"}, {"e_upper", "e_order"},
		{"s_upper", "s_lower"}, {"s_upper", "s_order"},
	}
	for _, pair := range pairs {
		left, lok := byName[pair[0]]
		right, rok := byName[pair[1]]
		if !lok || !rok {
			t.Fatalf("pair %s/%s missing from provider columns", pair[0], pair[1])
		}
		if left.Type == right.Type {
			t.Fatalf("%s and %s merged to %q", pair[0], pair[1], left.Type)
		}
	}
}

// TestT06A17ProviderParamBoundary pins quote-aware boundary scanning: a member
// containing ")" or "," never ends the parameter list early, and attribute
// words inside members never set Unsigned.
func TestT06A17ProviderParamBoundary(t *testing.T) {
	columns := t06a17SnapshotColumns(t)
	byName := map[string]spec.Column{}
	for _, column := range columns {
		byName[column.Name] = column
	}
	edge, ok := byName["e_edge"]
	if !ok {
		t.Fatalf("e_edge missing from provider columns")
	}
	if edge.Type != "enum('','A,B','A)B','O''Reilly')" {
		t.Fatalf("e_edge Type = %q — member delimiters broke the parameter span", edge.Type)
	}
	for _, name := range []string{"e_attrword", "s_attrword"} {
		column, ok := byName[name]
		if !ok {
			t.Fatalf("%s missing from provider columns", name)
		}
		if column.Unsigned {
			t.Fatalf("%s Unsigned = true — attribute word inside member literal leaked", name)
		}
	}
}

// Package mysqlmeta verifies the T06-A4 provider default-identity contract:
// a stored non-NULL COLUMN_DEFAULT byte string is a literal representation,
// never proof of a SQL NULL default. The tests run the real
// Provider.LoadTableSnapshot/loadColumns against constructed database/sql
// rows — this is "real provider + constructed DB rows", not a live anchor.
package mysqlmeta

import (
	"context"
	"database/sql/driver"
	"errors"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// t06a4ColumnRows renders the information_schema.columns row shape the real
// loadColumns scans: name, type, charset, collation, comment, column_default,
// is_nullable, extra. column_default nil models a stored SQL NULL.
func t06a4ColumnRows(defaults []driver.Value) testQueryResult {
	rows := make([][]driver.Value, 0, len(defaults)+1)
	rows = append(rows, []driver.Value{"id", "int", nil, nil, "", nil, "NO", "", ""})
	for i, def := range defaults {
		name := string(rune('a' + i))
		rows = append(rows, []driver.Value{name, "varchar(8)", nil, nil, "", def, "YES", "", ""})
	}
	return testQueryResult{
		columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
		rows:    rows,
	}
}

// t06a4Results builds the canned catalog for a table whose columns carry the
// given column_default values in order (id first, then a..).
func t06a4Results(defaults []driver.Value) map[string]testQueryResult {
	return map[string]testQueryResult{
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.columns": t06a4ColumnRows(defaults),
		"from information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows:    [][]driver.Value{{"PRIMARY", int64(0), "BTREE", "id", nil, nil, "A"}},
		},
	}
}

// TestT06A4ProviderDefaultIdentityMatrix pins the stored-value contract:
// COLUMN_DEFAULT SQL NULL is the only NULL default — and it cannot be told
// from an omitted DEFAULT clause (catalog limitation, not a provider bug to
// paper over). Every non-NULL value is a literal byte representation:
// "NULL"/"null"/"NuLl" are string literals, never SQL NULL.
func TestT06A4ProviderDefaultIdentityMatrix(t *testing.T) {
	type want struct {
		hasDefault bool
		value      string
		isNull     bool
	}
	cases := []struct {
		name string
		raw  driver.Value
		want want
	}{
		{"sql_null_stores_null", nil, want{false, "", false}},
		{"text_NULL_is_literal", "NULL", want{true, "NULL", false}},
		{"text_null_lowercase", "null", want{true, "null", false}},
		{"text_NuLl_mixed", "NuLl", want{true, "NuLl", false}},
		{"text_nil_literal", "<nil>", want{true, "<nil>", false}},
		{"empty_string_literal", "", want{true, "", false}},
		{"zero_literal", "0", want{true, "0", false}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			db := openTestDB(t, t06a4Results([]driver.Value{tc.raw}))
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			if len(snapshot.Columns) != 2 {
				t.Fatalf("columns = %#v, want id + one varchar", snapshot.Columns)
			}
			got := snapshot.Columns[1]
			if got.Name != "a" || got.HasDefault != tc.want.hasDefault ||
				got.DefaultValue != tc.want.value || got.DefaultIsNull != tc.want.isNull {
				t.Fatalf("column %q = {HasDefault:%v DefaultValue:%q DefaultIsNull:%v}, want {%v %q %v}",
					got.Name, got.HasDefault, got.DefaultValue, got.DefaultIsNull,
					tc.want.hasDefault, tc.want.value, tc.want.isNull)
			}
		})
	}
}

// TestT06A4ProviderDefaultsDoNotCrossRows guards per-row isolation: one
// column's stored NULL/literal can never bleed flags into its siblings, and
// the a/b catalog ambiguity is honestly preserved — a stored SQL NULL shows
// HasDefault=false on both `a` (no clause possible) and `b` (DEFAULT NULL).
func TestT06A4ProviderDefaultsDoNotCrossRows(t *testing.T) {
	db := openTestDB(t, t06a4Results([]driver.Value{nil, nil, "NULL", "<nil>"}))
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	want := map[string][3]any{
		"id": {false, "", false},
		"a":  {false, "", false},
		"b":  {false, "", false},
		"c":  {true, "NULL", false},
		"d":  {true, "<nil>", false},
	}
	for _, column := range snapshot.Columns {
		exp, ok := want[column.Name]
		if !ok {
			t.Fatalf("unexpected column %q", column.Name)
		}
		got := [3]any{column.HasDefault, column.DefaultValue, column.DefaultIsNull}
		if got != exp {
			t.Fatalf("column %q = %v, want %v", column.Name, got, exp)
		}
	}
}

// TestT06A4ProviderColumnQueryErrorPropagates keeps the error channel
// honest: a real columns-query failure surfaces as a provider error through
// errors.Is, never as an unknown or absent snapshot.
func TestT06A4ProviderColumnQueryErrorPropagates(t *testing.T) {
	sentinel := errors.New("columns access denied")
	results := t06a4Results(nil)
	results["from information_schema.columns"] = testQueryResult{queryErr: sentinel}
	db := openTestDB(t, results)
	defer db.Close()
	_, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err == nil || !errors.Is(err, sentinel) {
		t.Fatalf("err = %v, want wrapped %v", err, sentinel)
	}
}

// Package mysqlmeta verifies the T07 catalog column facts: GENERATION_EXPRESSION
// plus EXTRA tokens feed generated storage, expression defaults, and effective
// visibility on the same single ordered COLUMNS read.
package mysqlmeta

import (
	"context"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// t07ColumnRows renders the nine-column COLUMNS row shape loadColumns scans.
func t07ColumnRows(rows [][]driver.Value) testQueryResult {
	return testQueryResult{
		columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
		rows:    rows,
	}
}

func t07Results(columnRows [][]driver.Value) map[string]testQueryResult {
	return map[string]testQueryResult{
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.columns":    t07ColumnRows(columnRows),
		"from information_schema.statistics": {columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"}},
	}
}

func t07Column(t *testing.T, snapshot *spec.TableSnapshot, name string) spec.Column {
	t.Helper()
	for _, column := range snapshot.Columns {
		if column.Name == name {
			return column
		}
	}
	t.Fatalf("column %q missing from %#v", name, snapshot.Columns)
	return spec.Column{}
}

// t07ColumnsExactly asserts the complete ordered column collection — extra,
// duplicated, reordered, or missing members all fail.
func t07ColumnsExactly(t *testing.T, snapshot *spec.TableSnapshot, names ...string) {
	t.Helper()
	if len(snapshot.Columns) != len(names) {
		t.Fatalf("columns = %#v, want exactly %v", snapshot.Columns, names)
	}
	for i, want := range names {
		if snapshot.Columns[i].Name != want {
			t.Fatalf("column[%d] = %q, want %q (full set %#v)", i, snapshot.Columns[i].Name, want, snapshot.Columns)
		}
	}
}

// TestT07ProviderGeneratedColumnFacts pins catalog generated columns:
// storage comes from the EXTRA token, the expression facts come from
// GENERATION_EXPRESSION, and the default fields stay untouched.
func TestT07ProviderGeneratedColumnFacts(t *testing.T) {
	db := openTestDB(t, t07Results([][]driver.Value{
		{"a", "int", nil, nil, "", nil, "NO", "", nil},
		{"g", "int", nil, nil, "", nil, "YES", "VIRTUAL GENERATED", "(`a` + 1)"},
		{"h", "int", nil, nil, "", nil, "YES", "STORED GENERATED", "concat(`a`,_utf8mb4\\'x\\')"},
	}))
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	t07ColumnsExactly(t, snapshot, "a", "g", "h")

	ordinary := t07Column(t, snapshot, "a")
	if ordinary.Generated != nil || ordinary.DefaultExpression != nil {
		t.Fatalf("ordinary column gained generated facts: %+v", ordinary)
	}
	if ordinary.Visibility != spec.ColumnVisibilityVisible || ordinary.VisibilityExplicit {
		t.Fatalf("ordinary column visibility = %q explicit=%v, want effective visible", ordinary.Visibility, ordinary.VisibilityExplicit)
	}

	virtual := t07Column(t, snapshot, "g")
	if virtual.Generated == nil || virtual.Generated.Storage != spec.GeneratedStorageVirtual {
		t.Fatalf("virtual generated column = %+v", virtual.Generated)
	}
	expr := virtual.Generated.Expression
	if !expr.Known || len(expr.References) != 1 || expr.References[0].Name != "a" {
		t.Fatalf("virtual generated expression = %+v", expr)
	}
	if expr.Fingerprint == "" {
		t.Fatalf("virtual generated expression missing fingerprint")
	}

	stored := t07Column(t, snapshot, "h")
	if stored.Generated == nil || stored.Generated.Storage != spec.GeneratedStorageStored {
		t.Fatalf("stored generated column = %+v", stored.Generated)
	}
	sexpr := stored.Generated.Expression
	if !sexpr.Known || len(sexpr.References) != 1 || sexpr.References[0].Name != "a" {
		t.Fatalf("stored generated refs = %+v", sexpr)
	}
	// The escaped catalog literal must decode through the recognized escape
	// layer: `concat(...)` collects the function and the `a` reference.
	foundConcat := false
	for _, fn := range sexpr.Functions {
		if fn == "concat" {
			foundConcat = true
		}
	}
	if !foundConcat {
		t.Fatalf("stored generated functions = %v, want concat", sexpr.Functions)
	}
}

// TestT07ProviderExpressionDefaultFacts pins DEFAULT_GENERATED handling: the
// raw catalog bytes stay in DefaultValue while parsed facts land in
// DefaultExpression — including escaped quote delimiters.
func TestT07ProviderExpressionDefaultFacts(t *testing.T) {
	db := openTestDB(t, t07Results([][]driver.Value{
		{"a", "int", nil, nil, "", nil, "NO", "", nil},
		{"b", "int", nil, nil, "", "( `a` + 1 )", "YES", "DEFAULT_GENERATED", nil},
		{"j", "json", nil, nil, "", "json_object(_utf8mb4\\'k\\',1)", "YES", "DEFAULT_GENERATED", nil},
		{"l", "varchar(8)", nil, nil, "", "plain", "YES", "", nil},
	}))
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}

	t07ColumnsExactly(t, snapshot, "a", "b", "j", "l")
	expr := t07Column(t, snapshot, "b")
	if !expr.HasDefault || expr.DefaultValue != "( `a` + 1 )" {
		t.Fatalf("expression default raw bytes lost: %+v", expr)
	}
	if expr.DefaultExpression == nil || !expr.DefaultExpression.Known ||
		len(expr.DefaultExpression.References) != 1 || expr.DefaultExpression.References[0].Name != "a" {
		t.Fatalf("expression default facts = %+v", expr.DefaultExpression)
	}
	if expr.DefaultExpression.Fingerprint == "" {
		t.Fatalf("expression default missing fingerprint")
	}

	json := t07Column(t, snapshot, "j")
	if json.DefaultExpression == nil || !json.DefaultExpression.Known {
		t.Fatalf("json expression default unknown: %+v", json.DefaultExpression)
	}
	foundJSON := false
	for _, fn := range json.DefaultExpression.Functions {
		if fn == "json_object" {
			foundJSON = true
		}
	}
	if !foundJSON {
		t.Fatalf("json default functions = %v, want json_object", json.DefaultExpression.Functions)
	}
	if json.DefaultValue != "json_object(_utf8mb4\\'k\\',1)" {
		t.Fatalf("raw default bytes = %q, want verbatim catalog text", json.DefaultValue)
	}

	literal := t07Column(t, snapshot, "l")
	if !literal.HasDefault || literal.DefaultValue != "plain" || literal.DefaultExpression != nil {
		t.Fatalf("literal default = %+v, want plain literal only", literal)
	}
}

// TestT07ProviderUndecodableCatalogExpressions pins the failure boundary: a
// generated or expression-default marker with absent/unparseable expression
// text produces explicit unknown facts, never nil (absence) or known-empty.
func TestT07ProviderUndecodableCatalogExpressions(t *testing.T) {
	db := openTestDB(t, t07Results([][]driver.Value{
		{"g", "int", nil, nil, "", nil, "YES", "STORED GENERATED", nil},
		{"d", "int", nil, nil, "", nil, "YES", "DEFAULT_GENERATED", nil},
	}))
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	t07ColumnsExactly(t, snapshot, "g", "d")
	g := t07Column(t, snapshot, "g")
	if g.Generated == nil || g.Generated.Expression.Known {
		t.Fatalf("generated column without expression text = %+v, want explicit unknown", g.Generated)
	}
	d := t07Column(t, snapshot, "d")
	if d.DefaultExpression == nil || d.DefaultExpression.Known {
		t.Fatalf("default-generated column without text = %+v, want explicit unknown", d.DefaultExpression)
	}
}

// TestT07ProviderInvisibleColumn pins effective visibility from EXTRA: the
// INVISIBLE token is the only marker; its absence on a complete row is
// effective-visible, and the catalog never proves explicit declaration.
func TestT07ProviderInvisibleColumn(t *testing.T) {
	db := openTestDB(t, t07Results([][]driver.Value{
		{"a", "int", nil, nil, "", nil, "NO", "", nil},
		{"i", "int", nil, nil, "", nil, "YES", "INVISIBLE", nil},
	}))
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	t07ColumnsExactly(t, snapshot, "a", "i")
	a := t07Column(t, snapshot, "a")
	if a.Visibility != spec.ColumnVisibilityVisible || a.VisibilityExplicit {
		t.Fatalf("visible column = visibility %q explicit %v", a.Visibility, a.VisibilityExplicit)
	}
	i := t07Column(t, snapshot, "i")
	if i.Visibility != spec.ColumnVisibilityInvisible || i.VisibilityExplicit {
		t.Fatalf("invisible column = visibility %q explicit %v", i.Visibility, i.VisibilityExplicit)
	}
}

// Package mysqlmeta verifies the T08-R1 comparable literal identity the
// provider publishes: catalog COLUMN_DEFAULT bytes are already decoded
// literal values, and the column's own base type fixes the comparison
// domain — keyword-looking bytes on a non-temporal column stay literal.
// The tests run the real Provider.LoadTableSnapshot/loadColumns against
// constructed database/sql rows — real provider, constructed DB rows.
package mysqlmeta

import (
	"context"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// t08r1ColumnRows renders full-shape information_schema.columns rows where
// each entry carries its own column_type, column_default, and extra — the
// provider must read all three to classify the comparable identity.
func t08r1Results(columns [][3]string) map[string]testQueryResult {
	rows := make([][]driver.Value, 0, len(columns)+1)
	rows = append(rows, []driver.Value{"id", "int", nil, nil, "", nil, "NO", "", ""})
	for i, col := range columns {
		var def driver.Value
		if col[1] != "<sql-null>" {
			def = col[1]
		}
		rows = append(rows, []driver.Value{string(rune('a' + i)), col[0], nil, nil, "", def, "YES", col[2], ""})
	}
	return map[string]testQueryResult{
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.columns": {
			columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows:    rows,
		},
		"from information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows:    [][]driver.Value{{"PRIMARY", int64(0), "BTREE", "id", nil, nil, "A"}},
		},
	}
}

// TestT08R1ProviderLiteralIdentity pins the identity-fact domain: the
// stored bytes are the literal identity verbatim and the base type —
// parameters and attribute text stripped — names the kind. No quoting,
// unescaping, or content guessing applies. A recorded numeric fact like
// 1.50 is the catalog's own encoding; whether a pair shares a proven
// encoding is the comparison's domain check (T08-R2), not this seam.
func TestT08R1ProviderLiteralIdentity(t *testing.T) {
	cases := []struct {
		name     string
		colType  string
		def      string // "<sql-null>" models a NULL row value
		extra    string
		wantKind string // "" = expect nil DefaultLiteral
		wantVal  string
	}{
		{"varchar_literal", "varchar(16)", "x", "", spec.LiteralDefaultString, "x"},
		{"varchar_empty", "varchar(16)", "", "", spec.LiteralDefaultString, ""},
		{"varchar_text_null", "varchar(16)", "NULL", "", spec.LiteralDefaultString, "NULL"},
		{"varchar_content_quotes", "varchar(16)", "'x'", "", spec.LiteralDefaultString, "'x'"},
		{"varchar_quote_in_content", "varchar(16)", "O'Reilly", "", spec.LiteralDefaultString, "O'Reilly"},
		{"int_numeric", "int", "7", "", spec.LiteralDefaultNumeric, "7"},
		{"bigint_unsigned_numeric", "bigint unsigned", "18446744073709551615", "", spec.LiteralDefaultNumeric, "18446744073709551615"},
		{"decimal_param_numeric", "decimal(10,2)", "1.50", "", spec.LiteralDefaultNumeric, "1.50"},
		{"char_string", "char(4)", "ab", "", spec.LiteralDefaultString, "ab"},
		{"enum_param_string", "enum('a','b')", "b", "", spec.LiteralDefaultString, "b"},
		{"sql_null_row", "varchar(16)", "<sql-null>", "", "", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			db := openTestDB(t, t08r1Results([][3]string{{tc.colType, tc.def, tc.extra}}))
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			if len(snapshot.Columns) != 2 {
				t.Fatalf("columns = %#v, want id + one column", snapshot.Columns)
			}
			got := snapshot.Columns[1]
			if tc.wantKind == "" {
				if got.DefaultLiteral != nil {
					t.Fatalf("column %q DefaultLiteral = %+v, want nil (SQL NULL row)", got.Name, got.DefaultLiteral)
				}
				return
			}
			if got.DefaultLiteral == nil {
				t.Fatalf("column %q DefaultLiteral = nil, want {%s %q}", got.Name, tc.wantKind, tc.wantVal)
			}
			if got.DefaultLiteral.Kind != tc.wantKind || got.DefaultLiteral.Value != tc.wantVal {
				t.Fatalf("column %q DefaultLiteral = {%q %q}, want {%q %q}",
					got.Name, got.DefaultLiteral.Kind, got.DefaultLiteral.Value, tc.wantKind, tc.wantVal)
			}
			// The display contract is untouched: DefaultValue keeps the
			// same verbatim catalog bytes the identity decodes from.
			if got.DefaultValue != tc.def {
				t.Fatalf("column %q DefaultValue = %q, want verbatim %q", got.Name, got.DefaultValue, tc.def)
			}
		})
	}
}

// TestT08R1ProviderTemporalGate pins the CURRENT_TIMESTAMP classification:
// only temporal base types promote the stored bytes to the temporal
// marker, and the marker is not a literal. Parameterized temporal types
// (datetime(6)) must still resolve through the base type.
func TestT08R1ProviderTemporalGate(t *testing.T) {
	cases := []struct {
		name          string
		colType       string
		wantTemporal  bool
		wantKindIsSet bool
	}{
		{"datetime_is_temporal", "datetime", true, false},
		{"datetime6_is_temporal", "datetime(6)", true, false},
		{"timestamp_is_temporal", "timestamp", true, false},
		{"varchar_ct_is_string_literal", "varchar(32)", false, true},
		{"char_ct_is_string_literal", "char(17)", false, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			db := openTestDB(t, t08r1Results([][3]string{{tc.colType, "current_timestamp", ""}}))
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			got := snapshot.Columns[1]
			if got.DefaultIsCurrentTimestamp != tc.wantTemporal {
				t.Fatalf("column %q(%s) DefaultIsCurrentTimestamp = %v, want %v", got.Name, tc.colType, got.DefaultIsCurrentTimestamp, tc.wantTemporal)
			}
			if tc.wantTemporal {
				if got.DefaultLiteral != nil {
					t.Fatalf("temporal %s carried literal identity %+v", tc.colType, got.DefaultLiteral)
				}
				return
			}
			if got.DefaultLiteral == nil || got.DefaultLiteral.Kind != spec.LiteralDefaultString || got.DefaultLiteral.Value != "current_timestamp" {
				t.Fatalf("non-temporal %s literal identity = %+v, want {string current_timestamp}", tc.colType, got.DefaultLiteral)
			}
		})
	}
}

// TestT08R1ProviderExpressionRoutesOffLiteral pins the DEFAULT_GENERATED
// boundary: an expression default carries the parsed expression fact and
// never a literal identity, while undecodable/absent expression text keeps
// the explicit unknown fact instead of falling into a literal.
func TestT08R1ProviderExpressionRoutesOffLiteral(t *testing.T) {
	cases := []struct {
		name       string
		def        string
		wantExpr   bool
		wantExprOK bool
	}{
		{"expression_generated", "(uuid())", true, true},
		{"expression_undecodable", "", true, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			db := openTestDB(t, t08r1Results([][3]string{{"int", tc.def, "DEFAULT_GENERATED"}}))
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectMySQL, "golden", "t")
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			got := snapshot.Columns[1]
			if (got.DefaultExpression != nil) != tc.wantExpr {
				t.Fatalf("DefaultExpression = %+v, want present=%v", got.DefaultExpression, tc.wantExpr)
			}
			if got.DefaultExpression != nil && got.DefaultExpression.Known != tc.wantExprOK {
				t.Fatalf("DefaultExpression.Known = %v, want %v", got.DefaultExpression.Known, tc.wantExprOK)
			}
			if got.DefaultLiteral != nil {
				t.Fatalf("expression default carried literal identity %+v", got.DefaultLiteral)
			}
		})
	}
}

// Package mysqlmeta verifies the T09-R1 provider member-fact mapping.
package mysqlmeta

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// The R1 classification table: each member row lands exactly the mark its
// catalog facts prove — nothing defaults to plain.
func TestT09R1ProviderMemberRowClassification(t *testing.T) {
	str := func(v string) sql.NullString { return sql.NullString{String: v, Valid: true} }
	int64n := func(v int64) sql.NullInt64 { return sql.NullInt64{Int64: v, Valid: true} }

	cases := []struct {
		name          string
		row           indexMemberRow
		wantColumns   []string
		wantPrefix    int
		wantDesc      int
		wantExprCount int
		wantExprFlag  bool
		wantUnmodeled int
	}{
		{
			name:        "plain ascending whole column",
			row:         indexMemberRow{columnName: str("c"), collation: str("A")},
			wantColumns: []string{"c"},
		},
		{
			name:        "prefix length marks PrefixParts but keeps the column",
			row:         indexMemberRow{columnName: str("c"), collation: str("A"), subPart: int64n(3)},
			wantColumns: []string{"c"},
			wantPrefix:  1,
		},
		{
			name:        "descending collation marks DescParts",
			row:         indexMemberRow{columnName: str("c"), collation: str("D")},
			wantColumns: []string{"c"},
			wantDesc:    1,
		},
		{
			name:          "NULL column_name is an expression key part",
			row:           indexMemberRow{collation: str("A")},
			wantExprCount: 1,
			wantExprFlag:  true,
		},
		{
			name:          "NULL collation on a named member is unclassifiable",
			row:           indexMemberRow{columnName: str("c")},
			wantColumns:   []string{"c"},
			wantUnmodeled: 1,
		},
		{
			name:          "unrecognized collation value is unclassifiable",
			row:           indexMemberRow{columnName: str("c"), collation: str("X")},
			wantColumns:   []string{"c"},
			wantUnmodeled: 1,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			indexes := make(map[string]*spec.Index)
			order := make([]string, 0)
			accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i", 1, "BTREE", tc.row, nil, nil)
			index := indexes["i"]
			if index == nil {
				t.Fatalf("index not accumulated")
			}
			// Aggregate marks derive from the member list — the same
			// normalization loadIndexes applies on drain.
			index.SetKeyParts(index.KeyParts)
			if len(index.Columns) != len(tc.wantColumns) ||
				(len(tc.wantColumns) > 0 && index.Columns[0] != tc.wantColumns[0]) {
				t.Fatalf("columns = %v, want %v", index.Columns, tc.wantColumns)
			}
			if index.PrefixParts != tc.wantPrefix {
				t.Fatalf("PrefixParts = %d, want %d", index.PrefixParts, tc.wantPrefix)
			}
			if index.DescParts != tc.wantDesc {
				t.Fatalf("DescParts = %d, want %d", index.DescParts, tc.wantDesc)
			}
			if index.ExpressionCount != tc.wantExprCount || index.HasExpressionKeys != tc.wantExprFlag {
				t.Fatalf("expression marks = %d/%v, want %d/%v",
					index.ExpressionCount, index.HasExpressionKeys, tc.wantExprCount, tc.wantExprFlag)
			}
			if index.UnmodeledKeyParts != tc.wantUnmodeled {
				t.Fatalf("UnmodeledKeyParts = %d, want %d", index.UnmodeledKeyParts, tc.wantUnmodeled)
			}
		})
	}
}

// A loaded index built from real-shaped rows must expose non-plain marks the
// comparability gate reads — a prefix row can never scan back in as a plain
// key definition.
func TestT09R1ProviderLoadIndexesMarksNonPlain(t *testing.T) {
	db := openTestDB(t, map[string]testQueryResult{
		"select version()": {
			columns: []string{"version()"},
			rows:    [][]driver.Value{{"8.0.46"}},
		},
		"from information_schema.tables": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		},
		"from information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows: [][]driver.Value{
				{"i_prefix", int64(1), "BTREE", "c", int64(30), int64(8), "A"},
				{"i_plain", int64(1), "BTREE", "c", int64(30), nil, "A"},
			},
		},
		"from information_schema.columns": {
			columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows:    [][]driver.Value{{"c", "int", nil, nil, "", nil, "YES", "", ""}},
		},
	})
	defer db.Close()

	provider := NewProvider(db)
	snapshot, err := provider.LoadTableSnapshot(context.Background(), spec.DialectMySQL, "app", "t")
	if err != nil {
		t.Fatalf("load snapshot: %v", err)
	}
	if len(snapshot.Indexes) != 2 {
		t.Fatalf("expected two indexes, got %#v", snapshot.Indexes)
	}
	var prefix, plain *spec.Index
	for i := range snapshot.Indexes {
		switch snapshot.Indexes[i].Name {
		case "i_prefix":
			prefix = &snapshot.Indexes[i]
		case "i_plain":
			plain = &snapshot.Indexes[i]
		}
	}
	if prefix == nil || prefix.PrefixParts != 1 || len(prefix.Columns) != 1 {
		t.Fatalf("prefix index must carry PrefixParts=1 with its column, got %#v", prefix)
	}
	if plain == nil || plain.PrefixParts != 0 || plain.DescParts != 0 ||
		plain.ExpressionCount != 0 || plain.UnmodeledKeyParts != 0 {
		t.Fatalf("plain index must carry no non-plain marks, got %#v", plain)
	}
}

// Package mysql tests the T10-R2 provider corrections: the STATISTICS
// member classification must distinguish a SQL NULL column_name (expression
// member), TiDB's literal 'NULL' text for expression members, and a real
// column literally named `NULL` — decided on verifiable catalog facts
// (expression text, the loaded column set), never on the literal alone;
// and the TiDB PKIsHandle loader must keep the handle answer unknown
// whenever the clustered catalog fact is missing or NULL.
package mysqlmeta

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

func t10r2Str(v string) sql.NullString { return sql.NullString{String: v, Valid: true} }
func t10r2Int(v int64) sql.NullInt64   { return sql.NullInt64{Int64: v, Valid: true} }
func t10r2NullStr() sql.NullString     { return sql.NullString{} }

// D: a real column named `NULL` must load as a plain column member —
// TiDB emits the same literal for expression members, so the literal alone
// can never classify the row; the loaded column set is the arbiter.
func TestT10R2LiteralNullColumnNameIsColumn(t *testing.T) {
	t.Parallel()
	columns := []spec.Column{{Name: "NULL", Type: "int", NotNull: true}}
	cases := []struct {
		name       string
		memberName string
	}{
		{name: "uppercase NULL", memberName: "NULL"},
		{name: "lowercase null", memberName: "null"},
		{name: "mixed NuLl", memberName: "NuLl"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			indexes := make(map[string]*spec.Index)
			order := make([]string, 0)
			// The catalog carries the member with an ascending collation and
			// a SQL NULL expression column — the shape a real reserved-name
			// column produces.
			accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_null", 1, "BTREE",
				indexMemberRow{columnName: t10r2Str(tc.memberName), collation: t10r2Str("A")},
				nil, columns)
			index := indexes["i_null"]
			index.SetKeyParts(index.KeyParts)
			if len(index.Columns) != 1 || index.Columns[0] != tc.memberName {
				t.Fatalf("Columns = %v, want [%s]", index.Columns, tc.memberName)
			}
			if index.ExpressionCount != 0 || index.HasExpressionKeys {
				t.Fatalf("a proven column must not load as expression, got %+v", index)
			}
			part := index.KeyParts[0]
			if part.Kind != spec.IndexKeyPartColumn || part.Column != tc.memberName {
				t.Fatalf("KeyPart = %+v, want column member %q", part, tc.memberName)
			}
		})
	}
}

// D: literal 'NULL' with catalog expression text is the TiDB expression
// member shape — it must classify as expression even when a column named
// NULL exists (the catalog text is authoritative).
func TestT10R2LiteralNullWithExpressionTextIsExpression(t *testing.T) {
	t.Parallel()
	columns := []spec.Column{
		{Name: "NULL", Type: "int", NotNull: true},
		{Name: "a", Type: "int", NotNull: true},
	}
	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_expr", 1, "BTREE",
		indexMemberRow{
			columnName: t10r2Str("NULL"), collation: t10r2Str("A"),
			expression: t10r2Str("upper(`a`)"),
		}, nil, columns)
	index := indexes["i_expr"]
	index.SetKeyParts(index.KeyParts)
	if index.ExpressionCount != 1 || !index.HasExpressionKeys {
		t.Fatalf("expression text must classify the member as expression, got %+v", index)
	}
	if len(index.Columns) != 0 {
		t.Fatalf("expression member must not append the sentinel name, got %v", index.Columns)
	}
}

// D: literal 'NULL' without expression text and without a vouched column is
// unprovable — unmodeled, never a guessed column or expression.
func TestT10R2LiteralNullUnprovenIsUnmodeled(t *testing.T) {
	t.Parallel()
	columns := []spec.Column{{Name: "a", Type: "int", NotNull: true}}
	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_x", 1, "BTREE",
		indexMemberRow{columnName: t10r2Str("NULL"), collation: t10r2Str("A")},
		nil, columns)
	index := indexes["i_x"]
	index.SetKeyParts(index.KeyParts)
	if index.UnmodeledKeyParts != 1 {
		t.Fatalf("unproven literal NULL must stay unmodeled, got %+v", index)
	}
	if len(index.Columns) != 0 || index.ExpressionCount != 0 {
		t.Fatalf("unmodeled member must not invent identity, got %+v", index)
	}
}

// D: a SQL NULL column_name without expression text is still an expression
// member (the catalog stores no column name for one) — marked, not
// fabricated.
func TestT10R2SQLNullColumnNameWithoutExpression(t *testing.T) {
	t.Parallel()
	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_e", 1, "BTREE",
		indexMemberRow{columnName: t10r2NullStr(), collation: t10r2Str("A")},
		nil, nil)
	index := indexes["i_e"]
	index.SetKeyParts(index.KeyParts)
	if index.ExpressionCount != 1 || index.KeyParts[0].Kind != spec.IndexKeyPartExpression {
		t.Fatalf("SQL NULL column_name is an expression member, got %+v", index)
	}
}

// D: a mixed member list — plain column, literal-NULL column, and a SQL
// NULL expression member — keeps each identity and ordinal.
func TestT10R2MixedMembersKeepIdentities(t *testing.T) {
	t.Parallel()
	columns := []spec.Column{
		{Name: "a", Type: "int", NotNull: true},
		{Name: "NULL", Type: "int", NotNull: true},
	}
	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i", 1, "BTREE",
		indexMemberRow{columnName: t10r2Str("a"), collation: t10r2Str("A")}, nil, columns)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i", 1, "BTREE",
		indexMemberRow{columnName: t10r2Str("NULL"), collation: t10r2Str("A")}, nil, columns)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i", 1, "BTREE",
		indexMemberRow{columnName: t10r2NullStr(), collation: t10r2Str("A"), expression: t10r2Str("`a`+1")},
		nil, columns)
	index := indexes["i"]
	index.SetKeyParts(index.KeyParts)
	if len(index.KeyParts) != 3 {
		t.Fatalf("KeyParts = %d, want 3", len(index.KeyParts))
	}
	if index.KeyParts[0].Kind != spec.IndexKeyPartColumn || index.KeyParts[0].Column != "a" {
		t.Fatalf("member 1 = %+v", index.KeyParts[0])
	}
	if index.KeyParts[1].Kind != spec.IndexKeyPartColumn || index.KeyParts[1].Column != "NULL" {
		t.Fatalf("member 2 (real NULL column) = %+v", index.KeyParts[1])
	}
	if index.KeyParts[2].Kind != spec.IndexKeyPartExpression || index.KeyParts[2].Expression == nil {
		t.Fatalf("member 3 (expression) = %+v", index.KeyParts[2])
	}
	if index.KeyParts[2].Ordinal != 3 {
		t.Fatalf("expression ordinal = %d, want 3", index.KeyParts[2].Ordinal)
	}
}

// B4: the clustered catalog row missing or NULL must leave the handle
// answer unknown — a boolean false was a fabricated "real object exists".
func TestT10R2TiDBHandleUnknownOnMissingClusteredRow(t *testing.T) {
	t.Parallel()
	base := map[string]testQueryResult{
		"select engine, table_collation": {
			columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows:    [][]driver.Value{{"InnoDB", "utf8mb4_bin", "", nil, "", nil, "BASE TABLE"}},
		},
		"information_schema.columns": {
			columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows: [][]driver.Value{
				{"id", "int(11)", nil, nil, "", nil, "NO", "", nil},
			},
		},
		"column_name = 'IS_VISIBLE'": {
			columns: []string{"count"},
			rows:    [][]driver.Value{{1}},
		},
		"column_name = 'EXPRESSION'": {
			columns: []string{"count"},
			rows:    [][]driver.Value{{1}},
		},
		"information_schema.statistics": {
			columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation", "is_visible", "expression"},
			rows: [][]driver.Value{
				{"PRIMARY", 0, "BTREE", "id", nil, nil, "A", "YES", nil},
			},
		},
		"information_schema.partitions": {
			columns: []string{"partition_method", "partition_name", "subpartition_name"},
		},
		"table_constraints": {
			columns: []string{"count"},
			rows:    [][]driver.Value{{1}},
		},
	}

	// The clustered row absent → unknown, never a guessed real object.
	missing := map[string]testQueryResult{}
	for k, v := range base {
		missing[k] = v
	}
	db := openTestDB(t, missing)
	defer db.Close()
	snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	if !snapshot.PrimaryKeyHandleUnknown {
		t.Fatalf("missing TIDB_INDEXES row must leave the handle unknown, got handle=%v unknown=%v",
			snapshot.PrimaryKeyIsHandle, snapshot.PrimaryKeyHandleUnknown)
	}

	// A NULL clustered value → unknown.
	nullRow := map[string]testQueryResult{}
	for k, v := range base {
		nullRow[k] = v
	}
	nullRow["information_schema.tidb_indexes"] = testQueryResult{
		columns: []string{"clustered"},
		rows:    [][]driver.Value{{nil}},
	}
	db = openTestDB(t, nullRow)
	defer db.Close()
	snapshot, err = NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	if !snapshot.PrimaryKeyHandleUnknown {
		t.Fatalf("NULL clustered must leave the handle unknown, got handle=%v unknown=%v",
			snapshot.PrimaryKeyIsHandle, snapshot.PrimaryKeyHandleUnknown)
	}

	// clustered=yes + single int column → the handle (determined true).
	handleYes := map[string]testQueryResult{}
	for k, v := range base {
		handleYes[k] = v
	}
	handleYes["information_schema.tidb_indexes"] = testQueryResult{
		columns: []string{"clustered"},
		rows:    [][]driver.Value{{"YES"}},
	}
	db = openTestDB(t, handleYes)
	defer db.Close()
	snapshot, err = NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	if !snapshot.PrimaryKeyIsHandle || snapshot.PrimaryKeyHandleUnknown {
		t.Fatalf("clustered single-int PK must resolve to handle, got handle=%v unknown=%v",
			snapshot.PrimaryKeyIsHandle, snapshot.PrimaryKeyHandleUnknown)
	}

	// clustered=no → a real PRIMARY object (determined false).
	handleNo := map[string]testQueryResult{}
	for k, v := range base {
		handleNo[k] = v
	}
	handleNo["information_schema.tidb_indexes"] = testQueryResult{
		columns: []string{"clustered"},
		rows:    [][]driver.Value{{"NO"}},
	}
	db = openTestDB(t, handleNo)
	defer db.Close()
	snapshot, err = NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
	if err != nil {
		t.Fatalf("LoadTableSnapshot: %v", err)
	}
	if snapshot.PrimaryKeyIsHandle || snapshot.PrimaryKeyHandleUnknown {
		t.Fatalf("clustered=no must resolve to a real object, got handle=%v unknown=%v",
			snapshot.PrimaryKeyIsHandle, snapshot.PrimaryKeyHandleUnknown)
	}
}

// Package mysql verifies the T10-R4 provider fact corrections: a STATISTICS
// expression member whose COLLATION is NULL or unrecognized is still an
// expression key part — kind, identity, dependencies, and multi-valued
// marks survive while only the direction answer is withheld — the
// TIDB_INDEXES clustered row answers the clustered-storage fact separately
// from the handle answer (a common-handle PK is a clustered real object),
// and the table_constraints pk-presence matrix binds a `primary`-fold
// member row to the PK identity only under a proven PRIMARY KEY constraint
// with exactly one fold (proven-absent keeps folds secondary, zero folds
// prove no PK object, unanswerable or multi-fold states withhold all three
// primary facts).
package mysqlmeta

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// D: an unproven direction does not demote the member — the catalog row is
// still an expression key part whose sort direction the model cannot
// assert, so kind stays expression and DirectionUnknown records the
// withheld half. Identity, references, and multi-valued marks are
// unaffected by the missing direction.
func TestT10R4DirectionUnknownExpressionKeepsIdentity(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name                 string
		collation            sql.NullString
		wantDesc             bool
		wantDirectionUnknown bool
	}{
		{name: "NULL collation", collation: t10r2NullStr(), wantDirectionUnknown: true},
		{name: "unrecognized collation", collation: t10r2Str("X"), wantDirectionUnknown: true},
		{name: "A ascending proven", collation: t10r2Str("A"), wantDirectionUnknown: false},
		{name: "D descending proven", collation: t10r2Str("D"), wantDesc: true, wantDirectionUnknown: false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			indexes := make(map[string]*spec.Index)
			order := make([]string, 0)
			accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_e", 1, "BTREE",
				indexMemberRow{
					columnName: t10r2NullStr(), collation: tc.collation,
					expression: t10r2Str("`b`+1"),
				}, nil, nil)
			index := indexes["i_e"]
			index.SetKeyParts(index.KeyParts)
			if len(index.KeyParts) != 1 {
				t.Fatalf("KeyParts = %d, want 1", len(index.KeyParts))
			}
			part := index.KeyParts[0]
			if part.Kind != spec.IndexKeyPartExpression {
				t.Fatalf("an unproven direction keeps kind=expression, got %s", part.Kind)
			}
			if part.DirectionUnknown != tc.wantDirectionUnknown {
				t.Fatalf("DirectionUnknown = %v, want %v", part.DirectionUnknown, tc.wantDirectionUnknown)
			}
			if part.Descending != tc.wantDesc {
				t.Fatalf("Descending = %v, want %v", part.Descending, tc.wantDesc)
			}
			if part.Expression == nil {
				t.Fatalf("expression identity must survive the missing direction, got %+v", part)
			}
			if index.ExpressionCount != 1 || index.UnmodeledKeyParts != 0 {
				t.Fatalf("aggregate marks must count the expression member, got %+v", index)
			}
			wantDirParts := 0
			if tc.wantDirectionUnknown {
				wantDirParts = 1
			}
			if index.DirectionUnknownParts != wantDirParts {
				t.Fatalf("DirectionUnknownParts = %d, want %d", index.DirectionUnknownParts, wantDirParts)
			}
		})
	}
}

// D: multi-valued marks survive across the whole direction matrix — a
// cast-array expression keeps its MV aspect and counts whether the
// direction is proven (A/D) or withheld (NULL/unrecognized).
func TestT10R4DirectionUnknownMultiValuedKeepsMarks(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name                 string
		collation            sql.NullString
		wantDirectionUnknown bool
	}{
		{name: "NULL collation", collation: t10r2NullStr(), wantDirectionUnknown: true},
		{name: "unrecognized collation", collation: t10r2Str("X"), wantDirectionUnknown: true},
		{name: "A ascending proven", collation: t10r2Str("A"), wantDirectionUnknown: false},
		{name: "D descending proven", collation: t10r2Str("D"), wantDirectionUnknown: false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			indexes := make(map[string]*spec.Index)
			order := make([]string, 0)
			accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_mv", 1, "BTREE",
				indexMemberRow{
					columnName: t10r2NullStr(), collation: tc.collation,
					expression: t10r2Str("cast(`a` as unsigned array)"),
				}, nil, nil)
			index := indexes["i_mv"]
			index.SetKeyParts(index.KeyParts)
			part := index.KeyParts[0]
			if part.Kind != spec.IndexKeyPartExpression {
				t.Fatalf("multi-valued member kind = %s, want expression", part.Kind)
			}
			if part.DirectionUnknown != tc.wantDirectionUnknown {
				t.Fatalf("DirectionUnknown = %v, want %v", part.DirectionUnknown, tc.wantDirectionUnknown)
			}
			if !part.MultiValued || index.MultiValuedParts != 1 || part.MultiValuedCastType == "" {
				t.Fatalf("multi-valued marks must survive the missing direction, got %+v", index)
			}
			if index.ExpressionCount != 1 || index.UnmodeledKeyParts != 0 {
				t.Fatalf("aggregates must stay consistent with the member facts, got %+v", index)
			}
			wantDirParts := 0
			if tc.wantDirectionUnknown {
				wantDirParts = 1
			}
			if index.DirectionUnknownParts != wantDirParts {
				t.Fatalf("DirectionUnknownParts = %d, want %d", index.DirectionUnknownParts, wantDirParts)
			}
		})
	}
}

// D control: a named member with a NULL collation still stays unmodeled —
// the direction-unknown fix reaches expression members only, never
// relabels an unclassifiable named row as an expression.
func TestT10R4NamedUnmodeledMemberStaysUnmodeled(t *testing.T) {
	t.Parallel()
	columns := []spec.Column{{Name: "b", Type: "int", NotNull: true}}
	indexes := make(map[string]*spec.Index)
	order := make([]string, 0)
	accumulateIndexRow(indexes, &order, spec.DialectMySQL, "i_b", 1, "BTREE",
		indexMemberRow{columnName: t10r2Str("b"), collation: t10r2NullStr()},
		nil, columns)
	index := indexes["i_b"]
	index.SetKeyParts(index.KeyParts)
	part := index.KeyParts[0]
	if part.Kind != spec.IndexKeyPartUnmodeled || part.Column != "b" {
		t.Fatalf("named NULL-collation member = %+v, want unmodeled column member", part)
	}
	if index.UnmodeledKeyParts != 1 || index.ExpressionCount != 0 || index.DirectionUnknownParts != 0 {
		t.Fatalf("named unmodeled member must not gain expression marks, got %+v", index)
	}
}

// C: the TIDB_INDEXES clustered row answers clustered storage separately
// from the handle question — a clustered non-single-int PK is a
// common-handle real object (clustered=true, handle=false), a clustered
// single-int is both, and a missing/NULL row leaves the clustered answer
// unknown exactly like the handle answer.
func TestT10R4TiDBClusteredFactMatrix(t *testing.T) {
	t.Parallel()
	base := func(columnRows, statRows [][]driver.Value) map[string]testQueryResult {
		return map[string]testQueryResult{
			"select engine, table_collation": {
				columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
				rows:    [][]driver.Value{{"InnoDB", "utf8mb4_bin", "", nil, "", nil, "BASE TABLE"}},
			},
			"information_schema.columns": {
				columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
				rows:    columnRows,
			},
			"column_name = 'IS_VISIBLE'": {
				columns: []string{"count"},
				rows:    [][]driver.Value{{1}},
			},
			"column_name = 'EXPRESSION'": {
				columns: []string{"count"},
				rows:    [][]driver.Value{{1}},
			},
			"information_schema.statistics": {
				columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation", "is_visible", "expression"},
				rows:    statRows,
			},
			"information_schema.partitions": {
				columns: []string{"partition_method", "partition_name", "subpartition_name"},
			},
			"table_constraints": {
				columns: []string{"count"},
				rows:    [][]driver.Value{{1}},
			},
		}
	}
	clusteredRow := func(value driver.Value) testQueryResult {
		return testQueryResult{columns: []string{"clustered"}, rows: [][]driver.Value{{value}}}
	}
	varcharPK := func() (cols, stats [][]driver.Value) {
		return [][]driver.Value{{"id", "varchar(32)", nil, nil, "", nil, "NO", "", nil}},
			[][]driver.Value{{"PRIMARY", 0, "BTREE", "id", nil, nil, "A", "YES", nil}}
	}
	intPK := func() (cols, stats [][]driver.Value) {
		return [][]driver.Value{{"id", "int(11)", nil, nil, "", nil, "NO", "", nil}},
			[][]driver.Value{{"PRIMARY", 0, "BTREE", "id", nil, nil, "A", "YES", nil}}
	}
	compositePK := func() (cols, stats [][]driver.Value) {
		return [][]driver.Value{
				{"id", "int(11)", nil, nil, "", nil, "NO", "", nil},
				{"b", "varchar(32)", nil, nil, "", nil, "NO", "", nil},
			}, [][]driver.Value{
				{"PRIMARY", 0, "BTREE", "id", nil, nil, "A", "YES", nil},
				{"PRIMARY", 0, "BTREE", "b", nil, nil, "A", "YES", nil},
			}
	}
	cases := []struct {
		name             string
		queries          map[string]testQueryResult
		wantClustered    bool
		wantClusteredUnk bool
		wantHandle       bool
		wantHandleUnk    bool
	}{
		{
			name:          "clustered yes + varchar PK is a common-handle real object (P5)",
			queries:       withQuery(base(varcharPK()), "information_schema.tidb_indexes", clusteredRow("YES")),
			wantClustered: true, wantHandle: false,
		},
		{
			name:          "clustered yes + composite PK is a common-handle real object (P6)",
			queries:       withQuery(base(compositePK()), "information_schema.tidb_indexes", clusteredRow("YES")),
			wantClustered: true, wantHandle: false,
		},
		{
			name:          "clustered yes + single int is the handle",
			queries:       withQuery(base(intPK()), "information_schema.tidb_indexes", clusteredRow("YES")),
			wantClustered: true, wantHandle: true,
		},
		{
			name: "clustered no is nonclustered storage",
			queries: withQuery(
				withQuery(base(varcharPK()), "information_schema.tidb_indexes", clusteredRow("NO")),
				"tidb_pk_type", testQueryResult{columns: []string{"tidb_pk_type"}, rows: [][]driver.Value{{"NONCLUSTERED"}}}),
			wantClustered: false, wantHandle: false,
		},
		{
			name:             "missing clustered row leaves both answers unknown",
			queries:          base(varcharPK()),
			wantClusteredUnk: true, wantHandleUnk: true,
		},
		{
			name:             "NULL clustered value leaves both answers unknown",
			queries:          withQuery(base(varcharPK()), "information_schema.tidb_indexes", clusteredRow(nil)),
			wantClusteredUnk: true, wantHandleUnk: true,
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			db := openTestDB(t, tc.queries)
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			if snapshot.PrimaryKeyClustered != tc.wantClustered {
				t.Fatalf("PrimaryKeyClustered = %v, want %v", snapshot.PrimaryKeyClustered, tc.wantClustered)
			}
			if snapshot.PrimaryKeyClusteredUnknown != tc.wantClusteredUnk {
				t.Fatalf("PrimaryKeyClusteredUnknown = %v, want %v",
					snapshot.PrimaryKeyClusteredUnknown, tc.wantClusteredUnk)
			}
			if snapshot.PrimaryKeyIsHandle != tc.wantHandle || snapshot.PrimaryKeyHandleUnknown != tc.wantHandleUnk {
				t.Fatalf("handle = %v unknown=%v, want %v/%v",
					snapshot.PrimaryKeyIsHandle, snapshot.PrimaryKeyHandleUnknown,
					tc.wantHandle, tc.wantHandleUnk)
			}
		})
	}
}

// withQuery overlays one stubbed query result onto a base map.
func withQuery(base map[string]testQueryResult, key string, result testQueryResult) map[string]testQueryResult {
	out := make(map[string]testQueryResult, len(base)+1)
	for k, v := range base {
		out[k] = v
	}
	out[key] = result
	return out
}

// Spec-review residual pinned: on TiDB a secondary can literally own
// `primary` (RENAME … TO `primary` is legal on PK-less and PKIsHandle
// tables), so the catalog name alone cannot promote — the PRIMARY KEY
// table_constraints row proves whether a PK object exists (tidb_pk_type
// cannot: NONCLUSTERED covers both PK-less tables and real nonclustered
// primaries), and only a single `primary`-fold row under a proven PK
// binds to the constraint object.
func TestT10R4TiDBPrimaryNameBindingMatrix(t *testing.T) {
	t.Parallel()
	base := func(columnRows, statRows [][]driver.Value) map[string]testQueryResult {
		return map[string]testQueryResult{
			"select engine, table_collation": {
				columns: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
				rows:    [][]driver.Value{{"InnoDB", "utf8mb4_bin", "", nil, "", nil, "BASE TABLE"}},
			},
			"information_schema.columns": {
				columns: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
				rows:    columnRows,
			},
			"column_name = 'IS_VISIBLE'": {
				columns: []string{"count"},
				rows:    [][]driver.Value{{1}},
			},
			"column_name = 'EXPRESSION'": {
				columns: []string{"count"},
				rows:    [][]driver.Value{{1}},
			},
			"information_schema.statistics": {
				columns: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation", "is_visible", "expression"},
				rows:    statRows,
			},
			"information_schema.partitions": {
				columns: []string{"partition_method", "partition_name", "subpartition_name"},
			},
		}
	}
	constraintRow := func(count driver.Value) testQueryResult {
		return testQueryResult{columns: []string{"count"}, rows: [][]driver.Value{{count}}}
	}
	colsID := [][]driver.Value{
		{"id", "int(11)", nil, nil, "", nil, "NO", "", nil},
		{"c", "int(11)", nil, nil, "", nil, "NO", "", nil},
	}
	pkRow := [][]driver.Value{{"PRIMARY", 0, "BTREE", "id", nil, nil, "A", "YES", nil}}
	memberPrimary := [][]driver.Value{
		{"primary", 1, "BTREE", "c", nil, nil, "A", "YES", nil},
	}
	cases := []struct {
		name           string
		queries        map[string]testQueryResult
		wantPK         bool
		wantMembers    int
		wantPKUnknown  bool
		wantHandleUnk  bool
		wantClusterUnk bool
		wantErr        bool
	}{
		{
			name:        "no PRIMARY KEY constraint: member primary stays a secondary (renamed member on a PK-less table)",
			queries:     withQuery(base(colsID, memberPrimary), "table_constraints", constraintRow(0)),
			wantMembers: 1,
		},
		{
			name: "PK constraint + single fold promotes to the constraint object",
			queries: withQuery(
				withQuery(base(colsID, pkRow), "table_constraints", constraintRow(1)),
				"information_schema.tidb_indexes",
				testQueryResult{columns: []string{"clustered"}, rows: [][]driver.Value{{"NO"}}}),
			wantPK:      true,
			wantMembers: 0,
		},
		{
			name: "PK constraint + unique PRIMARY fold plus member `primary` is the legal handle-table coexistence (verified v8.5.0: the member is dropped by name while the PK survives)",
			queries: withQuery(
				withQuery(base(colsID, append(append([][]driver.Value{}, pkRow...), memberPrimary...)), "table_constraints", constraintRow(1)),
				"information_schema.tidb_indexes",
				testQueryResult{columns: []string{"clustered"}, rows: [][]driver.Value{{"NO"}}}),
			wantPK:      true,
			wantMembers: 1,
		},
		{
			name:    "unproven constraint probe propagates as a provider error (issue #79: actual failures stay errors)",
			queries: base(colsID, pkRow),
			wantErr: true,
		},
		{
			name: "no primary-fold row and no PK constraint: provably PK-less member table",
			queries: withQuery(
				base(colsID, [][]driver.Value{{"s", 1, "BTREE", "c", nil, nil, "A", "YES", nil}}),
				"table_constraints", constraintRow(0)),
			wantMembers: 1,
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			db := openTestDB(t, tc.queries)
			defer db.Close()
			snapshot, err := NewProvider(db).LoadTableSnapshot(context.Background(), spec.DialectTiDB, "app", "t")
			if tc.wantErr {
				if err == nil {
					t.Fatalf("an unanswerable constraint probe must surface as a provider error, got %+v", snapshot)
				}
				return
			}
			if err != nil {
				t.Fatalf("LoadTableSnapshot: %v", err)
			}
			if (snapshot.PrimaryKey != nil) != tc.wantPK {
				t.Fatalf("PrimaryKey present = %v, want %v (pk=%+v)", snapshot.PrimaryKey != nil, tc.wantPK, snapshot.PrimaryKey)
			}
			if len(snapshot.Indexes) != tc.wantMembers {
				t.Fatalf("member count = %d, want %d (%+v)", len(snapshot.Indexes), tc.wantMembers, snapshot.Indexes)
			}
			if snapshot.PrimaryKeyUnknown != tc.wantPKUnknown ||
				snapshot.PrimaryKeyHandleUnknown != tc.wantHandleUnk ||
				snapshot.PrimaryKeyClusteredUnknown != tc.wantClusterUnk {
				t.Fatalf("unknowns = %v/%v/%v, want %v/%v/%v",
					snapshot.PrimaryKeyUnknown, snapshot.PrimaryKeyHandleUnknown, snapshot.PrimaryKeyClusteredUnknown,
					tc.wantPKUnknown, tc.wantHandleUnk, tc.wantClusterUnk)
			}
			if tc.wantPK && snapshot.PrimaryKey.Kind != spec.IndexKindPrimary {
				t.Fatalf("the promoted fold must carry primary kind, got %+v", snapshot.PrimaryKey)
			}
		})
	}
}

// Package mysql verifies the T10-R5 provider corrections: a PK object
// renamed off `primary` keeps its logical identity on reload (constraint
// presence and index-object attribution are judged separately — a proven
