// sqlBareWords returns the unquoted, uncommented word tokens of one SQL
// fragment — the parser adaptation layer's way to recover facts the PingCAP
// AST normalized away (CHECK vs CONSTRAINT spelling, an authored [NOT]
// ENFORCED clause) from the exact clause text the grammar consumed. Quoted
// identifiers and string literals contribute nothing; comments, including
// versioned /*! ... */ blocks, are skipped wholesale (their inner text is
// not trusted as a fact source). Input is guaranteed to have parsed, so
// unterminated constructs simply end the scan.
func sqlBareWords(text string) []string {
	words := make([]string, 0, 8)
	i, n := 0, len(text)
	for i < n {
		c := text[i]
		switch {
		case c == '\'' || c == '"' || c == '`':
			quote := c
			i++
			for i < n {
				if text[i] == '\\' && quote != '`' {
					i += 2
					continue
				}
				if text[i] == quote {
					if quote != '`' && i+1 < n && text[i+1] == quote {
						i += 2
						continue
					}
					i++
					break
				}
				i++
			}
		case c == '-' && dashDashOpensComment(text, i):
			for i < n && text[i] != '\n' {
				i++
			}
		case c == '#':
			for i < n && text[i] != '\n' {
				i++
			}
		case c == '/' && i+1 < n && text[i+1] == '*':
			i += 2
			for i+1 < n && (text[i] != '*' || text[i+1] != '/') {
				i++
			}
			if i+1 < n {
				i += 2
			}
		case isBareWordChar(c):
			start := i
			for i < n && isBareWordChar(text[i]) {
				i++
			}
			words = append(words, strings.ToLower(text[start:i]))
		default:
			i++
		}
	}
	return words
}

func isBareWordChar(c byte) bool {
	return c == '_' || c == '$' || ('0' <= c && c <= '9') || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

// checkSpellingForClause recovers whether one alter_check|drop_check
// action was authored as CHECK or as the generic CONSTRAINT alias: the
// spelling keyword is the word immediately after the action verb. The
// clause may still carry its ALTER TABLE <name> prefix (or be the whole
// raw statement when splitting could not align), so the answer is the
// first check|constraint word that directly follows an alter|drop verb —
// a table or constraint name spelled "check" elsewhere in the text is
// never preceded by a verb and cannot collide. Anything else answers ""
// — the spelling is then unproven, never guessed.
func checkSpellingForClause(clause string) string {
	words := sqlBareWords(clause)
	for i := 1; i < len(words); i++ {
		if words[i-1] != "alter" && words[i-1] != "drop" {
			continue
		}
		switch words[i] {
		case "check":
			return spec.CheckSpellingCheck
		case "constraint":
			return spec.CheckSpellingConstraint
		}
	}
	return ""
}

// clauseDeclaresEnforced reports whether the clause carries an authored
// [NOT] ENFORCED clause in binding position: a bare ENFORCED word must
// immediately follow the closing parenthesis of a CHECK(...) expression,
// optionally preceded by NOT. `enforced` is a legal non-reserved
// identifier — a word inside the CHECK expression, a column or constraint
// name, or a comment never declares the clause. Callers apply the answer
// at clause scope: a shared multi-member clause marks every declared
// member, which stays sound because an explicit clause refuses the whole
// statement on the one boundary where the fact matters (MySQL <8.0.16).
func clauseDeclaresEnforced(clause string) bool {
	i, n := 0, len(clause)
	for i < n {
		if next := skipCommentOrQuoted(clause, i); next > i {
			i = next
			continue
		}
		if !isBareWordChar(clause[i]) {
			i++
			continue
		}
		start := i
		for i < n && isBareWordChar(clause[i]) {
			i++
		}
		if strings.ToLower(clause[start:i]) != "check" {
			continue
		}
		open := skipSpaceAndComments(clause, i)
		if open >= n || clause[open] != '(' {
			continue
		}
		closeIdx, ok := matchingParenClose(clause, open)
		if !ok {
			return false
		}
		word, wordEnd, found := nextBareWordAfter(clause, closeIdx+1)
		if !found {
			continue
		}
		if word == "enforced" {
			return true
		}
		if word != "not" {
			continue
		}
		if word, _, found = nextBareWordAfter(clause, wordEnd); found && word == "enforced" {
			return true
		}
	}
	return false
}

// dashDashOpensComment reports whether the `--` at text[i] opens a MySQL
// line comment — only at end-of-input or when a whitespace/control
// character follows (the MySQL manual's comment syntax and the locked
// TiDB lexer's startWithDash rule). `v--1` is `v - -1`, never a comment,
// so the closing paren and an authored [NOT] ENFORCED clause after it
// still reach the attribution scan.
func dashDashOpensComment(text string, i int) bool {
	return i+1 < len(text) && text[i+1] == '-' &&
		(i+2 >= len(text) || unicode.IsSpace(rune(text[i+2])))
}

// skipCommentOrQuoted returns the index just past a comment or quoted
// section starting at i, or i itself when the position starts neither.
func skipCommentOrQuoted(text string, i int) int {
	n := len(text)
	switch text[i] {
	case '\'', '"', '`':
		quote := text[i]
		i++
		for i < n {
			if text[i] == '\\' && quote != '`' {
				i += 2
				continue
			}
			if text[i] == quote {
				if quote != '`' && i+1 < n && text[i+1] == quote {
					i += 2
					continue
				}
				return i + 1
			}
			i++
		}
		return i
	case '-':
		if dashDashOpensComment(text, i) {
			for i < n && text[i] != '\n' {
				i++
			}
			return i
		}
	case '#':
		for i < n && text[i] != '\n' {
			i++
		}
		return i
	case '/':
		if i+1 < n && text[i+1] == '*' {
			i += 2
			for i+1 < n && (text[i] != '*' || text[i+1] != '/') {
				i++
			}
			if i+1 < n {
				return i + 2
			}
			return n
		}
	}
	return i
}

// skipSpaceAndComments returns the first index at or after i that is
// neither whitespace nor comment text.
func skipSpaceAndComments(text string, i int) int {
	n := len(text)
	for i < n {
		c := text[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			i++
			continue
		}
		if next := skipCommentOrQuoted(text, i); next > i {
			i = next
			continue
		}
		break
	}
	return i
}

// matchingParenClose finds the ')' closing the '(' at open, skipping
// quoted and commented text. ok=false means the parens never balance.
func matchingParenClose(text string, open int) (int, bool) {
	depth := 0
	for i := open; i < len(text); i++ {
		if next := skipCommentOrQuoted(text, i); next > i {
			i = next - 1
			continue
		}
		switch text[i] {
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				return i, true
			}
		}
	}
	return 0, false
}

// nextBareWordAfter reads the first bare word at or after i, skipping
// whitespace and comments.
func nextBareWordAfter(text string, i int) (word string, end int, ok bool) {
	i = skipSpaceAndComments(text, i)
	if i >= len(text) || !isBareWordChar(text[i]) {
		return "", 0, false
	}
	start := i
	for i < len(text) && isBareWordChar(text[i]) {
		i++
	}
	return strings.ToLower(text[start:i]), i, true
}

// createCheckExplicitFlags splits the CREATE TABLE element list and marks
// which Constraints and Cols entries provably carried an authored
// ENFORCED token — the AST records neither the clause's presence nor the
// element boundary, so the comma-split element text (same splitter ALTER
// clauses use) is correlated by position: constraint elements consume the
// Constraints order, everything else consumes the Cols order. An
// unalignable body answers empty maps — the fact stays unproven rather
// than guessed.
func createCheckExplicitFlags(stmt *ast.CreateTableStmt, rawSQL string) (constraintExplicit, columnExplicit map[int]bool, attributed bool) {
	constraintExplicit = map[int]bool{}
	columnExplicit = map[int]bool{}
	body := createTableElementBody(rawSQL)
	if body == "" {
		return constraintExplicit, columnExplicit, false
	}
	elements := splitAlterTableClauses(body)
	if len(elements) != len(stmt.Cols)+len(stmt.Constraints) {
		return constraintExplicit, columnExplicit, false
	}
	constraintIdx, columnIdx := 0, 0
	for _, element := range elements {
		words := sqlBareWords(element)
		explicit := clauseDeclaresEnforced(element)
		if len(words) > 0 && createElementIsConstraint(words[0]) {
			if explicit {
				constraintExplicit[constraintIdx] = true
			}
			constraintIdx++
			continue
		}
		if explicit {
			columnExplicit[columnIdx] = true
		}
		columnIdx++
	}
	if constraintIdx != len(stmt.Constraints) || columnIdx != len(stmt.Cols) {
		return map[int]bool{}, map[int]bool{}, false
	}
	return constraintExplicit, columnExplicit, true
}

// createTableElementBody extracts the parenthesized element list of a
// CREATE TABLE statement — the first top-level (...) after the table
// name. Statements without an element list (LIKE, pure AS SELECT) answer "".
func createTableElementBody(rawSQL string) string {
	var quote byte
	depth := 0
	start := -1
	for i := 0; i < len(rawSQL); i++ {
		c := rawSQL[i]
		if quote != 0 {
			if c == '\\' && quote != '`' {
				i++
				continue
			}
			if c == quote {
				if quote != '`' && i+1 < len(rawSQL) && rawSQL[i+1] == quote {
					i++
					continue
				}
				quote = 0
			}
			continue
		}
		switch c {
		case '\'', '"', '`':
			quote = c
		case '-':
			if dashDashOpensComment(rawSQL, i) {
				for i < len(rawSQL) && rawSQL[i] != '\n' {
					i++
				}
			}
		case '#':
			for i < len(rawSQL) && rawSQL[i] != '\n' {
				i++
			}
		case '/':
			if i+1 < len(rawSQL) && rawSQL[i+1] == '*' {
				i += 2
				for i+1 < len(rawSQL) && (rawSQL[i] != '*' || rawSQL[i+1] != '/') {
					i++
				}
				if i+1 < len(rawSQL) {
					i++
				}
			}
		case '(':
			if depth == 0 {
				start = i + 1
			}
			depth++
		case ')':
			depth--
			if depth == 0 && start >= 0 {
				return rawSQL[start:i]
			}
		}
	}
	return ""
}

// createElementIsConstraint classifies a split element's first bare word:
// everything the grammar allows to open a table-level constraint or index
// clause consumes a Constraints slot; identifiers and column types fall
// through to the Cols order.
func createElementIsConstraint(word string) bool {
	switch word {
	case "constraint", "check", "primary", "unique", "key", "index", "foreign", "fulltext", "spatial", "vector":
		return true
	default:
		return false
	}
}

internal/infrastructure/parser/tidb/pars:
// Package tidbparser loads SQL text through the TiDB parser.
package tidbparser

import (
	"context"
	"fmt"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
	"github.com/pingcap/tidb/pkg/parser"
	"github.com/pingcap/tidb/pkg/parser/ast"
	_ "github.com/pingcap/tidb/pkg/parser/test_driver"
)

// Parser adapts TiDB parser behavior for DeltaScope.
type Parser struct{}

// Result is the infrastructure output of the parser adapter.
type Result struct {
	Statements []ast.StmtNode
	Warnings   []string
}

// New returns a TiDB-backed parser adapter.
func New() *Parser {
	return &Parser{}
}

// Parse parses SQL text into TiDB statements and preserves parser warnings.
func (p *Parser) Parse(ctx context.Context, sql string) (Result, error) {
	if err := ctx.Err(); err != nil {
		return Result{}, fmt.Errorf("parse cancelled: %w", err)
	}

	// Structural supplements run BEFORE the base parse: column-option
	// DEFAULT (<expr>) sites, column VISIBLE/INVISIBLE attributes, and the
	// narrow SET VISIBLE|INVISIBLE setter are planned from the token stream,
	// rewritten same-width, then rebound to typed facts on real AST nodes.
	// Any plan that does not bind exactly falls through to the untouched
	// base parse so failures keep their original diagnostics.
	var parsed []ast.StmtNode
	var warns []error
	header, viewHeaderOK := parseViewHeader(sql)
	if viewHeaderOK && (header.operation == spec.DDLOperationAlterView || header.declaration.CheckBare) {
		if view, viewWarns, ok := parseViewAdapter(ctx, sql); ok {
			parsed, warns = []ast.StmtNode{view}, viewWarns
		}
	}
	if parsed != nil {
		// The adapter owns the original statement and its parsed SELECT.
	} else if recovered, recoveredWarns, ok := runSupplementedParse(sql); ok {
		parsed, warns = recovered, recoveredWarns
	} else {
		var err error
		parsed, warns, err = parser.New().Parse(sql, "", "")
		if err != nil {
			return Result{}, fmt.Errorf("parse sql: %w", err)
		}
	}

	result := Result{
		Statements: make([]ast.StmtNode, 0, len(parsed)),
		Warnings:   make([]string, 0, len(warns)),
	}

	for _, warn := range warns {
		result.Warnings = append(result.Warnings, warn.Error())
	}

	result.Statements = append(result.Statements, parsed...)

	return result, nil
}

var _ spec.StatementExtractor = tidbExtractor{}

internal/interfaces/http/audit_provider_:
// Package http verifies the T06-A4 provider default-identity contract at the
// HTTP seam with the real mysqlmeta.Provider behind a controlled
// database/sql driver — one conservative A representative and one precise C
// representative; the full matrix lives in the shared layer and Golden runs.
package httpapi

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"io"
	"net/http"
	"strings"
	"sync"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
	mysqlmeta "github.com/Fanduzi/DeltaScope/internal/infrastructure/metadata/mysql"
	"github.com/Fanduzi/DeltaScope/pkg/deltascope"
)

// t06a4HTTPProvider adapts the real mysql provider to the public
// MetadataProvider interface; it never rewrites produced fields.
type t06a4HTTPProvider struct {
	inner *mysqlmeta.Provider
	calls []string
}

func (p *t06a4HTTPProvider) LoadInstanceFacts(ctx context.Context, _ deltascope.Dialect, schema string) (*deltascope.InstanceFacts, error) {
	return p.inner.LoadInstanceFacts(ctx, spec.DialectMySQL, schema)
}

func (p *t06a4HTTPProvider) LoadTableSnapshot(ctx context.Context, _ deltascope.Dialect, schema, table string) (*deltascope.TableSnapshot, error) {
	p.calls = append(p.calls, schema+"."+table)
	return p.inner.LoadTableSnapshot(ctx, spec.DialectMySQL, schema, table)
}

// --- controlled driver: only the queries the real provider issues ---

var (
	t06a4HTTPOnce  sync.Once
	t06a4HTTPState sync.Map
)

type t06a4HTTPDriver struct{}
type t06a4HTTPConn struct{ cDefault driver.Value }
type t06a4HTTPRows struct {
	cols  []string
	rows  [][]driver.Value
	index int
}

func openT06A4HTTPDB(t *testing.T, cDefault driver.Value) *sql.DB {
	t.Helper()
	t06a4HTTPOnce.Do(func() { sql.Register("t06a4-http-mysqlmeta", t06a4HTTPDriver{}) })
	name := "t06a4-http-" + strings.NewReplacer("/", "_", " ", "_").Replace(t.Name())
	t06a4HTTPState.Store(name, cDefault)
	db, err := sql.Open("t06a4-http-mysqlmeta", name)
	if err != nil {
		t.Fatalf("open driver db: %v", err)
	}
	t.Cleanup(func() {
		db.Close()
		t06a4HTTPState.Delete(name)
	})
	return db
}

func (t06a4HTTPDriver) Open(name string) (driver.Conn, error) {
	value, _ := t06a4HTTPState.Load(name)
	cDefault, _ := value.(driver.Value)
	return t06a4HTTPConn{cDefault: cDefault}, nil
}

func (t06a4HTTPConn) Prepare(string) (driver.Stmt, error) { return nil, driver.ErrSkip }
func (t06a4HTTPConn) Close() error                        { return nil }
func (t06a4HTTPConn) Begin() (driver.Tx, error)           { return nil, driver.ErrSkip }

func (c t06a4HTTPConn) QueryContext(_ context.Context, query string, _ []driver.NamedValue) (driver.Rows, error) {
	switch {
	case strings.Contains(query, "show variables"):
		return &t06a4HTTPRows{cols: []string{"Variable_name", "Value"}, rows: [][]driver.Value{{"version", "8.4.10"}}}, nil
	case strings.Contains(query, "constraint_type = 'CHECK'"):
		// T12 CHECK member projection — this fixture stores no checks.
		return &t06a4HTTPRows{cols: []string{"constraint_name", "enforced", "check_clause"}}, nil
	case strings.Contains(query, "column_name = 'ENFORCED'"), strings.Contains(query, "table_name = 'CHECK_CONSTRAINTS'"), strings.Contains(query, "table_name = 'TIDB_CHECK_CONSTRAINTS'"):
		// T12 catalog capability probes — this fixture predates them.
		return &t06a4HTTPRows{cols: []string{"count(*)"}, rows: [][]driver.Value{{int64(0)}}}, nil
	case strings.Contains(query, "information_schema.columns"):
		return &t06a4HTTPRows{
			cols: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows: [][]driver.Value{
				{"id", "int", nil, nil, "", nil, "NO", "", ""},
				{"a", "varchar(8)", nil, nil, "", nil, "YES", "", ""},
				{"b", "varchar(8)", nil, nil, "", nil, "YES", "", ""},
				{"c", "varchar(8)", nil, nil, "", c.cDefault, "YES", "", ""},
				{"d", "varchar(8)", nil, nil, "", "<nil>", "YES", "", ""},
			},
		}, nil
	case strings.Contains(query, "information_schema.statistics"):
		return &t06a4HTTPRows{
			cols: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows: [][]driver.Value{{"PRIMARY", int64(0), "BTREE", "id", nil, nil, "A"}},
		}, nil
	case strings.Contains(query, "constraint_type not in"):
		return &t06a4HTTPRows{
			cols: []string{"count"},
			rows: [][]driver.Value{{int64(0)}},
		}, nil
	case strings.Contains(query, "information_schema.referential_constraints"):
		return &t06a4HTTPRows{
			cols: []string{"constraint_name", "column_name", "referenced_table_schema", "referenced_table_name", "referenced_column_name", "delete_rule", "update_rule", "match_option"},
		}, nil
	case strings.Contains(query, "information_schema.tables"):
		return &t06a4HTTPRows{
			cols: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows: [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		}, nil
	}
	return nil, sql.ErrNoRows
}

func (r *t06a4HTTPRows) Columns() []string { return r.cols }
func (r *t06a4HTTPRows) Close() error      { return nil }
func (r *t06a4HTTPRows) Next(dest []driver.Value) error {
	if r.index >= len(r.rows) {
		return io.EOF
	}
	copy(dest, r.rows[r.index])
	r.index++
	return nil
}

const t06a4HTTPSQL = "ALTER TABLE t06_a4_defaults DROP COLUMN d;\nCREATE INDEX idx_b ON t06_a4_defaults(b);"

func t06a4HTTPPolicy(t *testing.T) string {
	t.Helper()
	return t06A3HTTPPolicy(t, map[string]bool{
		"ddl.table.exists.alter.require":          true,
		"ddl.alter.drop_column.exists.require":    true,
		"ddl.create_index.columns.exists.require": true,
	})
}

// TestHandlerT06A4ProviderTextNullStaysConservative is the A representative
// at the HTTP seam: a stored 'NULL' literal keeps the drop inside the
// conservative boundary — 200, review/unverified.
func TestHandlerT06A4ProviderTextNullStaysConservative(t *testing.T) {
	db := openT06A4HTTPDB(t, "NULL")
	provider := &t06a4HTTPProvider{inner: mysqlmeta.NewProvider(db)}
	code, payload := postT06A3Audit(t, t06a4HTTPPolicy(t), "mysql", t06a4HTTPSQL, provider)
	if code != http.StatusOK {
		t.Fatalf("http code = %d payload = %v, want 200", code, payload)
	}
	if payload["verdict"] != "review" {
		t.Fatalf("verdict = %v, want review", payload["verdict"])
	}
	if len(provider.calls) != 1 || provider.calls[0] != "golden.t06_a4_defaults" {
		t.Fatalf("provider calls = %#v, want exactly one load", provider.calls)
	}
}

// TestHandlerT06A4ProviderNullStaysPrecise is the C representative: stored
// SQL NULL keeps the precise drop path — 200, pass.
func TestHandlerT06A4ProviderNullStaysPrecise(t *testing.T) {
	db := openT06A4HTTPDB(t, nil)
	provider := &t06a4HTTPProvider{inner: mysqlmeta.NewProvider(db)}
	code, payload := postT06A3Audit(t, t06a4HTTPPolicy(t), "mysql", t06a4HTTPSQL, provider)
	if code != http.StatusOK {
		t.Fatalf("http code = %d payload = %v, want 200", code, payload)
	}
	if payload["verdict"] != "pass" {
		t.Fatalf("verdict = %v, want pass", payload["verdict"])
	}
}

pkg/deltascope/audit.go:
// Package deltascope exposes the public library surface for consumers.
package deltascope

import (
	"context"
	"errors"
	"fmt"

	appaudit "github.com/Fanduzi/DeltaScope/internal/application/audit"
	"github.com/Fanduzi/DeltaScope/internal/domain/report"
	"github.com/Fanduzi/DeltaScope/internal/domain/rule"
	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

// Dialect identifies the SQL dialect for public callers.
type Dialect string

const (
	DialectMySQL      Dialect = "mysql"
	DialectTiDB       Dialect = "tidb"
	DialectPostgreSQL Dialect = "postgresql"
)

var ErrUnsupportedStatement = errors.New("deltascope audit includes unsupported statements")

var (
	// ErrInvalidTargetVersion rejects a target_version that is not strict
	// [v]MAJOR.MINOR.PATCH syntax.
	ErrInvalidTargetVersion = appaudit.ErrInvalidTargetVersion
	// ErrTargetVersionMismatch rejects a target_version that contradicts the
	// observed live-server version.
	ErrTargetVersionMismatch = appaudit.ErrTargetVersionMismatch
	// ErrDialectProductMismatch rejects a request whose dialect contradicts
	// the product independently derived from the observed server banner.
	ErrDialectProductMismatch = appaudit.ErrDialectProductMismatch
)

// VersionIdentity mirrors the shared product/version fact projected on results.
type VersionIdentity = spec.VersionIdentity

// Verdict identifies the final public audit outcome.
type Verdict string

const (
	VerdictPass   Verdict = "pass"
	VerdictReview Verdict = "review"
	VerdictReject Verdict = "reject"
)

// Level identifies the public finding severity.
type Level string

const (
	LevelBlocker Level = "blocker"
	LevelWarning Level = "warning"
	LevelNotice  Level = "notice"
)

// Metadata mirrors the optional domain metadata facts exposed on statements.
type Metadata = spec.Metadata

// InstanceFacts mirror metadata-aware instance facts for public providers.
type InstanceFacts = spec.InstanceFacts

// TableSnapshot mirrors metadata-aware target table snapshots for public providers.
type TableSnapshot = spec.TableSnapshot

// ViewSnapshot carries private view-definition facts for metadata providers.
type ViewSnapshot = spec.ViewSnapshot

// ViewDefinition carries a normalized, non-executed view query.
type ViewDefinition = spec.ViewDefinition

// ViewColumnBinding describes one statically identified view output column.
type ViewColumnBinding = spec.ViewColumnBinding

// Table mirrors the domain table shape used inside metadata snapshots.
type Table = spec.Table

// Column mirrors the domain column shape used inside metadata snapshots.
type Column = spec.Column

// Index mirrors the domain index shape used inside metadata snapshots.
type Index = spec.Index

// Constraint mirrors the domain constraint shape used inside metadata snapshots.
type Constraint = spec.Constraint

// MetadataProvider supplies optional metadata-aware facts for one public audit request.
type MetadataProvider interface {
	LoadInstanceFacts(ctx context.Context, dialect Dialect, schema string) (*InstanceFacts, error)
	LoadTableSnapshot(ctx context.Context, dialect Dialect, schema string, table string) (*TableSnapshot, error)
}

// PlanEstimateProvider optionally supplies planner-backed DML impact estimates.
type PlanEstimateProvider interface {
	LoadPlanEstimate(ctx context.Context, statement spec.Statement) (*spec.ImpactEstimate, error)
}

// Request describes one public audit invocation.
type Request struct {
	SQL              string
	Dialect          Dialect
	ConfigPath       string
	Schema           string
	MetadataProvider MetadataProvider
	// TargetVersion optionally pins the audited server version as strict
	// [v]MAJOR.MINOR.PATCH. Empty means no version was supplied — it is never
	// defaulted. With a MetadataProvider it is only a constraint checked
	// against the observed identity; a mismatch returns ErrTargetVersionMismatch.
	TargetVersion string
}

// Summary captures high-level public audit counts.
type Summary struct {
	Statements int `json:"statements"`
	Blockers   int `json:"blockers"`
	Warnings   int `json:"warnings"`
	Notices    int `json:"notices"`
}

// CoverageStatus identifies the public audit-completeness state.
type CoverageStatus string

const (
	CoverageComplete   CoverageStatus = "complete"
	CoverageUnverified CoverageStatus = "unverified"
	CoverageIncomplete CoverageStatus = "incomplete"
)

// Coverage is the stable public coverage record for one result scope.
type Coverage struct {
	Status CoverageStatus `json:"status"`
}

// Location identifies a public source span when available.
type Location struct {
	Line   int `json:"line,omitempty"`
	Column int `json:"column,omitempty"`
}

// Explanation is the stable public result-level explanation shape.
type Explanation struct {
	Summary string   `json:"summary,omitempty"`
	Reasons []string `json:"reasons,omitempty"`
}

// ImpactSource identifies the public origin of a statement-level DML impact estimate.
type ImpactSource string

// ImpactRisk identifies the public conservative risk bucket for a DML statement.
type ImpactRisk string

// ImpactConfidence identifies the public estimate-confidence bucket.
type ImpactConfidence string

const (
	ImpactSourceShape    ImpactSource = "shape"
	ImpactSourceMetadata ImpactSource = "metadata"
	ImpactSourcePlan     ImpactSource = "plan"

	ImpactRiskLow     ImpactRisk = "low"
	ImpactRiskMedium  ImpactRisk = "medium"
	ImpactRiskHigh    ImpactRisk = "high"
	ImpactRiskUnknown ImpactRisk = "unknown"

	ImpactConfidenceLow    ImpactConfidence = "low"
	ImpactConfidenceMedium ImpactConfidence = "medium"
	ImpactConfidenceHigh   ImpactConfidence = "high"
)

// Impact is the stable public statement-level DML impact estimate shape.
type Impact struct {
	EstimatedRows  *int64           `json:"estimated_rows,omitempty"`
	EstimatedRatio *float64         `json:"estimated_ratio,omitempty"`
	RiskLevel      ImpactRisk       `json:"risk_level,omitempty"`
	Confidence     ImpactConfidence `json:"confidence,omitempty"`
	Source         ImpactSource     `json:"source,omitempty"`
	ReasonCodes    []string         `json:"reason_codes,omitempty"`
	Notes          []string         `json:"notes,omitempty"`
}

// ExplanationMetadata describes how metadata availability affected a public finding explanation.
type ExplanationMetadata struct {
	Status string `json:"status,omitempty"`
	Note   string `json:"note,omitempty"`
}

// FindingExplanation is the stable public per-finding explanation shape.
type FindingExplanation struct {
	Summary    string               `json:"summary,omitempty"`
	Why        string               `json:"why,omitempty"`
	Risk       string               `json:"risk,omitempty"`
	Suggestion string               `json:"suggestion,omitempty"`
	Metadata   *ExplanationMetadata `json:"metadata,omitempty"`
}

// EvidenceGap is the stable public evidence-gap shape: one enabled, applicable
// rule could not verify a statement because the listed metadata facts were
// unavailable. RequiredFacts is a bounded list of fixed fact identifiers.
type EvidenceGap struct {
	RuleID        string   `json:"rule_id"`
	ReasonCode    string   `json:"reason_code"`
	RequiredFacts []string `json:"required_facts,omitempty"`
}

// Finding is the stable public finding shape.
type Finding struct {
	RuleID         string              `json:"rule_id"`
	Level          Level               `json:"level"`
	Message        string              `json:"message"`
	StatementIndex int                 `json:"statement_index,omitempty"`
	StatementKind  string              `json:"statement_kind,omitempty"`
	Location       *Location           `json:"location,omitempty"`
	Suggestion     string              `json:"suggestion,omitempty"`
	Metadata       map[string]any      `json:"metadata,omitempty"`
	Explanation    *FindingExplanation `json:"explanation,omitempty"`
}

// StatementResult stores public findings for a single SQL statement.
type StatementResult struct {
	Index         int           `json:"index"`
	Kind          string        `json:"kind"`
	RawSQL        string        `json:"raw_sql,omitempty"`
	NormalizedSQL string        `json:"normalized_sql,omitempty"`
	Findings      []Finding     `json:"findings,omitempty"`
	EvidenceGaps  []EvidenceGap `json:"evidence_gaps,omitempty"`
	Impact        *Impact       `json:"impact,omitempty"`
	Coverage      Coverage      `json:"coverage"`
	Explanation   *Explanation  `json:"explanation,omitempty"`
}

// Result is the stable public audit output.
type Result struct {
	Verdict        Verdict                  `json:"verdict"`
	Coverage       Coverage                 `json:"coverage"`
	Summary        Summary                  `json:"summary"`
	Statements     []StatementResult        `json:"statements,omitempty"`
	GlobalFindings []Finding                `json:"global_findings,omitempty"`
	Unsupported    []spec.UnsupportedDetail `json:"unsupported,omitempty"`
	Explanation    *Explanation             `json:"explanation,omitempty"`
	Diagnostics    []spec.Diagnostic        `json:"diagnostics,omitempty"`
	// Version is the resolved canonical product/version identity when a
	// verified target or observed version fact exists; nil otherwise.
	Version *VersionIdentity `json:"version,omitempty"`
}

// Audit executes the stable public audit flow.
func Audit(ctx context.Context, request Request) (Result, error) {
	appRequest := appaudit.Request{
		SQL:        request.SQL,
		Dialect:    toDomainDialect(request.Dialect),
		ConfigPath: request.ConfigPath,
		Schema:     request.Schema,
	}
	if request.MetadataProvider != nil {
		appRequest.MetadataProvider = publicMetadataProvider{provider: request.MetadataProvider}
	}

	appRequest.TargetVersion = request.TargetVersion

	result, err := appaudit.AuditSQL(ctx, appRequest)
	publicResult := fromDomainResult(result)
	if err != nil {
		if errors.Is(err, appaudit.ErrUnsupportedStatement) {
			return publicResult, fmt.Errorf("%w: %v", ErrUnsupportedStatement, err)
		}
		if len(publicResult.Diagnostics) > 0 {
			return publicResult, err
		}
		return Result{}, err
	}

	return publicResult, nil
}

func toDomainDialect(dialect Dialect) spec.Dialect {
	switch dialect {
	case DialectTiDB:
		return spec.DialectTiDB
	case DialectPostgreSQL:
		return spec.DialectPostgreSQL
	case DialectMySQL, "":
		return spec.DialectMySQL
	default:
		return spec.Dialect(dialect)
	}
}

func fromDomainResult(result report.Result) Result {
	public := Result{
		Verdict:        Verdict(result.Verdict),
		Coverage:       Coverage{Status: CoverageStatus(result.Coverage.Status)},
		Summary:        Summary(result.Summary),
		Statements:     make([]StatementResult, 0, len(result.Statements)),
		GlobalFindings: make([]Finding, 0, len(result.GlobalFindings)),
		Unsupported:    append([]spec.UnsupportedDetail(nil), result.Unsupported...),
		Explanation:    fromDomainExplanation(result.Explanation),
		Diagnostics:    append([]spec.Diagnostic(nil), result.Diagnostics...),
		Version:        cloneVersionIdentity(result.Version),
	}

	for _, stmt := range result.Statements {
		public.Statements = append(public.Statements, StatementResult{
			Index:         stmt.Index,
			Kind:          stmt.Kind,
			RawSQL:        stmt.RawSQL,
			NormalizedSQL: stmt.NormalizedSQL,
			Findings:      fromDomainFindings(stmt.Findings),
			EvidenceGaps:  fromDomainEvidenceGaps(stmt.EvidenceGaps),
			Impact:        fromDomainImpact(stmt.Impact),
			Coverage:      Coverage{Status: CoverageStatus(stmt.Coverage.Status)},
			Explanation:   fromDomainExplanation(stmt.Explanation),
		})
	}

	public.GlobalFindings = fromDomainFindings(result.GlobalFindings)
	return public
}

func fromDomainFindings(findings []rule.Finding) []Finding {
	public := make([]Finding, 0, len(findings))
	for _, finding := range findings {
		item := Finding{
			RuleID:         finding.RuleID,
			Level:          Level(finding.Level),
			Message:        finding.Message,
			StatementIndex: finding.StatementIndex,
			StatementKind:  finding.StatementKind,
			Suggestion:     finding.Suggestion,
			Metadata:       cloneMetadataMap(finding.Metadata),
			Explanation:    fromDomainFindingExplanation(finding.Explanation),
		}
		if finding.Location != nil {
			item.Location = &Location{
				Line:   finding.Location.Line,
				Column: finding.Location.Column,
			}
		}
		public = append(public, item)
	}
	return public
}

func fromDomainEvidenceGaps(gaps []rule.EvidenceGap) []EvidenceGap {
	if len(gaps) == 0 {
		return nil
	}
	public := make([]EvidenceGap, 0, len(gaps))
	for _, gap := range gaps {
		public = append(public, EvidenceGap{
			RuleID:        gap.RuleID,
			ReasonCode:    gap.ReasonCode,
			RequiredFacts: append([]string(nil), gap.RequiredFacts...),
		})
	}
	return public
}

func fromDomainExplanation(explanation *report.Explanation) *Explanation {
	if explanation == nil {
		return nil
	}
	return &Explanation{
		Summary: explanation.Summary,
		Reasons: append([]string(nil), explanation.Reasons...),
	}
}

func fromDomainImpact(impact *report.Impact) *Impact {
	if impact == nil {
		return nil
	}
	return &Impact{
		EstimatedRows:  cloneInt64Ptr(impact.EstimatedRows),
		EstimatedRatio: cloneFloat64Ptr(impact.EstimatedRatio),
		RiskLevel:      ImpactRisk(impact.RiskLevel),
		Confidence:     ImpactConfidence(impact.Confidence),
		Source:         ImpactSource(impact.Source),
		ReasonCodes:    append([]string(nil), impact.ReasonCodes...),
		Notes:          append([]string(nil), impact.Notes...),
	}
}

func cloneMetadataMap(in map[string]any) map[string]any {
	if len(in) == 0 {
		return nil
	}
	out := make(map[string]any, len(in))
	for key, value := range in {
		out[key] = cloneMetadataValue(value)
	}
	return out
}

func cloneMetadataValue(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		return cloneMetadataMap(typed)
	case []any:
		out := make([]any, len(typed))
		for i := range typed {
			out[i] = cloneMetadataValue(typed[i])
		}
		return out
	case []map[string]any:
		out := make([]map[string]any, len(typed))
		for i := range typed {
			out[i] = cloneMetadataMap(typed[i])
		}
		return out
	case [][]string:
		out := make([][]string, len(typed))
		for i := range typed {
			out[i] = append([]string(nil), typed[i]...)
		}
		return out
	case []string:
		return append([]string(nil), typed...)
	case []int:
		return append([]int(nil), typed...)
	case []int64:
		return append([]int64(nil), typed...)
	case []float64:
		return append([]float64(nil), typed...)
	case []bool:
		return append([]bool(nil), typed...)
	default:
		return value
	}
}

func cloneInt64Ptr(value *int64) *int64 {
	if value == nil {
		return nil
	}
	cloned := *value
	return &cloned
}

func cloneFloat64Ptr(value *float64) *float64 {
	if value == nil {
		return nil
	}
	cloned := *value
	return &cloned
}

func cloneVersionIdentity(in *spec.VersionIdentity) *spec.VersionIdentity {
	if in == nil {
		return nil
	}
	out := *in
	return &out
}

func cloneInstanceFacts(in *spec.InstanceFacts) *spec.InstanceFacts {
	if in == nil {
		return nil
	}
	out := *in
	return &out
}

func cloneTableSnapshot(in *spec.TableSnapshot) *spec.TableSnapshot {
	if in == nil {
		return nil
	}
	out := *in
	out.View = spec.CloneViewSnapshot(in.View)
	if in.Table != nil {
		table := *in.Table
		out.Table = &table
	}
	if in.Columns != nil {
		out.Columns = make([]spec.Column, len(in.Columns))
		for i := range in.Columns {
			out.Columns[i] = cloneSpecColumn(in.Columns[i])
		}
	}
	if in.PrimaryKey != nil {
		out.PrimaryKey = cloneIndex(in.PrimaryKey)
	}
	out.Indexes = cloneIndexes(in.Indexes)
	out.Constraints = cloneConstraints(in.Constraints)
	if len(in.Options) > 0 {
		out.Options = make(map[string]string, len(in.Options))
		for key, value := range in.Options {
			out.Options[key] = value
		}
	} else {
		out.Options = nil
	}
	if in.Partitioned != nil {
		partitioned := *in.Partitioned
		out.Partitioned = &partitioned
	}
	if in.PartitionType != nil {
		partitionType := *in.PartitionType
		out.PartitionType = &partitionType
	}
	if in.PartitionNames != nil {
		out.PartitionNames = append([]string{}, in.PartitionNames...)
	}
	return &out
}

// cloneSpecColumn deep-copies one provider column so the request-owned
// snapshot never aliases provider-owned nested facts (identity/unextracted
// option collections and the T07 generated/default-expression records).
func cloneSpecColumn(in spec.Column) spec.Column {
	out := in
	if in.IdentityOptions != nil {
		out.IdentityOptions = make(map[string]any, len(in.IdentityOptions))
		for key, value := range in.IdentityOptions {
			out.IdentityOptions[key] = value
		}
	}
	out.UnextractedOptions = append([]string(nil), in.UnextractedOptions...)
	out.Generated = spec.CloneGeneratedColumn(in.Generated)
	out.DefaultExpression = spec.CloneExpressionFacts(in.DefaultExpression)
	out.DefaultLiteral = spec.CloneLiteralDefaultFacts(in.DefaultLiteral)
	return out
}

func cloneIndexes(in []spec.Index) []spec.Index {
	if in == nil {
		return nil
	}
	out := make([]spec.Index, len(in))
	for i := range in {
		out[i] = *cloneIndex(&in[i])
	}
	return out
}

func cloneIndex(in *spec.Index) *spec.Index {
	if in == nil {
		return nil
	}
	out := *in
	out.Columns = append([]string(nil), in.Columns...)
	out.Cardinality = cloneInt64Ptr(in.Cardinality)
	return &out
}

func cloneConstraints(in []spec.Constraint) []spec.Constraint {
	if in == nil {
		return nil
	}
	out := make([]spec.Constraint, len(in))
	for i := range in {
		out[i] = in[i]
		out[i].Columns = append([]string(nil), in[i].Columns...)
		out[i].ReferencedColumns = append([]string(nil), in[i].ReferencedColumns...)
	}
	return out
}

func fromDomainFindingExplanation(explanation *rule.FindingExplanation) *FindingExplanation {
	if explanation == nil {
		return nil
	}
	mapped := &FindingExplanation{
		Summary:    explanation.Summary,
		Why:        explanation.Why,
		Risk:       explanation.Risk,
		Suggestion: explanation.Suggestion,
	}
	if explanation.Metadata != nil {
		mapped.Metadata = &ExplanationMetadata{
			Status: explanation.Metadata.Status,
			Note:   explanation.Metadata.Note,
		}
	}
	return mapped
}

type publicMetadataProvider struct {
	provider MetadataProvider
}

type internalIndexOwnerResolver interface {
	ResolveTableForIndex(ctx context.Context, dialect Dialect, schema string, index string) (string, error)
}

func (p publicMetadataProvider) LoadInstanceFacts(ctx context.Context, dialect spec.Dialect, schema string) (*spec.InstanceFacts, error) {
	if p.provider == nil {
		return nil, nil
	}
	instanceFacts, err := p.provider.LoadInstanceFacts(ctx, Dialect(dialect), schema)
	if err != nil {
		return nil, err
	}
	return cloneInstanceFacts(instanceFacts), nil
}

func (p publicMetadataProvider) LoadTableSnapshot(ctx context.Context, dialect spec.Dialect, schema string, table string) (*spec.TableSnapshot, error) {
	if p.provider == nil {
		return nil, nil
	}
	snapshot, err := p.provider.LoadTableSnapshot(ctx, Dialect(dialect), schema, table)
	if err != nil {
		return nil, err
	}
	return cloneTableSnapshot(snapshot), nil
}

func (p publicMetadataProvider) ResolveTableForIndex(ctx context.Context, dialect spec.Dialect, schema string, index string) (string, error) {
	if p.provider == nil {
		return "", nil
	}
	resolver, ok := p.provider.(internalIndexOwnerResolver)
	if !ok {
		return "", nil
	}
	return resolver.ResolveTableForIndex(ctx, Dialect(dialect), schema, index)
}

func (p publicMetadataProvider) LoadPlanEstimate(ctx context.Context, statement spec.Statement) (*spec.ImpactEstimate, error) {
	if p.provider == nil {
		return nil, nil
	}
	provider, ok := p.provider.(PlanEstimateProvider)
	if !ok {
		return nil, nil
	}
	estimate, err := provider.LoadPlanEstimate(ctx, statement)
	if err != nil {
		return nil, err
	}
	if estimate == nil {
		return nil, nil
	}
	cloned := *estimate
	cloned.EstimatedRows = cloneInt64Ptr(estimate.EstimatedRows)
	cloned.EstimatedRatio = cloneFloat64Ptr(estimate.EstimatedRatio)
	cloned.ReasonCodes = append([]string(nil), estimate.ReasonCodes...)
	cloned.Notes = append([]string(nil), estimate.Notes...)
	return &cloned, nil
}

func (p publicMetadataProvider) ResolveObject(ctx context.Context, dialect spec.Dialect, request spec.ObjectLookupRequest) (*spec.ObjectSnapshot, error) {
	if p.provider == nil {
		return &spec.ObjectSnapshot{
			Schema: request.Schema,
			Type:   request.Type,
			Name:   request.Name,
			Status: spec.MetadataStatusUnavailable,
		}, nil
	}
	type objectResolver interface {
		ResolveObject(context.Context, spec.Dialect, spec.ObjectLookupRequest) (*spec.ObjectSnapshot, error)
	}
	resolver, ok := p.provider.(objectResolver)
	if !ok {
		return &spec.ObjectSnapshot{
			Schema: request.Schema,
			Type:   request.Type,
			Name:   request.Name,
			Status: spec.MetadataStatusUnavailable,
		}, nil
	}
	return resolver.ResolveObject(ctx, dialect, request)
}

pkg/deltascope/audit_provider_defaults_t:
// Package deltascope verifies the T06-A4 provider default-identity contract at
// the public SDK seam with the real mysqlmeta.Provider behind a controlled
// database/sql driver — one conservative A representative and one precise C
// representative; the full matrix lives in the shared layer and Golden runs.
package deltascope

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"io"
	"strings"
	"sync"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
	mysqlmeta "github.com/Fanduzi/DeltaScope/internal/infrastructure/metadata/mysql"
)

// t06a4SDKProvider adapts the real mysql provider to the public
// MetadataProvider interface; it never rewrites produced fields.
type t06a4SDKProvider struct {
	inner *mysqlmeta.Provider
	calls []string
}

func (p *t06a4SDKProvider) LoadInstanceFacts(ctx context.Context, _ Dialect, schema string) (*InstanceFacts, error) {
	return p.inner.LoadInstanceFacts(ctx, spec.DialectMySQL, schema)
}

func (p *t06a4SDKProvider) LoadTableSnapshot(ctx context.Context, _ Dialect, schema, table string) (*TableSnapshot, error) {
	p.calls = append(p.calls, schema+"."+table)
	return p.inner.LoadTableSnapshot(ctx, spec.DialectMySQL, schema, table)
}

// --- controlled driver: only the queries the real provider issues ---

var (
	t06a4SDKOnce  sync.Once
	t06a4SDKState sync.Map
)

type t06a4SDKDriver struct{}
type t06a4SDKConn struct{ cDefault driver.Value }
type t06a4SDKRows struct {
	cols  []string
	rows  [][]driver.Value
	index int
}

func openT06A4SDKDB(t *testing.T, cDefault driver.Value) *sql.DB {
	t.Helper()
	t06a4SDKOnce.Do(func() { sql.Register("t06a4-sdk-mysqlmeta", t06a4SDKDriver{}) })
	name := "t06a4-sdk-" + strings.NewReplacer("/", "_", " ", "_").Replace(t.Name())
	t06a4SDKState.Store(name, cDefault)
	db, err := sql.Open("t06a4-sdk-mysqlmeta", name)
	if err != nil {
		t.Fatalf("open driver db: %v", err)
	}
	t.Cleanup(func() {
		db.Close()
		t06a4SDKState.Delete(name)
	})
	return db
}

func (t06a4SDKDriver) Open(name string) (driver.Conn, error) {
	value, _ := t06a4SDKState.Load(name)
	cDefault, _ := value.(driver.Value)
	return t06a4SDKConn{cDefault: cDefault}, nil
}

func (t06a4SDKConn) Prepare(string) (driver.Stmt, error) { return nil, driver.ErrSkip }
func (t06a4SDKConn) Close() error                        { return nil }
func (t06a4SDKConn) Begin() (driver.Tx, error)           { return nil, driver.ErrSkip }

func (c t06a4SDKConn) QueryContext(_ context.Context, query string, _ []driver.NamedValue) (driver.Rows, error) {
	switch {
	case strings.Contains(query, "show variables"):
		return &t06a4SDKRows{cols: []string{"Variable_name", "Value"}, rows: [][]driver.Value{{"version", "8.4.10"}}}, nil
	case strings.Contains(query, "constraint_type = 'CHECK'"):
		// T12 CHECK member projection — this fixture stores no checks.
		return &t06a4SDKRows{cols: []string{"constraint_name", "enforced", "check_clause"}}, nil
	case strings.Contains(query, "column_name = 'ENFORCED'"), strings.Contains(query, "table_name = 'CHECK_CONSTRAINTS'"), strings.Contains(query, "table_name = 'TIDB_CHECK_CONSTRAINTS'"):
		// T12 catalog capability probes — this fixture predates them.
		return &t06a4SDKRows{cols: []string{"count(*)"}, rows: [][]driver.Value{{int64(0)}}}, nil
	case strings.Contains(query, "information_schema.columns"):
		return &t06a4SDKRows{
			cols: []string{"column_name", "column_type", "character_set_name", "collation_name", "column_comment", "column_default", "is_nullable", "extra", "generation_expression"},
			rows: [][]driver.Value{
				{"id", "int", nil, nil, "", nil, "NO", "", ""},
				{"a", "varchar(8)", nil, nil, "", nil, "YES", "", ""},
				{"b", "varchar(8)", nil, nil, "", nil, "YES", "", ""},
				{"c", "varchar(8)", nil, nil, "", c.cDefault, "YES", "", ""},
				{"d", "varchar(8)", nil, nil, "", "<nil>", "YES", "", ""},
			},
		}, nil
	case strings.Contains(query, "information_schema.statistics"):
		return &t06a4SDKRows{
			cols: []string{"index_name", "non_unique", "index_type", "column_name", "cardinality", "sub_part", "collation"},
			rows: [][]driver.Value{{"PRIMARY", int64(0), "BTREE", "id", nil, nil, "A"}},
		}, nil
	case strings.Contains(query, "constraint_type not in"):
		return &t06a4SDKRows{
			cols: []string{"count"},
			rows: [][]driver.Value{{int64(0)}},
		}, nil
	case strings.Contains(query, "information_schema.referential_constraints"):
		return &t06a4SDKRows{
			cols: []string{"constraint_name", "column_name", "referenced_table_schema", "referenced_table_name", "referenced_column_name", "delete_rule", "update_rule", "match_option"},
		}, nil
	case strings.Contains(query, "information_schema.tables"):
		return &t06a4SDKRows{
			cols: []string{"engine", "table_collation", "table_comment", "auto_increment", "row_format", "table_rows", "table_type"},
			rows: [][]driver.Value{{"InnoDB", "utf8mb4_general_ci", "", nil, "Dynamic", int64(0), "BASE TABLE"}},
		}, nil
	}
	return nil, sql.ErrNoRows
}

func (r *t06a4SDKRows) Columns() []string { return r.cols }
func (r *t06a4SDKRows) Close() error      { return nil }
func (r *t06a4SDKRows) Next(dest []driver.Value) error {
	if r.index >= len(r.rows) {
		return io.EOF
	}
	copy(dest, r.rows[r.index])
	r.index++
	return nil
}

const t06a4SDKSQL = "ALTER TABLE t06_a4_defaults DROP COLUMN d;\nCREATE INDEX idx_b ON t06_a4_defaults(b);"

func t06a4SDKPolicy(t *testing.T) string {
	t.Helper()
	return t06A3SDKPolicy(t, map[string]bool{
		"ddl.table.exists.alter.require":          true,
		"ddl.alter.drop_column.exists.require":    true,
		"ddl.create_index.columns.exists.require": true,
	})
}

// TestT06A4ProviderTextNullStaysConservative is the A representative at the
// SDK seam: the stored 'NULL' literal on c keeps the drop inside the A6
// conservative boundary — review/unverified with one index gap.
func TestT06A4ProviderTextNullStaysConservative(t *testing.T) {
	db := openT06A4SDKDB(t, "NULL")
	provider := &t06a4SDKProvider{inner: mysqlmeta.NewProvider(db)}
	result, err := Audit(context.Background(), Request{
		SQL: t06a4SDKSQL, Dialect: DialectMySQL, Schema: "golden",
		ConfigPath: t06a4SDKPolicy(t), MetadataProvider: provider,
	})
	if err != nil {
		t.Fatalf("audit: %v", err)
	}
	if result.Verdict != VerdictReview || result.Coverage.Status != "unverified" {
		t.Fatalf("aggregate = %s/%s, want review/unverified", result.Verdict, result.Coverage.Status)
	}
	if len(provider.calls) != 1 || provider.calls[0] != "golden.t06_a4_defaults" {
		t.Fatalf("provider calls = %#v, want exactly one load", provider.calls)
	}
}

// TestT06A4ProviderNullStaysPrecise is the C representative: the stored SQL
// NULL default keeps the precise drop path — pass/complete, err nil.
func TestT06A4ProviderNullStaysPrecise(t *testing.T) {
	db := openT06A4SDKDB(t, nil)
	provider := &t06a4SDKProvider{inner: mysqlmeta.NewProvider(db)}
	result, err := Audit(context.Background(), Request{
		SQL: t06a4SDKSQL, Dialect: DialectMySQL, Schema: "golden",
		ConfigPath: t06a4SDKPolicy(t), MetadataProvider: provider,
	})
	if err != nil {
		t.Fatalf("audit: %v", err)
	}
	if result.Verdict != VerdictPass || result.Coverage.Status != "complete" {
		t.Fatalf("aggregate = %s/%s, want pass/complete", result.Verdict, result.Coverage.Status)
	}
	if len(provider.calls) != 1 || provider.calls[0] != "golden.t06_a4_defaults" {
		t.Fatalf("provider calls = %#v, want exactly one load", provider.calls)
	}
}

pkg/deltascope/audit_unsupported_diagnos:
// Package deltascope verifies public SDK diagnostic result contracts.
package deltascope

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/Fanduzi/DeltaScope/internal/domain/spec"
)

func TestUnsupportedDiagnosticsEvidenceSDKParserError(t *testing.T) {
	t.Parallel()

	result, err := Audit(context.Background(), Request{
		SQL:     "CREATE FUNCTION hello() RETURNS VARCHAR(20) RETURN 'secret_body_value'",
		Dialect: DialectMySQL,
	})
	if err == nil {
		t.Fatalf("expected parser-error diagnostic, got nil error and result=%#v", result)
	}

	if len(result.Diagnostics) == 0 {
		t.Fatalf("expected at least one diagnostic, got none")
	}

	var pe *spec.Diagnostic
	for i := range result.Diagnostics {
		if result.Diagnostics[i].Classification == "parser_error" {
			pe = &result.Diagnostics[i]
			break
		}
	}
	if pe == nil {
		t.Fatalf("expected parser_error diagnostic, got %#v", result.Diagnostics)
	}

	if !strings.Contains(pe.Reason, "not audited") {
		t.Fatalf("expected reason containing 'not audited', got %q", pe.Reason)
	}
	if !strings.Contains(pe.ActionHint, "verify the selected dialect") {
		t.Fatalf("expected action_hint containing 'verify the selected dialect', got %q", pe.ActionHint)
	}
	if pe.Audited {
		t.Fatal("parser-error diagnostic must mark audited=false")
	}
	if pe.Dialect != "mysql" {
		t.Fatalf("expected dialect mysql, got %q", pe.Dialect)
	}

	if len(result.Statements) != 0 {
		t.Fatalf("parser-error SQL must not produce statement results: %#v", result.Statements)
	}
	if len(result.GlobalFindings) != 0 {
		t.Fatalf("parser-error SQL must not produce global findings: %#v", result.GlobalFindings)
	}

	combined := pe.Reason + pe.ActionHint + pe.Dialect + err.Error()
	if strings.Contains(combined, "secret_body_value") {
		t.Fatalf("SDK diagnostic leaked forbidden payload: %q", combined)
	}
	if strings.Contains(strings.ToLower(combined), "near ") {
		t.Fatalf("SDK diagnostic leaked raw parser fragment: %q", combined)
	}

	msg := strings.ToLower(err.Error())
	if !strings.Contains(msg, "not audited") {
		t.Fatalf("v0.220.0 error contract: expected 'not audited', got %q", err.Error())
	}
}

func TestAuditParserErrorPreservesPartialSDKResult(t *testing.T) {
	t.Parallel()

	result, err := Audit(context.Background(), Request{
		SQL: "ALTER TABLE users DROP COLUMN email;\n" +
			"CREATE INDEX CONCURRENTLY idx_users_name ON users(name);\n" +
			"DELETE FROM users WHERE id = 1;",
		Dialect: DialectMySQL,
	})
	if err == nil {
		t.Fatal("expected parser-error result to remain non-nil")
	}
	if len(result.Statements) != 2 || result.Summary.Statements != 2 {
		t.Fatalf("expected two audited statements, got %#v", result.Statements)
	}
	if result.Verdict != VerdictReview {
		t.Fatalf("expected parser-error review floor, got %q", result.Verdict)
	}
	foundDropColumnNotice := false
	for _, finding := range result.Statements[0].Findings {
		foundDropColumnNotice = foundDropColumnNotice || finding.RuleID == "ddl.alter.drop_column.notice"
	}
	if !foundDropColumnNotice {
		t.Fatalf("expected retained DROP COLUMN notice, got %#v", result.Statements[0].Findings)
	}
	if result.Statements[1].Impact == nil {
		t.Fatalf("expected trailing DELETE impact to be preserved, got %#v", result.Statements[1])
	}
	if len(result.Diagnostics) != 1 || result.Diagnostics[0].Line != 2 || result.Diagnostics[0].Column != 1 {
		t.Fatalf("expected one located parser diagnostic, got %#v", result.Diagnostics)
	}
	payload, marshalErr := json.Marshal(result)
	if marshalErr != nil {
		t.Fatalf("marshal public result: %v", marshalErr)
	}
	if strings.Contains(string(payload), "idx_users_name") {
		t.Fatalf("public result leaked invalid SQL text: %s", payload)
	}
}

func TestUnsupportedDiagnosticsGuidanceCodeSDKMySQL(t *testing.T) {
	t.Parallel()

	result, err := Audit(context.Background(), Request{
		SQL:     "ALTER PROCEDURE v_users COMMENT 'x'",
		Dialect: DialectMySQL,
	})
	if err == nil {
		t.Fatalf("expected parser-error diagnostic, got nil error and result=%#v", result)
	}

	if len(result.Diagnostics) == 0 {
		t.Fatal("expected at least one diagnostic")
	}

	var pe *spec.Diagnostic
	for i := range result.Diagnostics {
		if result.Diagnostics[i].Classification == "parser_error" {
			pe = &result.Diagnostics[i]
			break
		}
	}
	if pe == nil {
		t.Fatalf("expected parser_error diagnostic, got %#v", result.Diagnostics)
	}

	if pe.Audited {
		t.Fatal("parser-error diagnostic must mark audited=false")
	}
	if pe.Dialect != "mysql" {
		t.Fatalf("expected dialect mysql, got %q", pe.Dialect)
	}

	if pe.GuidanceCode != "parser_upgrade_candidate" {
		t.Fatalf("expected guidance_code parser_upgrade_candidate, got %q", pe.GuidanceCode)
	}

	const expectedRef = "https://github.com/Fanduzi/DeltaScope/blob/main/docs/reference/cli.md#parser-upgrade-candidate-evidence-v02500"
	if pe.EvidenceRef != expectedRef {
		t.Fatalf("expected evidence_ref %q, got %q", expectedRef, pe.EvidenceRef)
	}
	if !strings.HasPrefix(pe.EvidenceRef, "https://github.com/Fanduzi/DeltaScope/") {
		t.Fatalf("evidence_ref must start with GitHub base URL, got %q", pe.EvidenceRef)
	}

	if strings.Contains(pe.EvidenceRef, "v_users") {
		t.Fatal("evidence_ref must not contain raw SQL object names")
	}
	if strings.Contains(pe.GuidanceCode+pe.EvidenceRef+pe.Reason+pe.ActionHint, "v_users") {
		t.Fatal("diagnostic fields must not contain raw SQL object names")
	}
	combined := pe.GuidanceCode + pe.EvidenceRef + pe.Reason + pe.ActionHint + err.Error()
	if strings.Contains(strings.ToLower(combined), "near ") {
		t.Fatalf("SDK diagnostic leaked raw parser fragment: %q", combined)
	}
}

