			t.Fatal(err)
		}
		result, err := EvaluateStatements(context.Background(), registry, statements)
		if err != nil || registry.LoadedStatementRuleCount() != tc.loaded ||
			!reflect.DeepEqual(statements[1].Metadata.View.Sources[0].Snapshot, prior) {
